// ============================================================================
// Deterministic language detection for SYSTEM messages — Checkpoint D2.
//
// WHY THIS IS NOT A MODEL CALL
// The handoff note is the message sent when the Concierge cannot answer: the
// model refused, returned unparseable JSON twice, or produced a reply that had
// to be discarded. It is the one message that must still work *when the model
// has failed*, which rules out asking a model — either to write it or to say
// what language to write it in.
//
// So: fixed strings from config, keyed by language, chosen by the rules below.
//
// This is a classifier for THREE known languages on SHORT messages, not a
// general-purpose one. It is allowed to be unsure, and being unsure is safe:
// an undecided result falls back to the client's configured default rather
// than guessing. Sending Portuguese to a Portuguese lead is the win; sending
// Spanish to a Portuguese lead because two words matched is worse than the
// English we send today.
// ============================================================================

// Accented and punctuation marks that occur in ONE of the three languages and
// effectively settle it on their own. Checked before normalisation, because
// stripping diacritics destroys exactly the signal that discriminates pt from
// es -- the two languages that actually get confused.
const HARD_MARKERS = [
  { lang: 'pt', rx: /[ãõ]/, weight: 6 },          // não, mão, então, opções
  { lang: 'pt', rx: /ç/, weight: 5 },             // preço, começar
  { lang: 'es', rx: /ñ/, weight: 6 },             // mañana, año, señor
  { lang: 'es', rx: /[¿¡]/, weight: 6 },          // inverted punctuation
];

// Function words and greetings. Deliberately excludes anything the three share
// (que, para, no, si/sim, por favor, esta) -- a shared word is not evidence.
// Function words. Only DISCRIMINATING tokens: anything the languages share
// (que, para, no, casa, como, por favor) is not evidence and is excluded.
// The pt/es minimal pairs do most of the work here -- com/con, uma/una,
// quando/cuando, muito/mucho -- because those two are the pair that actually
// gets confused.
const WORD_MARKERS = {
  pt: ['nao', 'obrigado', 'obrigada', 'ola', 'voce', 'gostaria', 'queria',
       'muito', 'estou', 'tenho', 'tem', 'quero', 'bom dia', 'boa tarde',
       'boa noite', 'feira', 'imovel', 'imoveis', 'moradia', 'preciso',
       'gostava', 'entao', 'onde', 'com', 'uma', 'um', 'quando', 'quanto',
       'qual', 'mais', 'na', 'nas', 'dos', 'das', 'ate', 'posso', 'pode',
       'procuro', 'visitar', 'marcar', 'falar', 'pessoa', 'afinal', 'mudar',
       // 2026-09-21: weekdays and parts of the day that only pt uses. es says
       // lunes..viernes, and sabado/domingo/tarde are shared, so they stay out.
       'segunda', 'terca', 'quarta', 'quinta', 'sexta', 'manha', 'amanha',
       'fica', 'serve', 'combinado', 'perfeito', 'otimo'],
  es: ['hola', 'gracias', 'quisiera', 'usted', 'tambien', 'buenos dias',
       'buenas tardes', 'buenas noches', 'vivienda', 'piso', 'necesito',
       'busco', 'con', 'una', 'cuando', 'cuanto', 'donde', 'ahora', 'manana',
       'el', 'los', 'las', 'muy', 'mucho', 'estoy', 'tengo', 'puedo',
       'hablar', 'jueves', 'viernes', 'quiero',
       // 2026-09-21: the other weekdays es alone uses, and short replies.
       'lunes', 'martes', 'miercoles', 'viene', 'vale', 'perfecto', 'genial'],
  en: ['the', 'and', 'you', 'are', 'is', 'would', 'like', 'hello', 'hi',
       'thanks', 'thank', 'please', 'can', 'i', 'im', 'looking', 'house',
       'flat', 'apartment', 'available', 'viewing', 'week', 'time', 'do',
       'have', 'see', 'come', 'speak', 'person', 'anything', 'something',
       // 2026-09-21: "Ok let's go with Thursday morning" scored 0 in every
       // language, so no REPLY LANGUAGE note was sent and 4 of 5 replies came
       // back in Portuguese. A booking reply is short and made of exactly these
       // words: weekdays, parts of the day, and the function words around them.
       // Only words pt and es never use: not 'ok', 'no', 'me', 'a' or 'sim'.
       'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday',
       'sunday', 'morning', 'afternoon', 'evening', 'tonight', 'tomorrow',
       'today', 'next', 'lets', "let's", 'go', 'with', 'works', 'sounds',
       'good', 'great', 'perfect', 'that', 'this', 'what', 'when', 'which',
       'at', 'for', 'yes', 'sure', 'fine', 'its', "it's", 'how', 'about'],
};

const SUPPORTED = ['pt', 'en', 'es'];

// detectLanguage(text) -> {lang: 'pt'|'en'|'es'|null, scores, confident}
// Returns null when the evidence is thin or the top two are close. Callers
// must treat null as "use the configured default", never as a language.
function detectLanguage(text) {
  const raw = String(text || '');
  const out = (lang, scores, confident) => ({ lang, scores, confident });
  if (!raw.trim()) return out(null, { pt: 0, en: 0, es: 0 }, false);

  // Typographic apostrophes folded to ' (21 Sep 2026): a phone keyboard turns
  // "let's" into "let’s" (U+2019), and the word pass below kept only [a-z0-9'],
  // so "let’s" became "let s" and matched neither "let's" nor "lets".
  const lower = raw.replace(/[\u2018\u2019\u201B\u02BC\u2032\uFF07\u00B4\u0060]/g, "'").toLowerCase();
  const scores = { pt: 0, en: 0, es: 0 };

  for (const m of HARD_MARKERS) {
    if (m.rx.test(lower)) scores[m.lang] += m.weight;
  }

  // Normalise for word matching so "voce"/"você" and "manana"/"mañana" both
  // land, having already banked the diacritic evidence above.
  const flat = ' ' + lower.normalize('NFD').replace(/[̀-ͯ]/g, '')
                          .replace(/[^a-z0-9']+/g, ' ').trim() + ' ';
  for (const lang of SUPPORTED) {
    for (const w of WORD_MARKERS[lang]) {
      const needle = w.includes(' ') ? w : ' ' + w + ' ';
      if (flat.includes(needle)) scores[lang] += 2;
    }
  }

  const ranked = SUPPORTED.slice().sort((a, b) => scores[b] - scores[a]);
  const top = ranked[0], second = ranked[1];
  // A single weak hit decides nothing, and a near-tie between pt and es is the
  // case most likely to be wrong. Both fall back rather than guess.
  // Two ways to be sure, and they cover different shapes of message:
  //   - unopposed: any evidence at all for exactly one language, none for the
  //     others. "Ola, procuro casa em Cascais" is short but unambiguous.
  //   - contested: enough evidence AND a clear margin. This is the pt/es case,
  //     where both score and the winner has to actually win.
  // Everything else falls back to the configured default rather than guessing.
  const unopposed = scores[top] >= 2 && scores[second] === 0;
  const contested = scores[top] >= 4 && (scores[top] - scores[second]) >= 4;
  const confident = unopposed || contested;
  return out(confident ? top : null, scores, confident);
}

// resolveLeadLanguage(text, priorInbound) -> {lang, source}
//
// The language to STATE for this reply. 2026-09-21: the current message alone
// decided it, and a short reply the detector cannot read ("ok, Thursday 15h")
// stated nothing, so the model drifted to the prompt's Portuguese. A lead does
// not change language by writing briefly, so an undecided message inherits the
// language of the lead's most recent message that WAS decided.
//   source: 'message'  the current message decided it
//           'history'  inherited from an earlier inbound message
//           null       nothing decided it (a first message the detector
//                      cannot read), and nothing is stated
// `priorInbound` is the lead's earlier messages as text, NEWEST FIRST. Only
// the lead's own words count: the assistant writes in whatever it was told,
// so its messages are not evidence of the lead's language.
function resolveLeadLanguage(text, priorInbound) {
  const now = detectLanguage(text);
  if (now.lang) return { lang: now.lang, source: 'message' };
  for (const t of (Array.isArray(priorInbound) ? priorInbound : [])) {
    const d = detectLanguage(t);
    if (d.lang) return { lang: d.lang, source: 'history' };
  }
  return { lang: null, source: null };
}

// pickMessage(messages, lang, fallbackLang) -> string|null
//
// `messages` is the config map, e.g. {pt: '...', en: '...', es: '...'}. Resolution
// order is: detected language -> the client's configured default -> English ->
// whatever single string was configured. Every step is a fixed string; nothing
// here is generated.
function pickMessage(messages, lang, fallbackLang) {
  if (typeof messages === 'string') return messages;          // legacy single string
  if (!messages || typeof messages !== 'object') return null;
  const order = [lang, fallbackLang, 'en', 'pt'];
  for (const k of order) {
    if (k && typeof messages[k] === 'string' && messages[k].trim()) return messages[k];
  }
  const first = Object.values(messages).find(v => typeof v === 'string' && v.trim());
  return first || null;
}

// Convenience: resolve a named system message for a lead's text in one call.
// `cfg` is client_automations.config.
//
// `priorInbound` (optional, 2026-09-21): the lead's earlier messages, NEWEST
// FIRST. An English lead who asks for a person in words the lists cannot read
// ("Talk to a human") inherits English from history (resolveLeadLanguage)
// rather than getting the client's default. `detected` stays the current
// message's own verdict, and `source` says where `lang` came from:
// 'message' | 'history' | null (the configured default).
function systemMessage(cfg, name, leadText, priorInbound) {
  const c = cfg || {};
  const det = detectLanguage(leadText);
  const res = resolveLeadLanguage(leadText, priorInbound);
  const fallback = c.default_language
    || (Array.isArray(c.languages) && c.languages.length ? c.languages[0] : 'en');
  const bag = (c.system_messages || {})[name];
  const picked = pickMessage(bag, res.lang, fallback);
  return {
    text: picked || c.handoff_note || null,
    lang: res.lang || fallback,
    detected: det.lang,
    source: res.source,
    confident: det.confident,
    scores: det.scores,
  };
}


// ============================================================================
// Did the reply come back in the lead's language? — shared source.
//
// Embedded verbatim into ParseClaude and ParseGuardRetry, AFTER
// src/language.js (it calls detectLanguage). Unit-tested standalone in
// tests/reply_language.test.js, which loads both files.
//
// WHY THIS EXISTS
// On 2026-09-12 the prompt suite failed English booking requests with
// Portuguese replies, 3 to 6 times in 24 depending on the prompt variant. The
// leak lives in one place: the explanation that the appointment is a first
// meeting rather than a viewing, whose vocabulary in the prompt is Portuguese.
// Rewording the example moved the rate; nothing removed it. The prompt is not
// the guard (§11): BuildClaudeRequest now STATES the reply language it
// detected, and this is the check behind it -- the same posture as
// bookingClaim and viewingClaim. A wrong-language reply is rejected, retried
// once, and escalates on a second failure. A lead told "a colleague will be in
// touch" in their own language is a recoverable outcome; a Portuguese reply
// to an English lead in the middle of a demo is not.
//
// THE BAR IS DELIBERATELY HIGHER THAN detectLanguage's OWN CONFIDENCE.
// The detector was tuned for short lead messages. On a reply it can be sure
// for the wrong reason: "Understood, João! Noted your maximum." scored
// Portuguese on the strength of one ã in a name. So the lead's stored name is
// masked before detection, and a mismatch needs the wrong language to score
// well past a single accented word while the lead's language scores next to
// nothing. Where either side is unsure, the reply passes: this guard is for
// the reply that is plainly in the other language, not for edge cases.
// ============================================================================

// pt and es carry hard markers worth 5-6 each (ã, ç, ñ, ¿), so one accented
// word already scores 6 and the bar must sit above two of them. English has no
// hard markers -- every word is worth 2 -- so three English function words is
// already unmistakable.
const REPLY_LANG_MIN_WRONG = { pt: 10, es: 10, en: 6 };
const REPLY_LANG_MAX_RIGHT = 2;    // at most one incidental function word

function maskName(text, name) {
  let t = String(text == null ? '' : text);
  const parts = String(name == null ? '' : name).split(/\s+/).filter(p => p.length > 1);
  for (const p of parts) {
    const esc = p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    t = t.replace(new RegExp(esc, 'gi'), ' ');
  }
  return t;
}

// replyLanguageMismatch(leadText, replyText, opts) ->
//   { mismatch, leadLang, replyLang, replyScores }
//
//   leadText   the lead's most recent message (what the reply answers)
//   replyText  the model's reply
//   opts.name  leads.full_name, masked out of the reply before detection
//   opts.leadLang  a language already detected upstream, to save a second pass
function replyLanguageMismatch(leadText, replyText, opts) {
  const o = opts || {};
  const lead = o.leadLang ? { lang: o.leadLang, confident: true } : detectLanguage(leadText);
  const reply = detectLanguage(maskName(replyText, o.name));
  const out = { mismatch: false, leadLang: lead.lang, replyLang: reply.lang, replyScores: reply.scores };
  if (!lead.lang || !reply.lang || reply.lang === lead.lang) return out;
  const wrong = reply.scores[reply.lang] || 0;
  const right = reply.scores[lead.lang] || 0;
  out.mismatch = wrong >= (REPLY_LANG_MIN_WRONG[reply.lang] || 10) && right <= REPLY_LANG_MAX_RIGHT;
  return out;
}

// renderReplyLanguageNote(lang) -> the line BuildClaudeRequest appends when the
// lead's language was detected with confidence, or '' when it was not. Stated,
// not asked for: the model is told which language this reply is in.
const REPLY_LANG_NAMES = { en: 'English', pt: 'Portuguese', es: 'Spanish' };
// 2026-09-13: the lead's stated name is spelled out as DATA, with the same
// precedent-override the booking status carries. "A name is never translated"
// held 11/24 on a transcript whose earlier English turns already said "John";
// the model was continuing its own precedent, exactly as it did with a
// booking confirmation up the transcript. Spelling the name out took it to
// 21/24. The booking-status precedent-override sentence was tried here too
// and scored 18/24 -- within noise, not better -- so it is NOT in the note;
// the deterministic check (src/reply_name.js) carries the rest.
function renderReplyLanguageNote(lang, leadName) {
  const name = REPLY_LANG_NAMES[lang];
  if (!name) return '';
  const full = String(leadName == null ? '' : leadName).trim().replace(/\s+/g, ' ');
  const first = full.split(' ')[0] || '';
  const nameRule = full
    ? 'The lead\'s name is "' + full + '": if you address them, write "' + first + '", with exactly '
      + 'that spelling. A name has no ' + name + ' form.'
    : 'A person\'s name is written exactly as recorded, never translated.';
  return '\n\nREPLY LANGUAGE: ' + name + '. The lead\'s most recent message is in ' + name
    + ', so the whole reply is written in ' + name + ' - every sentence, including any '
    + 'explanation of what kind of appointment this is. Words in other languages that appear '
    + 'in these instructions are examples, not the language to reply in. ' + nameRule;
}

// retryNameHint(used, storedName) -> the line for the ONE targeted retry after
// the reply addressed the lead by a name that is not on the row.
function retryNameHint(used, storedName) {
  const full = String(storedName == null ? '' : storedName).trim().replace(/\s+/g, ' ');
  const first = full.split(' ')[0] || full;
  return '\n\nYOUR PREVIOUS DRAFT WAS REJECTED: it addressed the lead as "' + used + '". The lead\'s '
    + 'name is "' + full + '": write "' + first + '", exactly that spelling. This outranks any name '
    + 'used earlier in this conversation, including in your own replies. Keep the same content.';
}

// retryLanguageHint(leadLang, replyLang) -> the line appended to the system
// prompt for the ONE targeted retry after a mismatch. A resample of the same
// request is a second draw from the same distribution; this names the fault.
function retryLanguageHint(leadLang, replyLang) {
  const want = REPLY_LANG_NAMES[leadLang] || leadLang;
  const got = REPLY_LANG_NAMES[replyLang] || replyLang;
  return '\n\nYOUR PREVIOUS DRAFT WAS REJECTED: it was written in ' + got + ', but the lead wrote in '
    + want + '. Write the reply again, entirely in ' + want + '. Keep the same content.';
}


// ============================================================================
// How many times have we already offered to propose times? — shared source.
//
// Embedded verbatim into BuildClaudeRequest. Unit-tested standalone in
// tests/offer_count.test.js, which loads THIS file rather than a copy.
//
// WHY THIS EXISTS
// On 2026-09-12 six consecutive replies ended with the identical sentence,
// "Quer que lhe proponha alguns horarios para essa primeira conversa com o
// nosso colega?". The lead had not declined and had not taken it up; the model
// had nothing left to qualify and used the offer as its way of moving forward,
// every turn. The same shape as "a colleague will follow up" (2.3) and the
// same fix: the workflow counts, the model phrases.
//
// THE RULE
// An offer to propose meeting times is made once. Count the assistant's own
// turns that ended with such an offer since the lead last raised booking
// themselves; a lead who asks for a time has taken the offer up, so the count
// restarts there. Only the assistant's own words count -- a colleague's reply
// or a system note is not the assistant repeating itself. The count is stated
// to the model; the prompt tells it what to do with it.
// ============================================================================

function deaccentOffer(s) {
  return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// The lead raising booking: asking for, accepting, or naming a time or a day.
const LEAD_RAISES = new RegExp(
  '\\b(marcar|agendar|reuniao|visita|visitar|horario|horarios|hora|horas|quando|amanha|semana|'
  + 'book|booking|schedule|meeting|viewing|appointment|available|availability|times?|slot|when|come|see|visit|week|tomorrow|'
  + 'cita|reunion|cuando|manana|'
  + 'segunda|terca|quarta|quinta|sexta|sabado|domingo|monday|tuesday|wednesday|thursday|friday|saturday|sunday|'
  + 'lunes|martes|miercoles|jueves|viernes)\\b|\\b\\d{1,2}[:h]\\d{2}\\b');
// The assistant offering to propose times, as the LAST sentence, as a question.
const OFFER_WORDS = /\b(horario|horarios|hora|horas|proponha|propor|agendar|marcar|reuniao|conversa|encontro|times?|slots?|schedule|scheduling|meeting|appointment|availability|available|book|cita|reunion|horarios|agendarla)\b/;

function lastSentence(text) {
  const t = String(text == null ? '' : text).trim();
  if (!t) return '';
  const parts = t.split(/(?<=[.!?])\s+|\n+/).filter(Boolean);
  return parts[parts.length - 1] || '';
}

function isOffer(body) {
  const s = deaccentOffer(lastSentence(body)).trim();
  return s.endsWith('?') && OFFER_WORDS.test(s);
}

// countPendingOffers(rows) -> number
//   rows  message rows in CHRONOLOGICAL order: { direction, body, ai_generated, origin }
function countPendingOffers(rows) {
  let n = 0;
  const list = Array.isArray(rows) ? rows : [];
  for (let i = list.length - 1; i >= 0; i--) {
    const r = list[i] || {};
    if (r.direction === 'inbound') {
      if (LEAD_RAISES.test(deaccentOffer(r.body))) break;   // the lead took it up, or asked
      continue;
    }
    const assistantOwn = r.origin ? r.origin === 'ai' : r.ai_generated === true;
    if (assistantOwn && isOffer(r.body)) n++;
  }
  return n;
}


// ============================================================================
// What the row already knows, stated to the model. — shared source.
//
// Embedded verbatim into BuildClaudeRequest. Unit-tested standalone in
// tests/known_facts.test.js, which loads THIS file; exercised against the live
// model by suite 4 of tests/prompt_suites.py.
//
// WHY THIS EXISTS
// On 2026-09-12 a lead who had given a budget, a timeline and an area was asked
// for the budget and the timeline again. The row held all three. The model
// sees the last 20 messages and nothing else; the budget had been stated 80
// messages earlier. Same defect class as every other one this week: the system
// holds a fact in one place and reasons from another.
//
// THE RULE
// A fact the workflow holds is stated to the model on every turn it holds it,
// exactly as the booking status is. The block is built from the ROW, so it can
// only contain what persistence accepted. The lead's newer words override it,
// and the model is told so -- this is a record, not an instruction to repeat.
// The WhatsApp profile name is deliberately NOT a fact: it is a nickname until
// the lead states a name (qualification.name_source = 'stated').
// ============================================================================

function renderKnownFacts(lead, qualification) {
  const l = lead || {}, q = qualification || {};
  const lines = [];
  const clean = (v) => (v === null || v === undefined) ? '' : String(v).trim();
  const eur = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' EUR';

  if (q.name_source === 'stated' && clean(l.full_name)) {
    lines.push('- Name: ' + clean(l.full_name) + ' (write it exactly like this in every reply language; a name is never translated or localised)');
  }
  const TYPE = { buyer: 'buy', seller: 'sell', renter: 'rent' };
  if (TYPE[l.lead_type]) lines.push('- Looking to: ' + TYPE[l.lead_type]);

  const bmin = Number(l.budget_min) > 0 ? Number(l.budget_min) : null;
  const bmax = Number(l.budget_max) > 0 ? Number(l.budget_max) : null;
  if (bmin && bmax) lines.push(bmin === bmax ? '- Budget: about ' + eur(bmin)
                                              : '- Budget: ' + eur(bmin) + ' to ' + eur(bmax));
  else if (bmax) lines.push('- Budget: up to ' + eur(bmax));
  else if (bmin) lines.push('- Budget: from ' + eur(bmin));

  if (clean(l.timeline)) lines.push('- Timeline: ' + clean(l.timeline));
  if (clean(l.area)) lines.push('- Area: ' + clean(l.area));
  if (clean(q.bedrooms)) lines.push('- Bedrooms: ' + clean(q.bedrooms));
  if (clean(q.financing)) lines.push('- Financing: ' + clean(q.financing));
  if (clean(q.purpose)) lines.push('- Purpose: ' + clean(q.purpose));
  if (!lines.length) return '';

  return '\n\nWHAT OUR RECORDS ALREADY HOLD FOR THIS LEAD\n'
    + 'Learned earlier in this conversation, possibly before the messages you can see:\n'
    + lines.join('\n') + '\n'
    + 'Do not ask again for anything listed here, and do not ask the lead to confirm it either - '
    + 'use it. If the lead brings one of these up you may refine it, and what the lead says now '
    + 'overrides the record. In the JSON, '
    + 'return these values unless the lead has changed them; when the lead gives a new figure, '
    + 'return only what they said now.';
}

// ============================================================================
// QUALIFIED: the row says there is nothing left to ask. — 2026-09-14.
//
// A buyer who had given budget, area, bedrooms, timeline and financing got
// two consecutive replies with no next step: "a colleague will follow up".
// The prompt told the model to offer times only when the lead asked, and to
// move forward with one qualifying question -- and when the questions run
// out, the handoff phrase is all that is left. That is the moment a lead
// goes cold, and the thing the product exists to prevent. Yesterday's rules
// against promising and against repeating an offer made the model more
// literal about it, not less.
//
// So the WORKFLOW says it, from the row, as a fact (improvements §0.4):
// budget, timeline and area are on record, no meeting is booked or offered,
// times are available -- offer them now. The prompt rule is reinforcement.
// ============================================================================
function qualifiedForOffer(lead, qualification, ctx) {
  const l = lead || {}, q = qualification || {}, c = ctx || {};
  const hasBudget = Number(l.budget_min) > 0 || Number(l.budget_max) > 0;
  const hasTimeline = !!(l.timeline && String(l.timeline).trim());
  const hasArea = !!(l.area && String(l.area).trim());
  if (!(hasBudget && hasTimeline && hasArea)) return false;
  if (q.booking && q.booking.event_id) return false;          // already booked
  if (c.bookingIntent && c.bookingIntent !== 'none') return false;   // booking in motion this turn
  if (c.offersPending > 0) return false;                       // already offered, not taken up
  if (!(c.slotsAvailable > 0)) return false;                   // nothing to offer
  return true;
}

function renderQualifiedNote() {
  return '\n\nQUALIFIED: budget, area and timeline are on record, no meeting is booked and none has '
    + 'been offered. There is nothing left to qualify. The next step is a first meeting with our '
    + 'colleague: offer the times listed under AVAILABLE_SLOTS in THIS reply, warmly, and ask '
    + 'which suits. Do not end this reply with "a colleague will follow up" - that is the moment '
    + 'a lead goes cold.';
}


// ============================================================================
// The never-invent-a-time guard. Shared source.
//
// Embedded verbatim into ParseClaude and ParseGuardRetry, replacing the
// timesNotSupplied() each node carried inline. Unit-tested standalone in
// tests/time_guard.test.js, which loads THIS file.
//
// THE RULE (unchanged since 2026-09-12): a time in the reply must be one the
// workflow supplied. If none was supplied, no time may appear at all. A
// rejection routes into the guard retry, and escalates if the retry fails too.
//
// THE ONE EXEMPTION (2026-09-21): a time the LEAD named in their own message
// may appear in a clause that DECLINES it. Live check 2 of the language
// deploy: the lead asked "11:00?", 09:00 and 10:00 were offered, and both of
// the model's replies said, correctly, "11:00 isn't available, but I do have
// … 09:00 … or 10:00". The guard rejected both, because it could not tell
// NAMING a time from DECLINING one, and the lead was escalated for asking an
// ordinary question.
//
// WHAT THE EXEMPTION MUST NOT OPEN, in order of danger:
//   * accepting the lead's unoffered time: "11:00 it is", "11:00 works";
//   * declining it in one clause and affirming it in the next: "11:00 isn't
//     possible on Wednesday, but Thursday at 11:00 works". So the decision is
//     taken PER OCCURRENCE, in the clause around it, not per sentence;
//   * declining a time the lead never asked for, which is still the model
//     talking about a time nobody supplied;
//   * an invented alternative in a declining sentence: "11:00 isn't
//     available, but 14:00 is".
// Clauses split on contrast words and dashes, NOT on plain commas:
// "11:00, unfortunately, is taken" is one clause, and must stay one.
//
// NEGATION THAT GOVERNS THE TIME (2026-09-21, the first deploy gate). The
// model declined "11:00?" with "09:00 or 10:00 are available, but not 11:00",
// the guard rejected that and the retry, and the lead was escalated. This was
// the third decline shape the wording list missed ("quedamos entonces", then
// the plurals, now "but not X"). So instead of another phrase, a second test
// is added, taken PER OCCURRENCE: does a negation stand directly in front of
// THIS time, with nothing between them except a preposition or a day?
//   en  not (at) 11:00 · except (for) 11:00 ·
//       don't have an 11:00 · can't do 11:00 · no 11:00 slot
//   pt  não às 11:00 · menos às 11:00 · exceto / salvo às 11:00 ·
//       não consigo marcar às 11:00
//   es  no a las 11:00 · excepto / salvo / menos a las 11:00 ·
//       no puedo ofrecer las 11:00
// The rule is unchanged: the time must be one the LEAD named. And the
// negation must govern it:
//   * "why not 11:00", "if not 11:00", "porque não às 11:00", "¿por qué no a
//     las 11:00?" are proposals, never declines;
//   * "pelo menos às 11:00", "al menos a las 11:00" mean "at least", and
//     "mais ou menos", "más o menos" mean "around";
//   * "apart from", "other than", "besides", "tirando" are left out: "apart
//     from 11:00 we also have 09:00" ADDS the time rather than declining it;
//   * an EXCEPT that carves the time out of something UNAVAILABLE, or out of
//     a negation, or that sits beside "also", affirms it: "everything except
//     11:00 is taken", "nothing is free except 11:00". That is a rejection even when the
//     clause also reads as a decline. The clause-level rule alone accepted it
//     before 2026-09-21.
// ============================================================================

const TG_TIME_RX = /\b([01]?\d|2[0-3])[:h]([0-5]\d)\b/g;

function tgNorm(h, m) { return String(Number(h)) + ':' + m; }

function tgTimesIn(s) {
  return tgTimesAt(s).map(x => x.t);
}

// Every time in s, with where it starts: [{ t: '11:00', i: 17 }].
function tgTimesAt(s) {
  const out = [];
  const rx = new RegExp(TG_TIME_RX.source, 'g');
  let m;
  while ((m = rx.exec(String(s == null ? '' : s))) !== null) out.push({ t: tgNorm(m[1], m[2]), i: m.index });
  return out;
}

// What may stand between a negation and the time it governs: a day ("on
// Thursday", "na quinta dia 24", "el jueves 24 de septiembre") and a
// preposition ("at", "às", "a las"). Nothing else. Deaccented text.
const TG_DAY = '(?:(?:mon|tues|wednes|thurs|fri|satur|sun)day|(?:segunda|terca|quarta|quinta|sexta)(?:-feira)?|sabado|domingo|lunes|martes|miercoles|jueves|viernes)';
const TG_BRIDGE = '(?:(?:(?:on|this|next|na|no|nesta|neste|el|este)\\s+)?' + TG_DAY +
  '(?:\\s+(?:dia\\s+)?\\d{1,2}(?:\\s+(?:de\\s+)?[a-z]+)?)?\\s+)?' +
  '(?:(?:at|for|the|as|a|pelas|para as|a las|las|a la|para las)\\s+)?$';
// The negation words themselves, one per language, with the forms that do NOT
// negate what follows. Shared: the time guard's rule below and tgNegatedBefore()
// (which src/booking_claim.js calls) read these three and no other list.
// en. Not "why not", "if not", "or not", "whether not".
const TG_NEG_EN = "(?<!\\b(?:why|if|or|whether)\\s)\\bnot";
// pt. Not "porque não", "por que não", "se não", "ou não".
const TG_NEG_PT = "(?<!\\b(?:porque|por que|se|ou)\\s)\\bnao";
// es. Not "por qué no", "porque no", "si no", "o no".
const TG_NEG_ES = "(?<!\\b(?:por que|porque|si|o)\\s)\\bno";
// en contractions ("isn't", "won't"). NOT part of the time guard's own rule (its
// decline list carries those forms itself); shared for src/appointment_kind.js's
// viewing guard (22 Sep 2026), so "this isn't a viewing" is read as a denial.
const TG_NEG_EN_NT = "\\b(?:is|are|was|were|does|do|did|would|will|wo|could|ca)n'?t";
// A negation that governs the time after it.
const TG_NOT_BEFORE_RX = new RegExp('(?:' + [
  TG_NEG_EN,
  "\\b(?:(?:don'?t|do not|doesn'?t|does not)\\s+have|have no|haven'?t got)(?:\\s+(?:an?|the|any))?",
  "\\b(?:can'?t|cannot|can not)\\s+(?:do|offer|make|book)",
  TG_NEG_PT,
  "\\bnao\\s+(?:consigo|conseguimos|posso|podemos)\\s+(?:fazer|oferecer|marcar|agendar)",
  "\\bnao\\s+(?:tenho|temos|ha)(?:\\s+(?:vaga|disponibilidade))?",
  // es. A bare "no" governs only through a preposition: "pero no a las 11:00".
  TG_NEG_ES + "(?=\\s+(?:(?:a las|las|para las|a la)\\s+$|(?:el\\s+)?" + TG_DAY + "))",
  "\\bno\\s+(?:puedo|podemos)\\s+(?:hacer|ofrecer|agendar|reservar)",
  "\\bno\\s+(?:tengo|tenemos|hay)(?:\\s+(?:hueco|disponibilidad))?",
].join('|') + ')\\s+' + TG_BRIDGE);
// Does a negation govern whatever starts right after `before`? Deaccented,
// lower-cased text. The negation must END the text, optionally followed by one
// adverb: "ainda nao temos uma reuniao marcada" is negated at "temos"; "nao, temos
// a reuniao marcada" is not (the comma ends the negation's reach), and neither is
// "nao se preocupe, temos a reuniao marcada". Added 22 Sep 2026 for the claim
// guard (src/booking_claim.js): "Ainda não temos uma reunião marcada, João. Posso
// propor..." was read as a claim, both drafts rejected, the lead handed over
// (the booking gate, run 8).
const TG_NEGATED_BEFORE_RX = new RegExp('(?:' + [TG_NEG_EN, TG_NEG_PT, TG_NEG_ES].join('|') +
  ')\\s+(?:(?:ainda|ja|aun|todavia|yet|still|really|actually)\\s+)?$');
function tgNegatedBefore(before) {
  return TG_NEGATED_BEFORE_RX.test(String(before == null ? '' : before));
}

// "except" and its kin. They decline the time only when the rest of the clause
// is not about something UNAVAILABLE: "any time except 11:00" declines it,
// "everything except 11:00 is taken" offers it.
const TG_EXCEPT_BEFORE_RX = new RegExp('(?:' + [
  '\\bexcept(?:\\s+for)?',
  '\\b(?:exceto|excepto|salvo)', '(?<!\\b(?:pelo|ao|a|de|al|lo|o|ou)\\s)\\bmenos',
].join('|') + ')\\s+' + TG_BRIDGE);
const TG_UNAVAILABLE_RX = /\b(?:(?:taken|booked|full|unavailable|gone|not (?:available|free|open)|isn'?t (?:available|free|open)|aren'?t (?:available|free|open)|no longer)\b|ocupad|reservad|preenchid|lotad|complet|indisponiv|(?:nao|no) (?:esta|estao|estan|ha|hay) (?:disponiv|disponib|livre|libre))/;
// Before an except: a negation or "only" turns the except into an offer.
const TG_EXCEPT_INVERTS_RX = /\b(?:not|no|nothing|none|cannot|only|nao|nada|nenhum\w*|sem|apenas|so|sin|ningun\w*|solo|solamente)\b|n't\b/;
// Anywhere in the clause: an except beside "also" adds the time.
const TG_ADDITIVE_RX = /\b(?:also|too|as well|tambem|alem|tambien|ademas)\b/;
// After the time: "there's no 11:00 slot", "no 11:00 opening".
const TG_NO_BEFORE_RX = /\bno\s+$/;
const TG_SLOT_AFTER_RX = /^\s*(?:slot|opening|appointment|availability)\b/;

// governs(clause, i) -> 'declined' | 'carved' | null, for the time at clause[i].
function tgGoverned(clause, i) {
  const before = clause.slice(0, i);
  const after = clause.slice(i).replace(/^\S+/, '');
  const ex = before.match(TG_EXCEPT_BEFORE_RX);
  if (ex) {
    const lead = before.slice(0, ex.index);
    return (TG_UNAVAILABLE_RX.test(clause) || TG_EXCEPT_INVERTS_RX.test(lead) || TG_ADDITIVE_RX.test(clause)) ? 'carved' : 'declined';
  }
  if (TG_NOT_BEFORE_RX.test(before)) return 'declined';
  if (TG_NO_BEFORE_RX.test(before) && TG_SLOT_AFTER_RX.test(after)) return 'declined';
  return null;
}

// A clause that declines. Deaccented, lower-cased text. Each language's forms,
// singular and plural. The list is measured against real replies in
// tests/time_guard.test.js; a shape it misses is a false escalation (annoying),
// never a false acceptance, because the exemption only ever ALLOWS a declined
// time the lead asked for.
const TG_DECLINE_RX = new RegExp([
  // en. A negation counts only when it governs an availability word: "no
  // problem, 17:00 then" must never read as a decline.
  "\\b(?:isn'?t|is not|aren'?t|are not|not|no longer|won'?t be|can'?t (?:do|offer|make)|cannot (?:do|offer|make))\\b[^.;]{0,30}?\\b(?:available|free|possible|an option|open|doable)\\b",
  "\\bnot available\\b", "\\bunavailable\\b",
  "\\b(?:already (?:taken|booked)|fully booked|booked up|is taken|are taken)\\b",
  "\\bno (?:availability|slot|slots|opening|openings)\\b",
  "\\b(?:don'?t|do not) have (?:availability|anything|a slot|slots|that time|an opening)\\b",
  "\\b(?:can'?t|cannot) offer\\b",
  // 22 Sep 2026: the slot another lead has just taken. TAKEN and GONE only, never
  // "booked": a decline lets the lead's own time through, and "your meeting was
  // just booked for 11:00" must never be read as one.
  "\\b(?:was|were|has been|have been|got) (?:just )?taken\\b(?! care)", "\\bjust (?:been |got )?(?:taken|gone)\\b(?! care)",
  "\\b(?:has|have) (?:just )?gone\\b",
  "\\b(?:taken|booked|reserved) by (?:someone else|somebody else|another (?:client|person|customer|lead))\\b",
  // pt. Same rule: "nao ha problema" is not a decline.
  "\\bnao (?:esta|estao|temos|tenho|ha|existe|existem|e|sera|fica|ficam)\\b[^.;]{0,25}?\\b(?:disponiv|disponibilidade|livre|possiv|vaga|aberto|opcao)",
  "\\bindisponive(?:l|is)\\b",
  "\\bja (?:esta|estao) (?:ocupad|preenchid|reservad)", "\\b(?:esta|estao) (?:ocupad|preenchid)",
  "\\bsem disponibilidade\\b", "\\bnao (?:consigo|conseguimos|posso|podemos) (?:oferecer|marcar|agendar|disponibilizar)",
  // 22 Sep 2026: "ficou ocupado", "acabou de ser ocupado". Never "marcado": see en.
  // "Reservado" only with WHO took it: "acabou de ser reservado por outra pessoa"
  // (the booking gate, run 5). Kept narrow: someone ELSE, never the lead's own booking.
  "\\b(?:reservad|marcad|ocupad)[oa]s? por (?:outra pessoa|outro cliente|outra cliente|outras pessoas|alguem)\\b",
  "\\b(?:ficou|ficaram|foi|foram) (?:entretanto |agora |ja )?(?:ocupad|preenchid)", "\\bacab(?:ou|aram) de (?:ser |ficar )?(?:ocupad|preenchid)",
  // es. "no hay problema" is not a decline.
  "\\bno (?:esta|estan|tenemos|tengo|hay|es|sera|queda|quedan)\\b[^.;]{0,25}?\\b(?:disponib|libre|posible|hueco|opcion)",
  "\\bya (?:esta|estan) (?:ocupad|reservad|complet)", "\\b(?:esta|estan) (?:ocupad|complet)",
  "\\bsin disponibilidad\\b", "\\bno (?:puedo|podemos) (?:ofrecer|agendar|reservar)",
  // 22 Sep 2026, the booking gate's run 9: "Ese horario de las 16:00 se acaba de
  // ocupar"; run 6: "acaba de ocuparse". Never "reservado" alone: see en.
  "\\b(?:reservad|ocupad|cogid)[oa]s? por (?:otra persona|otro cliente|otra clienta|otras personas|alguien)\\b",
  "\\bse (?:acaba|acaban) de ocupar\\b", "\\bacaba(?:n)? de ocupar(?:se)?\\b", "\\bacaba(?:n)? de (?:ser |quedar )?ocupad", "\\bse (?:ocupo|ocuparon)\\b", "\\b(?:quedo|quedaron) (?:ya )?ocupad",
].join('|'));

// Contrast words and dashes end a clause. Deaccented text.
const TG_CLAUSE_SPLIT_RX = /\s*;\s*|\s+[-–—]\s+|\s*—\s*|,?\s+\b(?:but|however|though|although|whereas|instead|mas|porem|contudo|no entanto|pero|sin embargo|en cambio)\b/;

// Typographic apostrophes are folded to ' before any pattern runs (21 Sep 2026,
// the gate that passed 61f50cc: "11:00 isn’t available", U+2019, was rejected
// because every pattern here is written with a straight quote).
function tgDeaccent(s) {
  return String(s == null ? '' : s).replace(/[\u2018\u2019\u201B\u02BC\u2032\uFF07\u00B4\u0060]/g, "'")
    .normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// Which time each clause-level decline is ABOUT: the occurrence nearest to it.
// Before 2026-09-21 (the first deploy gate) a decline anywhere in the clause
// exempted every lead-named time in it, so "10:00 isn't available, so 11:00 it
// is" let 11:00 through. And the bare sentiment words ("unfortunately",
// "infelizmente", "lamentablemente"...) no longer decline on their own:
// "Sadly I had to move things, 11:00 is yours" was accepted.
// -> Set of the start indexes of declined occurrences.
function tgDeclinedOccurrences(clause, times) {
  const out = new Set();
  if (!times.length) return out;
  const rx = new RegExp(TG_DECLINE_RX.source, 'g');
  let m;
  while ((m = rx.exec(clause)) !== null) {
    const a = m.index, b = m.index + m[0].length;
    let best = null, bestD = Infinity;
    for (const x of times) {
      const e = x.i + x.t.length;
      const d = e <= a ? a - e : (x.i >= b ? x.i - b : 0);
      if (d < bestD) { bestD = d; best = x; }
    }
    if (best) out.add(best.i);
    if (m[0].length === 0) rx.lastIndex++;
  }
  return out;
}

// timesNotSupplied(reply, slots, leadText) -> the times the reply named that
// nothing supplied, e.g. ['14:00']. Empty means the reply passes.
//   slots     [{timeLocal: 'HH:MM'}, ...]: offered, booked or stored times
//   leadText  the lead's current message (optional: without it there is no
//             exemption, which is the pre-2026-09-21 behaviour)
function timesNotSupplied(reply, slots, leadText) {
  const supplied = new Set();
  for (const s of (slots || [])) {
    const m = String((s && s.timeLocal) || '').match(/^(\d{1,2}):(\d{2})$/);
    if (m) supplied.add(tgNorm(m[1], m[2]));
  }
  const leadTimes = new Set(tgTimesIn(leadText));
  const bad = new Set();
  const sentences = String(reply == null ? '' : reply).split(/(?<=[.!?\n])\s+|\n+/);
  for (const sentence of sentences) {
    for (const clause of tgDeaccent(sentence).split(TG_CLAUSE_SPLIT_RX)) {
      if (!clause) continue;
      const times = tgTimesAt(clause);
      const declinedAt = tgDeclinedOccurrences(clause, times);
      for (const { t, i } of times) {
        if (supplied.has(t)) continue;
        if (!leadTimes.has(t)) { bad.add(t); continue; }
        const governed = tgGoverned(clause, i);
        if (governed === 'declined') continue;
        if (governed === 'carved') { bad.add(t); continue; }
        if (declinedAt.has(i)) continue;
        bad.add(t);
      }
    }
  }
  return [...bad];
}

// ============================================================================
// Is there a property to view, or only a lead to meet? — shared source.
//
// Embedded verbatim into BuildClaudeRequest (which decides) and into
// ParseClaude / ParseGuardRetry (which check the reply). Unit-tested standalone
// in tests/appointment_kind.test.js, which loads THIS file rather than a copy.
//
// WHY THIS EXISTS
// On 2026-09-05 the Concierge sent a real lead:
//     "A sua visita esta confirmada para sexta-feira, dia 11 de setembro,
//      as 10:00, hora de Lisboa."
// The calendar half was correct: the slot was genuinely free, the event was
// created, the agent was notified. The CLAIM was not. Nobody -- not the lead,
// not an agent, not the Concierge -- had ever named a property. It booked a
// viewing of nothing, and the lead would have found out on the doorstep.
//
// engineering-lessons.md §0: never let a generated message narrate a future you
// have not secured. A property nobody has named is a future nobody has secured.
//
// THE RULE
// Unless a specific property has been named in the conversation, the
// appointment is a FIRST MEETING with an agent, and must be described as one.
// That is normal in this market and, unlike "visita", it is true. "visita" /
// "viewing" is reserved for when a property has a name.
//
// THE BIAS IS ONE-DIRECTIONAL, and deliberately so -- the same rule that
// governs matchConfirmation(). When in doubt it is a MEETING:
//   - calling a real viewing a meeting UNDER-describes an appointment that is
//     going to happen anyway. A human corrects it in one message.
//   - calling a meeting a viewing INVENTS a property. Nothing downstream can
//     correct that, because the lead has already been told.
// Every unknown below therefore resolves to 'meeting'.
//
// WHY NOT ASK THE MODEL
// Same reason the workflow picks the slots and the model only phrases them: the
// appointment kind decides what goes in a real agent's calendar and what a
// prospect is told. It has to be answerable from stored data. Asking the model
// "was a property discussed?" would make the guard depend on the judgement it
// exists to not trust.
// ============================================================================

// ---------------------------------------------------------------------------
// A listing reference is the only thing that counts as "a property has a name".
//
// An address or a house name ("a moradia na Rua das Flores") would need
// judgement to recognise, and judgement here means a model. So they are NOT
// detected, and such a conversation books a meeting. That is the safe
// direction and it is an honest under-description, not a wrong one.
//
// Two forms:
//   bare      A-1042, LX-2001            uppercase block, dash, 3-5 digits
//   keyword   Ref B-2001, referencia 10234, reference: LX88
// The bare form is case-SENSITIVE on purpose. Lowercase "t-3000" in prose is
// far more likely to be noise than a reference; a real one is written in caps
// or introduced by the word "ref".
// ---------------------------------------------------------------------------
const REF_BARE = /\b[A-Z]{1,3}-\d{3,5}\b/g;
const REF_KEYWORD =
  /\b(?:ref|refa|referencia|reference)\b\.?\s*[:#-]?\s*([A-Za-z]{0,4}-?\d{2,6}[A-Za-z]?)\b/gi;

function deaccent(s) {
  return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '');
}

// findPropertyRefs(text) -> array of normalised reference strings (may be empty)
function findPropertyRefs(text) {
  const raw = String(text == null ? '' : text);
  if (!raw.trim()) return [];
  const found = [];
  const add = (v) => {
    const s = String(v).toUpperCase().replace(/\s+/g, '');
    if (s && found.indexOf(s) === -1) found.push(s);
  };

  // Bare form reads the ORIGINAL text: case is part of the signal.
  let m;
  REF_BARE.lastIndex = 0;
  while ((m = REF_BARE.exec(raw)) !== null) add(m[0]);

  // Keyword form reads the de-accented text so "referencia" and "referência"
  // are the same word.
  const flat = deaccent(raw);
  REF_KEYWORD.lastIndex = 0;
  while ((m = REF_KEYWORD.exec(flat)) !== null) add(m[1]);

  return found;
}

// ---------------------------------------------------------------------------
// appointmentKindFor(rows) -> {kind: 'viewing'|'meeting', refs: [...]}
//
// `rows` are message rows: {direction, body, ai_generated}.
//
// THE CONCIERGE'S OWN WORDS ARE NOT EVIDENCE. It has no inventory, so any
// reference it produced would be one it invented -- and trusting it would
// re-open exactly this defect one layer down. Outbound rows count only when
// they are explicitly marked as NOT ai_generated, which is a human agent
// replying from the cockpit (or a fixed config string, which never carries a
// reference). An outbound row whose origin cannot be established is ignored:
// if `ai_generated` is missing from the query, every conversation books a
// meeting, which is the fail-SAFE direction rather than the fail-open one.
// ---------------------------------------------------------------------------
function appointmentKindFor(rows) {
  const refs = [];
  for (const r of (Array.isArray(rows) ? rows : [])) {
    if (!r) continue;
    if (r.direction === 'outbound' && r.ai_generated !== false) continue;
    for (const ref of findPropertyRefs(r.body)) {
      if (refs.indexOf(ref) === -1) refs.push(ref);
    }
  }
  return { kind: refs.length ? 'viewing' : 'meeting', refs };
}

// ---------------------------------------------------------------------------
// viewingClaim(reply) -> the offending phrase, or null.
//
// The prompt tells the model which kind of appointment this is. This is the
// CHECK, not a better prompt -- §11 instance 11: when wording cannot hold a
// line reliably, replace it with something that fails loudly. The model wrote
// "a sua visita esta confirmada" under a prompt that already forbade asserting
// things it could not see.
//
// Applied only when the kind is 'meeting'. A rejection routes into the existing
// guard-retry; if the retry also claims a viewing, the turn escalates and NO
// booking is created -- a human holds a lead who is ready to book, which is a
// recoverable outcome, unlike the message this guard prevents.
//
// The list is not exhaustive and is not meant to be. It covers the words that
// NAME the appointment in the three languages the Concierge speaks. Paraphrases
// it misses are caught, if at all, by the prompt -- this is the backstop, and a
// backstop that tried to be complete would start rejecting honest sentences.
// ---------------------------------------------------------------------------
const VIEWING_WORDS = [
  // pt/es visita, visitas, visitar, visita-la; en visit, visits, visiting
  { rx: /\bvisit\w*/, label: 'visit*' },
  { rx: /\bviewings?\b/, label: 'viewing' },
  { rx: /\bview the\b/, label: 'view the' },
  { rx: /\bver (?:o|a|os|as|el|la|los|las) (?:imovel|imoveis|casa|moradia|apartamento|andar|vivienda|piso|propriedade|propiedad)\b/,
    label: 'ver o imovel' },
  { rx: /\bsee the (?:property|house|apartment|flat|villa)\b/, label: 'see the property' },
];

// 22 Sep 2026, the booking gate (runs 1 and 4): the model EXPLAINED that no
// property was named -- "a first meeting ... rather than a specific property
// viewing", "There's no specific property lined up yet for a viewing" -- and
// this guard, which matched the word anywhere, rejected both drafts and handed
// the lead over. A viewing word is now NOT a claim when, and only when:
//   1. a negation governs it directly: "not a viewing", "isn't a viewing",
//      "nao e uma visita", "no es una visita";
//   2. a contrast stands directly before it: "rather than a (specific property)
//      viewing", "instead of", "em vez de", "en lugar de";
//   3. EARLIER IN THE SAME CLAUSE the reply says no property is identified:
//      "no specific property lined up yet for a viewing", "sem imovel ... visita".
// Everything else still rejects, and the dangerous direction stays shut: "I'll
// book you a viewing of the villa on Thursday" has none of the three.
// WHICH words negate, and where a clause ends, are src/time_guard.js's rules
// (TG_NEG_*, TG_CLAUSE_SPLIT_RX), not second lists here: every node that embeds
// this file embeds time_guard.js too.
function viewingDenied(sentence, i) {
  const before = sentence.slice(0, i);
  const DET = '(?:(?:a|an|the|any|um|uma|un|una|nenhum|nenhuma|ningun|ninguna)\\s+)?';
  const ADJ = '(?:(?:specific|particular|actual|real|property|imovel|propriedade|propiedad|inmueble|concreta?|especifica?)\\s+){0,2}';
  const NEG = '(?:' + [TG_NEG_EN, TG_NEG_EN_NT, TG_NEG_PT, TG_NEG_ES].join('|') + ')';
  const COPULA = '(?:(?:be|is|e|es|sera|seria|era|yet|still|ainda|aun|todavia|really|actually)\\s+)?';
  if (new RegExp(NEG + '\\s+' + COPULA + DET + ADJ + '$').test(before)) return true;
  const CONTRAST = '(?:rather than|instead of|as opposed to|em vez de|em lugar de|ao inves de|en lugar de|en vez de)';
  if (new RegExp('\\b' + CONTRAST + '\\s+' + DET + ADJ + '$').test(before)) return true;
  // the clause this word sits in, from its last boundary before the word
  let start = 0;
  for (const m of before.matchAll(new RegExp(TG_CLAUSE_SPLIT_RX.source, 'g'))) start = m.index + m[0].length;
  const clauseBefore = before.slice(start);
