// A promise that waits on the LEAD is not a claim, for the same reason a question
// is not: "Whenever you're ready to confirm, just let me know and I'll get it
// arranged" (exec 1684 and 1692, 12 Sep) commits to nothing yet. Only the lead's
// own decision counts as the condition -- "once our colleague confirms, you're
// all set" is still a claim, because nothing the lead does is awaited.
const CLAIM_CONDITIONAL_RX = new RegExp([
  "\\b(?:whenever|once|as soon as|if|when) you(?:'re| are)? (?:ready|decide|confirm|choose|pick|let me know|want|would like|'d like)",
  '\\b(?:assim que|quando|se|logo que) (?:me )?(?:confirmar|decidir|escolher|quiser|estiver pront|disser)',
  '\\b(?:cuando|en cuanto|si) (?:me )?(?:confirme|decida|elija|quiera|este list|diga)',
].join('|'));

// bookingClaim(reply) -> the offending phrase (label), or null.
function bookingClaim(reply) {
  const raw = String(reply == null ? '' : reply);
  if (!raw.trim()) return null;
  // Sentence by sentence, so a question is never read as an assertion.
  const sentences = raw.split(/(?<=[.!?\n])\s+|\n+/);
  for (const sentence of sentences) {
    const s = sentence.trim();
    if (!s || s.endsWith('?')) continue;
    const t = deaccentClaim(s);
    if (CLAIM_CONDITIONAL_RX.test(t)) continue;
    for (const c of BOOKING_CLAIMS) {
      // Every occurrence, not the first: a negated one ("ainda nao temos uma
      // reuniao marcada") must not hide an affirmed one later in the sentence.
      for (const m of t.matchAll(new RegExp(c.rx.source, c.rx.flags.replace('g', '') + 'g'))) {
        // A negation governing the claim makes it a denial (22 Sep 2026, the
        // booking gate's run 8). Which words negate is src/time_guard.js's rule,
        // tgNegatedBefore(), not a second list here: every node that embeds this
        // file embeds time_guard.js too.
        if (tgNegatedBefore(t.slice(0, m.index))) continue;
        return m[0];
      }
    }
  }
  return null;
}



// ============================================================================
// The shared steps of parsing a model reply. Shared source.
//
// Embedded verbatim into ParseClaude and ParseGuardRetry. Unit-tested
// standalone in tests/parse_reply.test.js, which loads THIS file.
//
// WHY IT EXISTS (2026-09-21): the two parser nodes carried the same code as two
// copies (fail(), replyLooksBroken(), the response parse, the shape check, the
// time guard's inputs, the viewing check, the budget check). A fix to one could
// miss the other, and did: the never-invent guard existed twice inline. What
// is left in each node is only where they genuinely DIFFER: the first attempt
// asks for a targeted retry, and the retry delivers, withholds or escalates.
// ============================================================================

// makeParseFail(b, durationMs, extra) -> fail(errorType, errorMessage), the
// node's failure return. `extra` is what distinguishes the retry
// ({ wasGuardRetry: true }).
function makeParseFail(b, durationMs, extra) {
  return function fail(errorType, errorMessage) {
    return [{ json: Object.assign({}, b, extra || {}, {
      ok: false, errorType, errorMessage, durationMs, usage: null, parsed: null }) }];
  };
}

// parseModelResponse(res) -> { ok: true, parsed, body } | { ok: false, errorType, errorMessage }
//
// Defensive parse. Structured outputs (output_config.format) already constrain
// the response to the schema at the API level, so this is a BACKSTOP, not the
// primary mechanism. But it is not dead code: structured outputs do NOT hold
// when stop_reason is 'refusal' or 'max_tokens'.
function parseModelResponse(res) {
  const bad = (errorType, errorMessage) => ({ ok: false, errorType, errorMessage });
  const code = (res || {}).statusCode;
  if (code === 401 || code === 403) return bad('claude_auth', 'HTTP ' + code);
  if (code >= 400 && code < 500)    return bad('claude_bad_request', 'HTTP ' + code);
  if (!(code >= 200 && code < 300)) return bad('claude_unavailable', 'HTTP ' + code);

  const body = (res || {}).body || {};
  if (body.stop_reason === 'refusal')    return bad('claude_refusal', 'model declined');
  if (body.stop_reason === 'max_tokens') return bad('claude_truncated', 'hit max_tokens');

  let text = '';
  for (const blk of (body.content || [])) if (blk.type === 'text') text += blk.text;
  // Strip fences / stray prose even though structured outputs should prevent them.
  text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const s = text.indexOf('{'), e = text.lastIndexOf('}');
  if (s !== -1 && e > s) text = text.slice(s, e + 1);

  let parsed;
  try { parsed = JSON.parse(text); } catch (err) { return bad('bad_json', String(err.message)); }
  return { ok: true, parsed, body };
}

// ---------------------------------------------------------------------------
// SEMANTIC guard on the reply.
//
// Structured outputs guarantee the response matches the SCHEMA. They do not
// guarantee the reply is a sensible sentence. On 2026-09-03 a schema-valid
// response carried reply = ": corrigir - vou responder corretamente.}" and it
// was DELIVERED to a real lead. Structural markers only; nothing
// language-specific, since replies are pt-PT / en / es.
//
// 2026-09-21: two more markers, from a reply that passed every guard:
//   "…hora de Lisbo,, si le viene bien.dígame para me confirma…"
// It was character-level corruption (fused words, a double comma, a full stop
// glued to the next word) in otherwise valid Spanish, with a promise drifting in
// ("lo dejo registado"). Measured against 65 good real replies: 0 false
// positives for either marker. A web address or a domain ("g.page",
// "ryvodigital.com", "hello@ryvodigital.com") is removed before the glued-stop
// test, since it is the one legitimate shape of a letter-dot-letter join.
// ---------------------------------------------------------------------------
const PR_DOMAIN_RX = /\b(?:https?:\/\/\S+|www\.\S+|[\w.+-]+@[\w-]+(?:\.[\w-]+)+|[\w-]+(?:\.[\w-]+)*\.(?:com|pt|es|net|org|io|co|uk|eu|page|app|gl|dev|ai|info|biz|me|tv|us|fr|de|link|ly)\b\S*)/gi;

// 2026-09-22, DEFECT D: a first attempt came back corrupted end to end and was
// DELIVERED (gate exec 5780): " only be2509:00 September25:00 09Lisbon time, 09:00
// on 26 September, or 09:00 on 28 September - which which is closest.」use
// دdireidply,". None of the markers above fired. Three structural ones, each
// measured on the 538-text corpus (tests/fixtures/lead_texts_2026-09-22.json):
//   - a clock time fused to a letter on either side ("be2509:00", "09:00Lisbon"),
//     or digits fused to a capitalised word ("09Lisbon");
//   - a character outside the set a pt/en/es reply can contain: PR_ALLOWED_CHAR
//     below, defined explicitly (Latin with its accents, typographic punctuation,
//     currency, arrows and emoji). "」" and "د" are outside it;
//   - the same word twice in a row ("which which"), for words of 3+ letters.
const PR_ALLOWED_CHAR = new RegExp('^[' + [
  '\\t\\n\\r\\u0020-\\u007E',   // printable ASCII
  '\\u00A0-\\u00FF',             // Latin-1: NBSP, ¡ ¿ « » º ª °, accented letters
  '\\u0100-\\u017F',             // Latin Extended-A: names like Łukasz, Ōta
  '\\u0300-\\u036F',             // combining accents (decomposed text)
  '\\u2000-\\u206F',             // general punctuation: – — ‘ ’ “ ” … • and the zero-width joiner
  '\\u20A0-\\u20CF',             // currency symbols, €
  '\\u2100-\\u214F',             // letterlike: ™ №
  '\\u2190-\\u21FF',             // arrows
  '\\u2300-\\u23FF',             // technical: ⌚ ⏰
  '\\u2600-\\u27BF',             // misc symbols and dingbats: ☀ ✓ ✅ ❤
  '\\u2B00-\\u2BFF',             // ⭐ and arrows
  '\\uFE0E\\uFE0F',              // emoji variation selectors
].join('') + ']$');
const PR_EMOJI_RX = /\p{Extended_Pictographic}|\p{Emoji_Component}/u;
// "10:00h" is legitimate Portuguese, so a lone trailing h is not a fused word.
const PR_FUSED_TIME_RX = /[A-Za-zÀ-ÿ]\d{1,4}:\d{2}\b|\b\d{1,2}:\d{2}(?!h\b)[A-Za-zÀ-ÿ]|\b\d{1,2}[A-Z][a-z]{2,}/;
const PR_DOUBLED_WORD_RX = /(?<![\p{L}\p{N}])([\p{L}]{3,})\s+\1(?![\p{L}\p{N}])/iu;

function prForeignChar(t) {
  for (const ch of t) {
    if (PR_ALLOWED_CHAR.test(ch)) continue;
    if (PR_EMOJI_RX.test(ch)) continue;            // emoji beyond the BMP ranges above (🤖, 🏡)
    return ch;
  }
  return null;
}

function replyLooksBroken(s) {
  const t = (s || '').trim();
  if (t.length < 15) return 'too short (' + t.length + ' chars)';
  if (':;,.})]>'.includes(t[0])) return 'starts with punctuation: ' + JSON.stringify(t[0]);
  if (t.includes('{') || t.includes('}')) return 'contains a brace - JSON leaked into the reply';
  if (t.split(/\s+/).filter(Boolean).length < 3) return 'fewer than 3 words';
  if (!/[a-zA-ZÀ-ÿ]/.test(t)) return 'contains no letters';
  const m1 = t.match(/[,;]\s*[,;]/);
  if (m1) return 'doubled punctuation: ' + JSON.stringify(m1[0]);
  const m2 = t.replace(PR_DOMAIN_RX, ' ').match(/[a-zà-ÿ]{2}\.[a-zà-ÿ]{2}/);
  if (m2) return 'a full stop glued to the next word: ' + JSON.stringify(m2[0]);
  const m3 = t.match(PR_FUSED_TIME_RX);
  if (m3) return 'a time fused to a word: ' + JSON.stringify(m3[0]);
  const ch = prForeignChar(t);
  if (ch) return 'a character outside the reply alphabet: ' + JSON.stringify(ch) + ' (U+' + ch.codePointAt(0).toString(16).toUpperCase().padStart(4, '0') + ')';
  const m4 = t.match(PR_DOUBLED_WORD_RX);
  if (m4) return 'the same word twice: ' + JSON.stringify(m4[0]);
  return null;
}

// checkReplyShape(p) -> null | { errorType, errorMessage }
//
// 2026-09-21: an EMPTY reply is 'bad_reply', not 'bad_json'. Only bad_reply
// takes the one guard retry (IsRetryableReply), so an empty reply used to
// escalate the lead at once. It happened live: execution 4569 returned valid
// JSON with "reply": "" and everything else right, and the lead who had asked
// "11:00?" got the handoff note. Now it is re-asked once, and a second empty
// reply escalates as bad_reply_twice. A reply that is not a string at all, a
// missing key or a non-boolean needs_human is still bad_json: that is the
// schema failing, not the model leaving a field blank.
// On a lost-slot turn (src/lost_slot.js) the model is told to write {{LOST_SLOT}}
// where the system's sentence goes, and may write that alone. The reply is judged
// as the lead will receive it: the placeholder, and the mangled attempts at it
// that the assembler removes, stand for a well-formed sentence. Found on the
// 24 Sep gate: "{{LOST_SLOT}}" alone was "too short", and any reply carrying it
// "contains a brace", so every lost slot escalated as bad_reply_twice. A brace
// anywhere ELSE is still what it always was. tests/parse_reply.test.js holds
// these two constants equal to src/lost_slot.js's.
const PR_LOST_SLOT = '{{LOST_SLOT}}';
const PR_LOST_SLOT_MANGLED_RX = /[{[]{1,2}\s*lost[\s_-]?slot\s*[}\]]{1,2}/gi;
const PR_LOST_SLOT_STAND_IN = 'That time has just been taken by someone else.';

// checkReplyShape(p, opts) -> null | { errorType, errorMessage }
//   opts.lostSlot  true on a lost-slot turn (bookingIntent 'taken')
function checkReplyShape(p, opts) {
  if (!p || typeof p !== 'object' || Array.isArray(p)) return { errorType: 'bad_json', errorMessage: 'response is not an object' };
  const REQUIRED = ['reply', 'lead_type', 'stage', 'intent', 'wants_booking', 'needs_human'];
  for (const k of REQUIRED) if (!(k in p)) return { errorType: 'bad_json', errorMessage: 'missing key: ' + k };
  if (typeof p.reply !== 'string') return { errorType: 'bad_json', errorMessage: 'empty reply' };
  if (!p.reply.trim()) return { errorType: 'bad_reply', errorMessage: 'empty reply' };
  if (typeof p.needs_human !== 'boolean') return { errorType: 'bad_json', errorMessage: 'needs_human not boolean' };
  const judged = (opts && opts.lostSlot)
    ? p.reply.split(PR_LOST_SLOT).join(' ' + PR_LOST_SLOT_STAND_IN + ' ').replace(PR_LOST_SLOT_MANGLED_RX, ' ' + PR_LOST_SLOT_STAND_IN + ' ')
    : p.reply;
  const broken = replyLooksBroken(judged);
  if (broken) return { errorType: 'bad_reply', errorMessage: 'reply rejected: ' + broken };
  return null;
}

// allowedTimesFor(b) -> [{ timeLocal }] the time guard (src/time_guard.js)
// accepts. A booked viewing is restated from what we stored, so its time is
// legitimate even once the offer list has been cleared.
function allowedTimesFor(b) {
  const bookedTime = (b.bookingIntent === 'already_booked' && b.existingBooking) ? [b.existingBooking] : [];
  return (b.slots || []).concat((b.bookingSlot ? [b.bookingSlot] : []), bookedTime).map(s => ({
    timeLocal: s.timeLocal || (s.local ? String(s.local).slice(11, 16) : null) }));
}

// viewingClaimFailure(b, reply) -> null | { errorType, errorMessage }
//
// §0, and the instance that reached a real prospect. If no property has been
// named, the reply may not call the appointment a viewing -- "a sua visita esta
// confirmada" about a property nobody had ever identified. The condition is
// `!== 'viewing'`, not `=== 'meeting'`: if the field is ever missing the guard
// stays ON, which costs a retry; the other way round it silently stops running.
// Needs viewingClaim() from src/appointment_kind.js, embedded before this file.
function viewingClaimFailure(b, reply) {
  if (b.appointmentKind === 'viewing') return null;
  const vc = viewingClaim(reply);
  return vc ? { errorType: 'bad_reply',
                errorMessage: 'reply called the appointment a viewing when no property has been named: "' + vc + '"' } : null;
}

// saneBudgets(p) -> { rejected, budgetInconsistent }. MUTATES p.budget_min/max.
//
// Sanity-check extracted money before it is ever trusted downstream (spec 4.3):
// bad structured data is worse than absent structured data. An inverted pair
// is NOT nulled here (2026-09-12): the parser cannot interpret it without the
// row, MergeLeadFields can (src/budget_range.js), so both bounds go through
// with a flag.
function saneBudgets(p) {
  const rejected = [];
  const sane = (v) => {
    if (v === null || v === undefined) return null;
    const n = Number(v);
    if (!Number.isFinite(n)) return null;
    if (n < 1000 || n > 50000000) { rejected.push(n); return null; }
    return n;
  };
  p.budget_min = sane(p.budget_min);
  p.budget_max = sane(p.budget_max);
  const budgetInconsistent = p.budget_min !== null && p.budget_max !== null && p.budget_min > p.budget_max;
  return { rejected, budgetInconsistent };
}

// Defensive parse. Structured outputs (output_config.format) already constrain the
// response to the schema at the API level, so this is a BACKSTOP, not the primary
// mechanism - but it is not dead code: structured outputs do NOT hold when
// stop_reason is 'refusal' or 'max_tokens'.
const b   = $('BuildClaudeRequest').first().json;
const res = $input.first().json;
const started = b.claudeStartedAt;
const finished = new Date().toISOString();
const durationMs = Math.max(0, new Date(finished) - new Date(started));

// 2026-09-21: fail(), the response parse, the shape check, the allowed times,
// the viewing check and the budget check are src/parse_reply.js, shared with
// ParseClaude. What stays here is only where the two parsers DIFFER.
const fail = makeParseFail(b, durationMs, { wasGuardRetry: true });
const pr = parseModelResponse(res);
if (!pr.ok) return fail(pr.errorType, pr.errorMessage);
const body = pr.body;
const p = pr.parsed;

// ---------------------------------------------------------------------------
// SEMANTIC guard on the reply.
//
// Structured outputs guarantee the response matches the SCHEMA. They do not
// guarantee the reply is a sensible sentence. On 2026-09-03 a schema-valid
// response carried reply = ": corrigir - vou responder corretamente.}" and it
// was DELIVERED to a real lead. It parsed cleanly: a non-empty string in a
// string field. Only the content was broken.
//
// Not reproducible in 8 further runs, so this is rare rather than systematic --
// which is exactly why it needs a deterministic check rather than a better
// prompt. Structural markers only; nothing language-specific, since replies are
// pt-PT / en / es.
// ---------------------------------------------------------------------------
// §9.10, deterministically. The prompt says "offer only these times"; on
// 2026-09-04 the model was asked about a day that was NOT in AVAILABLE_SLOTS
// and answered "no sabado dia 12 tenho as 14:00 ou as 15:00" -- two times
// nobody had supplied. The never-invent probe suite scored 18/18 throughout,
// because every case in it asked about a day the list covered.
//
// So this is a check, not a better prompt. A time in the reply must appear in
// the list the workflow supplied; if none was supplied, no time may appear at
// all. A rejection routes into the existing guard-retry, and escalates if the
// retry also fails.
// ============================================================================
// The never-invent-a-time guard. Shared source.
//
// Embedded verbatim into ParseClaude and ParseGuardRetry, replacing the
// timesNotSupplied() each node carried inline. Unit-tested standalone in
// tests/time_guard.test.js, which loads THIS file.
//
// THE RULE (unchanged since 2026-09-12): a time in the reply must be one the
// workflow supplied. If none was supplied, no time may appear at all. A
// rejection routes into the guard retry, and escalates if the retry fails too.
//
// THE ONE EXEMPTION (2026-09-21): a time the LEAD named in their own message
// may appear in a clause that DECLINES it. Live check 2 of the language
// deploy: the lead asked "11:00?", 09:00 and 10:00 were offered, and both of
// the model's replies said, correctly, "11:00 isn't available, but I do have
// … 09:00 … or 10:00". The guard rejected both, because it could not tell
// NAMING a time from DECLINING one, and the lead was escalated for asking an
// ordinary question.
//
// WHAT THE EXEMPTION MUST NOT OPEN, in order of danger:
//   * accepting the lead's unoffered time: "11:00 it is", "11:00 works";
//   * declining it in one clause and affirming it in the next: "11:00 isn't
//     possible on Wednesday, but Thursday at 11:00 works". So the decision is
//     taken PER OCCURRENCE, in the clause around it, not per sentence;
//   * declining a time the lead never asked for, which is still the model
//     talking about a time nobody supplied;
//   * an invented alternative in a declining sentence: "11:00 isn't
//     available, but 14:00 is".
// Clauses split on contrast words and dashes, NOT on plain commas:
// "11:00, unfortunately, is taken" is one clause, and must stay one.
//
// NEGATION THAT GOVERNS THE TIME (2026-09-21, the first deploy gate). The
// model declined "11:00?" with "09:00 or 10:00 are available, but not 11:00",
// the guard rejected that and the retry, and the lead was escalated. This was
// the third decline shape the wording list missed ("quedamos entonces", then
// the plurals, now "but not X"). So instead of another phrase, a second test
// is added, taken PER OCCURRENCE: does a negation stand directly in front of
// THIS time, with nothing between them except a preposition or a day?
//   en  not (at) 11:00 · except (for) 11:00 ·
//       don't have an 11:00 · can't do 11:00 · no 11:00 slot
//   pt  não às 11:00 · menos às 11:00 · exceto / salvo às 11:00 ·
//       não consigo marcar às 11:00
//   es  no a las 11:00 · excepto / salvo / menos a las 11:00 ·
//       no puedo ofrecer las 11:00
// The rule is unchanged: the time must be one the LEAD named. And the
// negation must govern it:
//   * "why not 11:00", "if not 11:00", "porque não às 11:00", "¿por qué no a
//     las 11:00?" are proposals, never declines;
//   * "pelo menos às 11:00", "al menos a las 11:00" mean "at least", and
//     "mais ou menos", "más o menos" mean "around";
//   * "apart from", "other than", "besides", "tirando" are left out: "apart
//     from 11:00 we also have 09:00" ADDS the time rather than declining it;
//   * an EXCEPT that carves the time out of something UNAVAILABLE, or out of
//     a negation, or that sits beside "also", affirms it: "everything except
//     11:00 is taken", "nothing is free except 11:00". That is a rejection even when the
//     clause also reads as a decline. The clause-level rule alone accepted it
//     before 2026-09-21.
// ============================================================================

const TG_TIME_RX = /\b([01]?\d|2[0-3])[:h]([0-5]\d)\b/g;

function tgNorm(h, m) { return String(Number(h)) + ':' + m; }

function tgTimesIn(s) {
  return tgTimesAt(s).map(x => x.t);
}

// Every time in s, with where it starts: [{ t: '11:00', i: 17 }].
function tgTimesAt(s) {
  const out = [];
  const rx = new RegExp(TG_TIME_RX.source, 'g');
  let m;
  while ((m = rx.exec(String(s == null ? '' : s))) !== null) out.push({ t: tgNorm(m[1], m[2]), i: m.index });
  return out;
}

// What may stand between a negation and the time it governs: a day ("on
// Thursday", "na quinta dia 24", "el jueves 24 de septiembre") and a
// preposition ("at", "às", "a las"). Nothing else. Deaccented text.
const TG_DAY = '(?:(?:mon|tues|wednes|thurs|fri|satur|sun)day|(?:segunda|terca|quarta|quinta|sexta)(?:-feira)?|sabado|domingo|lunes|martes|miercoles|jueves|viernes)';
const TG_BRIDGE = '(?:(?:(?:on|this|next|na|no|nesta|neste|el|este)\\s+)?' + TG_DAY +
  '(?:\\s+(?:dia\\s+)?\\d{1,2}(?:\\s+(?:de\\s+)?[a-z]+)?)?\\s+)?' +
  '(?:(?:at|for|the|as|a|pelas|para as|a las|las|a la|para las)\\s+)?$';
// The negation words themselves, one per language, with the forms that do NOT
// negate what follows. Shared: the time guard's rule below and tgNegatedBefore()
// (which src/booking_claim.js calls) read these three and no other list.
// en. Not "why not", "if not", "or not", "whether not".
const TG_NEG_EN = "(?<!\\b(?:why|if|or|whether)\\s)\\bnot";
// pt. Not "porque não", "por que não", "se não", "ou não".
const TG_NEG_PT = "(?<!\\b(?:porque|por que|se|ou)\\s)\\bnao";
// es. Not "por qué no", "porque no", "si no", "o no".
const TG_NEG_ES = "(?<!\\b(?:por que|porque|si|o)\\s)\\bno";
// en contractions ("isn't", "won't"). NOT part of the time guard's own rule (its
// decline list carries those forms itself); shared for src/appointment_kind.js's
// viewing guard (22 Sep 2026), so "this isn't a viewing" is read as a denial.
const TG_NEG_EN_NT = "\\b(?:is|are|was|were|does|do|did|would|will|wo|could|ca)n'?t";
// A negation that governs the time after it.
const TG_NOT_BEFORE_RX = new RegExp('(?:' + [
  TG_NEG_EN,
  "\\b(?:(?:don'?t|do not|doesn'?t|does not)\\s+have|have no|haven'?t got)(?:\\s+(?:an?|the|any))?",
  "\\b(?:can'?t|cannot|can not)\\s+(?:do|offer|make|book)",
  TG_NEG_PT,
  "\\bnao\\s+(?:consigo|conseguimos|posso|podemos)\\s+(?:fazer|oferecer|marcar|agendar)",
  "\\bnao\\s+(?:tenho|temos|ha)(?:\\s+(?:vaga|disponibilidade))?",
  // es. A bare "no" governs only through a preposition: "pero no a las 11:00".
  TG_NEG_ES + "(?=\\s+(?:(?:a las|las|para las|a la)\\s+$|(?:el\\s+)?" + TG_DAY + "))",
  "\\bno\\s+(?:puedo|podemos)\\s+(?:hacer|ofrecer|agendar|reservar)",
  "\\bno\\s+(?:tengo|tenemos|hay)(?:\\s+(?:hueco|disponibilidad))?",
].join('|') + ')\\s+' + TG_BRIDGE);
// Does a negation govern whatever starts right after `before`? Deaccented,
// lower-cased text. The negation must END the text, optionally followed by one
// adverb: "ainda nao temos uma reuniao marcada" is negated at "temos"; "nao, temos
// a reuniao marcada" is not (the comma ends the negation's reach), and neither is
// "nao se preocupe, temos a reuniao marcada". Added 22 Sep 2026 for the claim
// guard (src/booking_claim.js): "Ainda não temos uma reunião marcada, João. Posso
// propor..." was read as a claim, both drafts rejected, the lead handed over
// (the booking gate, run 8).
const TG_NEGATED_BEFORE_RX = new RegExp('(?:' + [TG_NEG_EN, TG_NEG_PT, TG_NEG_ES].join('|') +
  ')\\s+(?:(?:ainda|ja|aun|todavia|yet|still|really|actually)\\s+)?$');
function tgNegatedBefore(before) {
  return TG_NEGATED_BEFORE_RX.test(String(before == null ? '' : before));
}

// "except" and its kin. They decline the time only when the rest of the clause
// is not about something UNAVAILABLE: "any time except 11:00" declines it,
// "everything except 11:00 is taken" offers it.
const TG_EXCEPT_BEFORE_RX = new RegExp('(?:' + [
  '\\bexcept(?:\\s+for)?',
  '\\b(?:exceto|excepto|salvo)', '(?<!\\b(?:pelo|ao|a|de|al|lo|o|ou)\\s)\\bmenos',
].join('|') + ')\\s+' + TG_BRIDGE);
const TG_UNAVAILABLE_RX = /\b(?:(?:taken|booked|full|unavailable|gone|not (?:available|free|open)|isn'?t (?:available|free|open)|aren'?t (?:available|free|open)|no longer)\b|ocupad|reservad|preenchid|lotad|complet|indisponiv|(?:nao|no) (?:esta|estao|estan|ha|hay) (?:disponiv|disponib|livre|libre))/;
// Before an except: a negation or "only" turns the except into an offer.
const TG_EXCEPT_INVERTS_RX = /\b(?:not|no|nothing|none|cannot|only|nao|nada|nenhum\w*|sem|apenas|so|sin|ningun\w*|solo|solamente)\b|n't\b/;
// Anywhere in the clause: an except beside "also" adds the time.
const TG_ADDITIVE_RX = /\b(?:also|too|as well|tambem|alem|tambien|ademas)\b/;
// After the time: "there's no 11:00 slot", "no 11:00 opening".
const TG_NO_BEFORE_RX = /\bno\s+$/;
const TG_SLOT_AFTER_RX = /^\s*(?:slot|opening|appointment|availability)\b/;

// governs(clause, i) -> 'declined' | 'carved' | null, for the time at clause[i].
function tgGoverned(clause, i) {
  const before = clause.slice(0, i);
  const after = clause.slice(i).replace(/^\S+/, '');
  const ex = before.match(TG_EXCEPT_BEFORE_RX);
  if (ex) {
    const lead = before.slice(0, ex.index);
    return (TG_UNAVAILABLE_RX.test(clause) || TG_EXCEPT_INVERTS_RX.test(lead) || TG_ADDITIVE_RX.test(clause)) ? 'carved' : 'declined';
  }
  if (TG_NOT_BEFORE_RX.test(before)) return 'declined';
  if (TG_NO_BEFORE_RX.test(before) && TG_SLOT_AFTER_RX.test(after)) return 'declined';
  return null;
}

// A clause that declines. Deaccented, lower-cased text. Each language's forms,
// singular and plural. The list is measured against real replies in
// tests/time_guard.test.js; a shape it misses is a false escalation (annoying),
// never a false acceptance, because the exemption only ever ALLOWS a declined
// time the lead asked for.
const TG_DECLINE_RX = new RegExp([
  // en. A negation counts only when it governs an availability word: "no
  // problem, 17:00 then" must never read as a decline.
  "\\b(?:isn'?t|is not|aren'?t|are not|not|no longer|won'?t be|can'?t (?:do|offer|make)|cannot (?:do|offer|make))\\b[^.;]{0,30}?\\b(?:available|free|possible|an option|open|doable)\\b",
  "\\bnot available\\b", "\\bunavailable\\b",
  "\\b(?:already (?:taken|booked)|fully booked|booked up|is taken|are taken)\\b",
  "\\bno (?:availability|slot|slots|opening|openings)\\b",
  "\\b(?:don'?t|do not) have (?:availability|anything|a slot|slots|that time|an opening)\\b",
  "\\b(?:can'?t|cannot) offer\\b",
  // 22 Sep 2026: the slot another lead has just taken. TAKEN and GONE only, never
  // "booked": a decline lets the lead's own time through, and "your meeting was
  // just booked for 11:00" must never be read as one.
  "\\b(?:was|were|has been|have been|got) (?:just )?taken\\b(?! care)", "\\bjust (?:been |got )?(?:taken|gone)\\b(?! care)",
  "\\b(?:has|have) (?:just )?gone\\b",
  "\\b(?:taken|booked|reserved) by (?:someone else|somebody else|another (?:client|person|customer|lead))\\b",
  // pt. Same rule: "nao ha problema" is not a decline.
  "\\bnao (?:esta|estao|temos|tenho|ha|existe|existem|e|sera|fica|ficam)\\b[^.;]{0,25}?\\b(?:disponiv|disponibilidade|livre|possiv|vaga|aberto|opcao)",
  "\\bindisponive(?:l|is)\\b",
  "\\bja (?:esta|estao) (?:ocupad|preenchid|reservad)", "\\b(?:esta|estao) (?:ocupad|preenchid)",
  "\\bsem disponibilidade\\b", "\\bnao (?:consigo|conseguimos|posso|podemos) (?:oferecer|marcar|agendar|disponibilizar)",
  // 22 Sep 2026: "ficou ocupado", "acabou de ser ocupado". Never "marcado": see en.
  // "Reservado" only with WHO took it: "acabou de ser reservado por outra pessoa"
  // (the booking gate, run 5). Kept narrow: someone ELSE, never the lead's own booking.
  "\\b(?:reservad|marcad|ocupad)[oa]s? por (?:outra pessoa|outro cliente|outra cliente|outras pessoas|alguem)\\b",
  "\\b(?:ficou|ficaram|foi|foram) (?:entretanto |agora |ja )?(?:ocupad|preenchid)", "\\bacab(?:ou|aram) de (?:ser |ficar )?(?:ocupad|preenchid)",
  // es. "no hay problema" is not a decline.
  "\\bno (?:esta|estan|tenemos|tengo|hay|es|sera|queda|quedan)\\b[^.;]{0,25}?\\b(?:disponib|libre|posible|hueco|opcion)",
  "\\bya (?:esta|estan) (?:ocupad|reservad|complet)", "\\b(?:esta|estan) (?:ocupad|complet)",
  "\\bsin disponibilidad\\b", "\\bno (?:puedo|podemos) (?:ofrecer|agendar|reservar)",
  // 22 Sep 2026, the booking gate's run 9: "Ese horario de las 16:00 se acaba de
  // ocupar"; run 6: "acaba de ocuparse". Never "reservado" alone: see en.
  "\\b(?:reservad|ocupad|cogid)[oa]s? por (?:otra persona|otro cliente|otra clienta|otras personas|alguien)\\b",
  "\\bse (?:acaba|acaban) de ocupar\\b", "\\bacaba(?:n)? de ocupar(?:se)?\\b", "\\bacaba(?:n)? de (?:ser |quedar )?ocupad", "\\bse (?:ocupo|ocuparon)\\b", "\\b(?:quedo|quedaron) (?:ya )?ocupad",
].join('|'));

// Contrast words and dashes end a clause. Deaccented text.
const TG_CLAUSE_SPLIT_RX = /\s*;\s*|\s+[-–—]\s+|\s*—\s*|,?\s+\b(?:but|however|though|although|whereas|instead|mas|porem|contudo|no entanto|pero|sin embargo|en cambio)\b/;

// Typographic apostrophes are folded to ' before any pattern runs (21 Sep 2026,
// the gate that passed 61f50cc: "11:00 isn’t available", U+2019, was rejected
// because every pattern here is written with a straight quote).
function tgDeaccent(s) {
  return String(s == null ? '' : s).replace(/[\u2018\u2019\u201B\u02BC\u2032\uFF07\u00B4\u0060]/g, "'")
    .normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// Which time each clause-level decline is ABOUT: the occurrence nearest to it.
// Before 2026-09-21 (the first deploy gate) a decline anywhere in the clause
// exempted every lead-named time in it, so "10:00 isn't available, so 11:00 it
// is" let 11:00 through. And the bare sentiment words ("unfortunately",
// "infelizmente", "lamentablemente"...) no longer decline on their own:
// "Sadly I had to move things, 11:00 is yours" was accepted.
// -> Set of the start indexes of declined occurrences.
function tgDeclinedOccurrences(clause, times) {
  const out = new Set();
  if (!times.length) return out;
  const rx = new RegExp(TG_DECLINE_RX.source, 'g');
  let m;
  while ((m = rx.exec(clause)) !== null) {
    const a = m.index, b = m.index + m[0].length;
    let best = null, bestD = Infinity;
    for (const x of times) {
      const e = x.i + x.t.length;
      const d = e <= a ? a - e : (x.i >= b ? x.i - b : 0);
      if (d < bestD) { bestD = d; best = x; }
    }
    if (best) out.add(best.i);
    if (m[0].length === 0) rx.lastIndex++;
  }
  return out;
}

// timesNotSupplied(reply, slots, leadText) -> the times the reply named that
// nothing supplied, e.g. ['14:00']. Empty means the reply passes.
//   slots     [{timeLocal: 'HH:MM'}, ...]: offered, booked or stored times
//   leadText  the lead's current message (optional: without it there is no
//             exemption, which is the pre-2026-09-21 behaviour)
function timesNotSupplied(reply, slots, leadText) {
  const supplied = new Set();
  for (const s of (slots || [])) {
    const m = String((s && s.timeLocal) || '').match(/^(\d{1,2}):(\d{2})$/);
    if (m) supplied.add(tgNorm(m[1], m[2]));
  }
  const leadTimes = new Set(tgTimesIn(leadText));
  const bad = new Set();
  const sentences = String(reply == null ? '' : reply).split(/(?<=[.!?\n])\s+|\n+/);
  for (const sentence of sentences) {
    for (const clause of tgDeaccent(sentence).split(TG_CLAUSE_SPLIT_RX)) {
      if (!clause) continue;
      const times = tgTimesAt(clause);
      const declinedAt = tgDeclinedOccurrences(clause, times);
      for (const { t, i } of times) {
        if (supplied.has(t)) continue;
        if (!leadTimes.has(t)) { bad.add(t); continue; }
        const governed = tgGoverned(clause, i);
        if (governed === 'declined') continue;
        if (governed === 'carved') { bad.add(t); continue; }
        if (declinedAt.has(i)) continue;
        bad.add(t);
      }
    }
  }
  return [...bad];
}

// 24 Sep 2026: on a lost-slot turn the reply is judged as it will be sent (src/parse_reply.js).
const shape = checkReplyShape(p, { lostSlot: b.bookingIntent === 'taken' });
if (shape) return fail(shape.errorType, shape.errorMessage);

const allowed = allowedTimesFor(b);
// 2026-09-21: the lead's own message is passed so a clause DECLINING the
// time they asked for is not read as inventing it (src/time_guard.js).
const invented = timesNotSupplied(p.reply, allowed, b.body);
// 2026-09-14: the offer the lead was SHOWN is what the merge must store, whether
// or not the model flagged wants_booking. See slotsNamedIn in src/booking_stated.js.
const replyNamedSlots = slotsNamedIn(p.reply, b.slots || []);
// 24 Sep 2026: on a lost-slot turn ('taken') the sentence carrying the times is
// the system's (src/lost_slot.js), and prose that names a time is dropped there
// with a warning. Rejecting it here would retry, then escalate a lead who only
// needs the remaining times.
if (invented.length && b.bookingIntent !== 'taken') {
  return fail('bad_reply', 'reply named times the workflow never supplied: ' + invented.join(', '));
}



// §0, and this is the instance that reached a real prospect. Before the model
// wrote anything, the workflow established whether a property has a name. If it
// does not, the reply may not call the appointment a viewing -- "a sua visita
// esta confirmada" about a property nobody had ever identified.
//
// The prompt says this too. The prompt is not the guard: on 2026-09-05 the same
// prompt already forbade asserting anything the model could not see.
//
// Note the condition is `!== 'viewing'`, not `=== 'meeting'`. If the field is
// ever missing the guard stays ON, which costs a retry; the other way round it
// silently stops running and this defect returns unannounced.
const vcf = viewingClaimFailure(b, p.reply);
if (vcf) return fail(vcf.errorType, vcf.errorMessage);

// 2026-09-12: a reply may assert an existing appointment ONLY when the workflow
// holds one or is creating one this turn. Otherwise "ja tem uma reuniao
// marcada" is the model repeating a confirmation the calendar has since lost.
// Second line of defence -- the BOOKING STATUS note in the prompt is the fix;
// this catches the common shapes and fails loudly (retry, then escalate).
const holdsBooking = b.bookingIntent === 'already_booked' && !!b.existingBooking;
const creatingBooking = b.bookingIntent === 'confirm' && !!b.bookingSlot;
if (!holdsBooking && !creatingBooking) {
  const bcm = bookingClaim(p.reply);
  if (bcm) {
    return fail('bad_reply',
      'reply asserted an appointment the workflow does not hold: "' + bcm + '"');
  }
}

// 2026-09-12: second look at the reply language. If it is STILL wrong after the
// targeted retry, the reply is delivered anyway and the mismatch is recorded
// (payload + a warning event downstream): a wrong-language reply the lead can
// correct in one message beats the AI going silent for a fault nobody in the
// conversation can see.
const lm = replyLanguageMismatch(b.body, p.reply, { name: (b.priorLead || {}).full_name, leadLang: b.leadLang || null });
let languageRetried = false;
try { languageRetried = !!$('ParseClaude').first().json.languageMismatch; } catch (e) { languageRetried = false; }

const cfg = b.config || {};
// 2026-09-13: second look at the name. Still wrong after the targeted retry:
// deliver, flag, and let the warning event downstream make it visible.
const nmAllow = [cfg.agent_name, cfg.agency_name].concat(cfg.areas || []);
const nmc = nameMismatch(p.reply, b.statedName || null, { allow: nmAllow });
let nameRetried = false;
try { nameRetried = !!$('ParseClaude').first().json.nameMismatch; } catch (e) { nameRetried = false; }

// 2026-09-13: the retry was told to state the booking. If it still does not,
// the booking is WITHHELD this turn: no event, the offer stays on the row, the
// reply goes out, and a warning event records it. A booking that did not
// happen costs one message; a booking the lead was never told about does not
// surface until someone turns up.
const bookingWithheld = !!(creatingBooking && !replyStatesSlot(p.reply, b.bookingSlot));

// Sanity-check extracted money before it is ever trusted downstream (spec 4.3).
// Bad structured data is worse than absent structured data.
const { rejected, budgetInconsistent } = saneBudgets(p);

return [{ json: { ...b, wasGuardRetry: true, ok: true, errorType: null, errorMessage: null, durationMs,
                  usage: body.usage || null, modelUsed: body.model || null,
                  rejectedBudgets: rejected, budgetInconsistent, replyNamedSlots, bookingWithheld, nameMismatch: !!nmc.mismatch, nameUsed: nmc.used, nameRetried, languageMismatch: !!lm.mismatch, languageRetried, leadLang: lm.leadLang, replyLang: lm.replyLang, parsed: p } }];

// ============================================================================
// Deterministic language detection for SYSTEM messages — Checkpoint D2.
//
// WHY THIS IS NOT A MODEL CALL
// The handoff note is the message sent when the Concierge cannot answer: the
// model refused, returned unparseable JSON twice, or produced a reply that had
// to be discarded. It is the one message that must still work *when the model
// has failed*, which rules out asking a model — either to write it or to say
// what language to write it in.
//
// So: fixed strings from config, keyed by language, chosen by the rules below.
//
// This is a classifier for THREE known languages on SHORT messages, not a
// general-purpose one. It is allowed to be unsure, and being unsure is safe:
// an undecided result falls back to the client's configured default rather
// than guessing. Sending Portuguese to a Portuguese lead is the win; sending
// Spanish to a Portuguese lead because two words matched is worse than the
// English we send today.
// ============================================================================

// Accented and punctuation marks that occur in ONE of the three languages and
// effectively settle it on their own. Checked before normalisation, because
// stripping diacritics destroys exactly the signal that discriminates pt from
// es -- the two languages that actually get confused.
const HARD_MARKERS = [
  { lang: 'pt', rx: /[ãõ]/, weight: 6 },          // não, mão, então, opções
  { lang: 'pt', rx: /ç/, weight: 5 },             // preço, começar
  { lang: 'es', rx: /ñ/, weight: 6 },             // mañana, año, señor
  { lang: 'es', rx: /[¿¡]/, weight: 6 },          // inverted punctuation
];

// Function words and greetings. Deliberately excludes anything the three share
// (que, para, no, si/sim, por favor, esta) -- a shared word is not evidence.
// Function words. Only DISCRIMINATING tokens: anything the languages share
// (que, para, no, casa, como, por favor) is not evidence and is excluded.
// The pt/es minimal pairs do most of the work here -- com/con, uma/una,
// quando/cuando, muito/mucho -- because those two are the pair that actually
// gets confused.
const WORD_MARKERS = {
  pt: ['nao', 'obrigado', 'obrigada', 'ola', 'voce', 'gostaria', 'queria',
       'muito', 'estou', 'tenho', 'tem', 'quero', 'bom dia', 'boa tarde',
       'boa noite', 'feira', 'imovel', 'imoveis', 'moradia', 'preciso',
       'gostava', 'entao', 'onde', 'com', 'uma', 'um', 'quando', 'quanto',
       'qual', 'mais', 'na', 'nas', 'dos', 'das', 'ate', 'posso', 'pode',
       'procuro', 'visitar', 'marcar', 'falar', 'pessoa', 'afinal', 'mudar',
       // 2026-09-21: weekdays and parts of the day that only pt uses. es says
       // lunes..viernes, and sabado/domingo/tarde are shared, so they stay out.
       'segunda', 'terca', 'quarta', 'quinta', 'sexta', 'manha', 'amanha',
       'fica', 'serve', 'combinado', 'perfeito', 'otimo'],
  es: ['hola', 'gracias', 'quisiera', 'usted', 'tambien', 'buenos dias',
       'buenas tardes', 'buenas noches', 'vivienda', 'piso', 'necesito',
       'busco', 'con', 'una', 'cuando', 'cuanto', 'donde', 'ahora', 'manana',
       'el', 'los', 'las', 'muy', 'mucho', 'estoy', 'tengo', 'puedo',
       'hablar', 'jueves', 'viernes', 'quiero',
       // 2026-09-21: the other weekdays es alone uses, and short replies.
       'lunes', 'martes', 'miercoles', 'viene', 'vale', 'perfecto', 'genial'],
  en: ['the', 'and', 'you', 'are', 'is', 'would', 'like', 'hello', 'hi',
       'thanks', 'thank', 'please', 'can', 'i', 'im', 'looking', 'house',
       'flat', 'apartment', 'available', 'viewing', 'week', 'time', 'do',
       'have', 'see', 'come', 'speak', 'person', 'anything', 'something',
       // 2026-09-21: "Ok let's go with Thursday morning" scored 0 in every
       // language, so no REPLY LANGUAGE note was sent and 4 of 5 replies came
       // back in Portuguese. A booking reply is short and made of exactly these
       // words: weekdays, parts of the day, and the function words around them.
       // Only words pt and es never use: not 'ok', 'no', 'me', 'a' or 'sim'.
       'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday',
       'sunday', 'morning', 'afternoon', 'evening', 'tonight', 'tomorrow',
       'today', 'next', 'lets', "let's", 'go', 'with', 'works', 'sounds',
       'good', 'great', 'perfect', 'that', 'this', 'what', 'when', 'which',
       'at', 'for', 'yes', 'sure', 'fine', 'its', "it's", 'how', 'about'],
};

const SUPPORTED = ['pt', 'en', 'es'];

// detectLanguage(text) -> {lang: 'pt'|'en'|'es'|null, scores, confident}
// Returns null when the evidence is thin or the top two are close. Callers
// must treat null as "use the configured default", never as a language.
function detectLanguage(text) {
  const raw = String(text || '');
  const out = (lang, scores, confident) => ({ lang, scores, confident });
  if (!raw.trim()) return out(null, { pt: 0, en: 0, es: 0 }, false);

  // Typographic apostrophes folded to ' (21 Sep 2026): a phone keyboard turns
  // "let's" into "let’s" (U+2019), and the word pass below kept only [a-z0-9'],
  // so "let’s" became "let s" and matched neither "let's" nor "lets".
  const lower = raw.replace(/[\u2018\u2019\u201B\u02BC\u2032\uFF07\u00B4\u0060]/g, "'").toLowerCase();
  const scores = { pt: 0, en: 0, es: 0 };

  for (const m of HARD_MARKERS) {
    if (m.rx.test(lower)) scores[m.lang] += m.weight;
  }

  // Normalise for word matching so "voce"/"você" and "manana"/"mañana" both
  // land, having already banked the diacritic evidence above.
  const flat = ' ' + lower.normalize('NFD').replace(/[̀-ͯ]/g, '')
                          .replace(/[^a-z0-9']+/g, ' ').trim() + ' ';
  for (const lang of SUPPORTED) {
    for (const w of WORD_MARKERS[lang]) {
      const needle = w.includes(' ') ? w : ' ' + w + ' ';
      if (flat.includes(needle)) scores[lang] += 2;
    }
  }

  const ranked = SUPPORTED.slice().sort((a, b) => scores[b] - scores[a]);
  const top = ranked[0], second = ranked[1];
  // A single weak hit decides nothing, and a near-tie between pt and es is the
  // case most likely to be wrong. Both fall back rather than guess.
  // Two ways to be sure, and they cover different shapes of message:
  //   - unopposed: any evidence at all for exactly one language, none for the
  //     others. "Ola, procuro casa em Cascais" is short but unambiguous.
  //   - contested: enough evidence AND a clear margin. This is the pt/es case,
  //     where both score and the winner has to actually win.
  // Everything else falls back to the configured default rather than guessing.
  const unopposed = scores[top] >= 2 && scores[second] === 0;
  const contested = scores[top] >= 4 && (scores[top] - scores[second]) >= 4;
  const confident = unopposed || contested;
  return out(confident ? top : null, scores, confident);
}

// resolveLeadLanguage(text, priorInbound) -> {lang, source}
//
// The language to STATE for this reply. 2026-09-21: the current message alone
// decided it, and a short reply the detector cannot read ("ok, Thursday 15h")
// stated nothing, so the model drifted to the prompt's Portuguese. A lead does
// not change language by writing briefly, so an undecided message inherits the
// language of the lead's most recent message that WAS decided.
//   source: 'message'  the current message decided it
//           'history'  inherited from an earlier inbound message
//           null       nothing decided it (a first message the detector
//                      cannot read), and nothing is stated
// `priorInbound` is the lead's earlier messages as text, NEWEST FIRST. Only
// the lead's own words count: the assistant writes in whatever it was told,
// so its messages are not evidence of the lead's language.
function resolveLeadLanguage(text, priorInbound) {
  const now = detectLanguage(text);
  if (now.lang) return { lang: now.lang, source: 'message' };
  for (const t of (Array.isArray(priorInbound) ? priorInbound : [])) {
    const d = detectLanguage(t);
    if (d.lang) return { lang: d.lang, source: 'history' };
  }
  return { lang: null, source: null };
}

// pickMessage(messages, lang, fallbackLang) -> string|null
//
// `messages` is the config map, e.g. {pt: '...', en: '...', es: '...'}. Resolution
// order is: detected language -> the client's configured default -> English ->
// whatever single string was configured. Every step is a fixed string; nothing
// here is generated.
function pickMessage(messages, lang, fallbackLang) {
  if (typeof messages === 'string') return messages;          // legacy single string
  if (!messages || typeof messages !== 'object') return null;
  const order = [lang, fallbackLang, 'en', 'pt'];
  for (const k of order) {
    if (k && typeof messages[k] === 'string' && messages[k].trim()) return messages[k];
  }
  const first = Object.values(messages).find(v => typeof v === 'string' && v.trim());
  return first || null;
}

// Convenience: resolve a named system message for a lead's text in one call.
// `cfg` is client_automations.config.
//
// `priorInbound` (optional, 2026-09-21): the lead's earlier messages, NEWEST
// FIRST. An English lead who asks for a person in words the lists cannot read
// ("Talk to a human") inherits English from history (resolveLeadLanguage)
// rather than getting the client's default. `detected` stays the current
// message's own verdict, and `source` says where `lang` came from:
// 'message' | 'history' | null (the configured default).
function systemMessage(cfg, name, leadText, priorInbound) {
  const c = cfg || {};
  const det = detectLanguage(leadText);
  const res = resolveLeadLanguage(leadText, priorInbound);
  const fallback = c.default_language
    || (Array.isArray(c.languages) && c.languages.length ? c.languages[0] : 'en');
  const bag = (c.system_messages || {})[name];
  const picked = pickMessage(bag, res.lang, fallback);
  return {
    text: picked || c.handoff_note || null,
    lang: res.lang || fallback,
    detected: det.lang,
    source: res.source,
    confident: det.confident,
    scores: det.scores,
  };
}


// Convergence point for every post-parse path. Downstream nodes read
// $('DecideEscalation') rather than $('ParseClaude'), because either the first
// parse OR the guard retry may have produced the item.
const j   = $input.first().json;
const a   = $('AfterLead').first().json;
const cfg = a.config || {};
const p   = j.parsed || null;
const sl  = $('ProposeSlots').first().json;
const mc  = $('ResolveBooking').first().json;   // the VERIFIED booking state, not the stored claim

// 2026-09-21: the note inherits the lead's language from history when this
// message is unreadable ("Talk to a human"). BuildClaudeRequest runs before
// this node on every path; the guard is for safety, not expectation.
let deePrior = []; try { deePrior = $('BuildClaudeRequest').first().json.leadPriorInbound || []; } catch (e) { deePrior = []; }
const HANDOFF = systemMessage(cfg, 'handoff', a.body, deePrior);

// ---------------------------------------------------------------------------
// A booking found cancelled or missing THIS TURN always escalates, and the
// lead is ALWAYS told, in a fixed string. On 2026-09-12 the model escalated
// this case itself with a perfectly good reason -- and the escalation path
// discarded its reply and sent the generic handoff note, so a lead who asked
// "esta tudo confirmado?" was told a colleague would be in touch and nothing
// else. They still believed they had a meeting. A real buyer turns up.
//
// Deterministic, like every other system message: not the model's reply
// (which is discarded on escalation by design) and not a prompt instruction
// (which is the layer that fails). `{when}` is rendered here, in the lead's
// language and the client's zone. The fixed text is overridable per client via
// config.system_messages.booking_retired; these are the defaults.
// ---------------------------------------------------------------------------
const RETIRED_DEFAULT = {
  pt: 'A marcação que tínhamos para {when} já não está na nossa agenda. Peço desculpa pelo incómodo. Um colega da equipa vai entrar em contacto consigo em breve para combinar uma nova hora.',
  en: 'The appointment we had booked for {when} is no longer in our diary. I am sorry for the inconvenience. A member of our team will be in touch with you shortly to arrange a new time.',
  es: 'La cita que teníamos para {when} ya no está en nuestra agenda. Disculpe las molestias. Un compañero del equipo se pondrá en contacto con usted en breve para acordar una nueva hora.',
};
const rb = mc.bookingRetired || null;
const retiredGone = !!rb && (mc.bookingCheck === 'cancelled' || mc.bookingCheck === 'missing');
let RETIRED_NOTE = null;
if (retiredGone) {
