// ============================================================================
// Slot engine — shared source. Embedded verbatim into the ProposeSlots Code
// node, and unit-tested standalone against non-Lisbon timezones.
//
// §4: the test environment has calendar, config and cron all agreeing on
// Europe/Lisbon. That agreement HIDES timezone bugs rather than revealing them,
// so nothing here may hardcode a zone and every case below is exercised against
// Europe/Madrid (+1 vs Lisbon) as well.
//
// Everything is computed and stored in UTC. The client timezone is used at
// exactly three edges: filtering to working hours, formatting for the lead, and
// setting the calendar event's zone.
// ============================================================================
// ---------------------------------------------------------------------------
// Google free/busy returns HTTP 200 for a calendar it cannot read, with an
// `errors` array and an EMPTY `busy` list. An unreachable or misconfigured
// calendar is therefore indistinguishable from a totally free one unless the
// errors array is read. Unguarded, that offers every slot in the window as
// available. Verified against the live API on 2026-09-03.
function readFreeBusy(httpResponse, calendarId) {
  const res = httpResponse || {};
  const code = res.statusCode;
  if (!(code >= 200 && code < 300)) {
    return { ok: false, busy: [], error: 'freebusy_http_' + code };
  }
  const cals = (res.body && res.body.calendars) || null;
  if (!cals) return { ok: false, busy: [], error: 'freebusy_malformed' };
  const entry = cals[calendarId];
  if (!entry) return { ok: false, busy: [], error: 'freebusy_calendar_absent' };
  if (Array.isArray(entry.errors) && entry.errors.length) {
    const reason = entry.errors.map(e => e.reason || 'unknown').join(',');
    return { ok: false, busy: [], error: 'freebusy_calendar_error:' + reason };
  }
  return { ok: true, busy: Array.isArray(entry.busy) ? entry.busy : [], error: null };
}

// ---------------------------------------------------------------------------
// A lightweight, workflow-side date HINT.
//
// The slots must be in Claude's prompt before it replies, and Checkpoint C2
// needs the workflow to know exactly which slots were offered -- so the model
// cannot be the one choosing them. That rules out taking the preferred day from
// the model's output on the same turn.
//
// This produces a CANDIDATE date only. Every guard in computeSlots still
// applies, and anything unrecognised or invalid falls back silently to
// spreading. The worst failure is an uneven spread, never a wrong or
// unavailable time.
const WEEKDAYS = {
  1: ['segunda', 'monday', 'lunes'],
  2: ['terca', 'tuesday', 'martes'],
  3: ['quarta', 'wednesday', 'miercoles'],
  4: ['quinta', 'thursday', 'jueves'],
  5: ['sexta', 'friday', 'viernes'],
  6: ['sabado', 'saturday'],
  7: ['domingo', 'sunday'],
};
function extractPreferredDate(text, tz, nowISO) {
  if (!text) return null;
  // Strip diacritics first. A JS \\b after "ã" never matches, because an accented
  // character is not a word character -- so "amanhã?" failed while "tomorrow"
  // worked. Normalising also removes the need to enumerate accented variants.
  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const now = DateTime.fromISO(nowISO, { zone: 'utc' }).setZone(tz);

  if (/\b(hoje|today|hoy)\b/.test(t)) return now.toFormat('yyyy-LL-dd');
  if (/\b(amanha|tomorrow|manana)\b/.test(t)) {
    return now.plus({ days: 1 }).toFormat('yyyy-LL-dd');
  }
  // "dia 12", "no dia 12 de setembro". Without this, "sabado dia 12" matched
  // only the weekday and resolved to the NEXT Saturday -- so a request for the
  // 12th was answered with slots for the 5th, and the model then invented times
  // for the day it had been asked about. Checked before the weekday branch for
  // exactly that reason.
  const dia = t.match(/\bdia\s+(\d{1,2})\b/);
  if (dia) {
    const day = Number(dia[1]);
    for (let i = 0; i < 400; i++) {
      const d = now.plus({ days: i });
      if (d.day === day) return d.toFormat('yyyy-LL-dd');
    }
    return null;
  }

  // Explicit dd/mm or dd-mm, year optional.
  const m = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})(?:[\/\-.](\d{2,4}))?\b/);
  if (m) {
    const day = Number(m[1]), mon = Number(m[2]);
    let year = m[3] ? Number(m[3]) : now.year;
    if (year < 100) year += 2000;
    const d = DateTime.fromObject({ year, month: mon, day }, { zone: tz });
    if (d.isValid) {
      // A bare dd/mm already past this year means next year.
      return (!m[3] && d < now.startOf('day') ? d.plus({ years: 1 }) : d).toFormat('yyyy-LL-dd');
    }
    return null;
  }
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) {
      const target = Number(wd);
      // "next <weekday>" means the coming one; today does not count, because a
      // same-day request will fail min_hours_notice anyway.
      let d = now.plus({ days: 1 }).startOf('day');
      for (let i = 0; i < 7; i++) {
        if (d.weekday === target) return d.toFormat('yyyy-LL-dd');
        d = d.plus({ days: 1 });
      }
    }
  }
  return null;
}

function computeSlots(opts) {
  const {
    nowISO,                    // UTC instant, ISO
    tz,                        // IANA zone from client config -- never a literal
    workingHours,              // {start:'09:00', end:'19:00', days:[1..6]}
    bookingWindowDays,
    minHoursNotice,
    durationMinutes,
    busy,                      // [{start,end}] ISO UTC, from free/busy
    maxSlots,
    preferDate,                // optional 'YYYY-MM-DD' in tz; soft preference
    slotStepMinutes,
  } = opts;

  const step = slotStepMinutes || 60;
  const max = maxSlots || 3;
  const now = DateTime.fromISO(nowISO, { zone: 'utc' });
  if (!now.isValid) throw new Error('bad nowISO');

  const zone = tz;
  const earliest = now.plus({ hours: minHoursNotice });     // never "in 20 minutes"
  const windowEnd = now.plus({ days: bookingWindowDays });

  const busyIv = (busy || []).map(b => ({
    s: DateTime.fromISO(b.start, { zone: 'utc' }),
    e: DateTime.fromISO(b.end, { zone: 'utc' }),
  })).filter(x => x.s.isValid && x.e.isValid);

  const overlaps = (s, e) => busyIv.some(b => s < b.e && e > b.s);

  const [sh, sm] = String(workingHours.start).split(':').map(Number);
  const [eh, em] = String(workingHours.end).split(':').map(Number);
  const allowedDays = new Set(workingHours.days || [1, 2, 3, 4, 5, 6]);

  // Walk calendar days in the CLIENT's zone, not UTC -- a day boundary in
  // Lisbon is not a day boundary in Madrid.
  const perDay = [];
  const perDayAll = [];
  let cursor = now.setZone(zone).startOf('day');
  const lastDay = windowEnd.setZone(zone).endOf('day');

  while (cursor <= lastDay) {
    if (allowedDays.has(cursor.weekday)) {          // Luxon: 1=Mon .. 7=Sun
      const dayStart = cursor.set({ hour: sh, minute: sm, second: 0, millisecond: 0 });
      const dayEnd = cursor.set({ hour: eh, minute: em, second: 0, millisecond: 0 });
      const free = [];
      let eligible = 0;
      // Re-derive from the day, so a DST transition inside the day is applied
      // by Luxon rather than by adding fixed offsets.
      for (let t = dayStart; t.plus({ minutes: durationMinutes }) <= dayEnd; t = t.plus({ minutes: step })) {
        const sUtc = t.toUTC();
        const eUtc = t.plus({ minutes: durationMinutes }).toUTC();
        if (sUtc < earliest) continue;              // past, or inside notice period
        if (eUtc > windowEnd) continue;             // beyond the booking window
        eligible++;                                 // would be offerable if free
        if (overlaps(sUtc, eUtc)) continue;         // busy
        free.push({
          startUtc: sUtc.toISO(),
          endUtc: eUtc.toISO(),
          startLocal: t.toISO(),
          dateLocal: t.toFormat('yyyy-LL-dd'),
          timeLocal: t.toFormat('HH:mm'),
          zone,
        });
      }
      // `eligible` counts slots that clear the past/notice/window tests but
      // ignores busy. It is the only way to tell "that day is booked up" from
      // "that day is too soon" -- and saying the wrong one is asserting a cause
      // the system does not actually know.
      if (eligible || free.length) {
        perDayAll.push({ date: cursor.toFormat('yyyy-LL-dd'), free, eligible });
      }
      if (free.length) perDay.push({ date: cursor.toFormat('yyyy-LL-dd'), free });
    }
    cursor = cursor.plus({ days: 1 });
  }

  // ---------------------------------------------------------------------
  // preferDate comes from the MODEL (it extracts "quinta-feira" from the
  // lead's message), so it is validated before it is allowed to influence
  // anything. It affects ORDERING and INCLUSION only -- never eligibility.
  // A slot that is not genuinely free can never be surfaced by preferring it.
  // Any failed check falls back silently to spreading.
  // ---------------------------------------------------------------------
  let preferStatus = 'none';
  let prefer = null;
  if (preferDate) {
    preferStatus = 'invalid';
    const d = DateTime.fromISO(String(preferDate), { zone });
    if (d.isValid) {
      const dayKey = d.toFormat('yyyy-LL-dd');
      const dayStartUtc = d.startOf('day').toUTC();
      const dayEndUtc = d.endOf('day').toUTC();
      const inWindow = dayEndUtc >= now && dayStartUtc <= windowEnd;
      const notPast = dayEndUtc > now;
      const afterNotice = dayEndUtc > earliest;
      const workingDay = allowedDays.has(d.weekday);
      // Each failure gets its own status. They all fall back to spreading, but
      // the reply should be able to say WHICH thing was true -- "we are closed
      // on Sundays" and "that is too soon" are different sentences to a lead,
      // and picking the wrong one is an invented fact.
      if (!workingDay) preferStatus = 'closed_day';
      else if (!notPast || !afterNotice) preferStatus = 'too_soon';
      else if (!inWindow) preferStatus = 'out_of_window';
      if (inWindow && notPast && afterNotice && workingDay) {
        prefer = dayKey;
        // Valid, but the day may yield nothing -- and there are two different
        // reasons for that. "Full" means the calendar is genuinely blocked;
        // "too soon" means every slot on that day sits inside min_hours_notice.
        // Reporting one as the other is asserting a cause we did not check.
        if (perDay.some(x => x.date === dayKey)) {
          preferStatus = 'used';
        } else {
          const rec = perDayAll.find(x => x.date === dayKey);
          preferStatus = (rec && rec.eligible > 0) ? 'full' : 'too_soon';
        }
      }
    }
  }

  const out = [];
  if (prefer && preferStatus === 'used') {
    // Listen to what was asked for: take up to 2 from the requested day, then
    // spread the remainder, so an alternative is still offered.
    const day = perDay.find(x => x.date === prefer);
    for (const s of day.free.slice(0, Math.min(2, max))) out.push(s);
  }
  for (const d of perDay) {
    if (out.length >= max) break;
    if (prefer && d.date === prefer) continue;          // already taken from
    out.push(d.free[0]);
  }
  // If only one day has availability at all, fill from it rather than
  // under-offering.
  if (out.length < max && perDay.length === 1) {
    for (const s of perDay[0].free) {
      if (out.length >= max) break;
      if (!out.some(o => o.startUtc === s.startUtc)) out.push(s);
    }
  }
  return { slots: out, preferDate: prefer,
           preferRequested: preferDate || null, preferStatus };
}

// ============================================================================
// Checkpoint C2 — does this message confirm one of the slots we offered?
//
// The WORKFLOW decides, for the same reason it chose the slots in C1: an event
// is about to be created, and "which one did they mean" must be answerable from
// stored data rather than from a model's paraphrase. The model still phrases
// the outcome -- it is just told the outcome rather than asked for it.
//
// Deciding this before the Claude call, rather than after, is what keeps the
// booking turn to ONE model call: by the time Claude writes, the event either
// exists or it does not, so it never confirms a booking that failed.
//
// The bias is deliberate and one-directional: when in doubt, do NOT book. An
// ambiguous message costs the lead one clarifying question. A wrong match puts
// a real appointment in a real agent's calendar at a time nobody agreed to.
//
// 2026-09-13, THE PHRASE WE TEACH THEM. "What should I bring to the first
// meeting?" booked the first slot on offer: "first" is an ordinal, the offer
// was open, and one ordinal was enough. "Uma primeira reuniao com o nosso
// colega" is the phrase every reply uses for the appointment, so leads say it
// back. A deterministic matcher that reads lead text has to be checked against
// the words our own replies put in their mouths. Two rules follow:
//   - a QUESTION is not an acceptance. "Is Tuesday still available?" with one
//     Tuesday on offer would have booked it. A message that ends in "?" or
//     opens with an interrogative confirms nothing unless it also carries an
//     affirmative ("pode ser terca as 9?" still books).
//   - an ORDINAL counts only when it points at a slot -- "the first one", "a
//     primeira opcao", "o primeiro horario" -- never when it names the
//     appointment: "first meeting", "primeira reuniao", "primera cita".
// ============================================================================
const AFFIRMATIVE = /\b(sim|yes|si|ok|okay|claro|perfeito|perfect|combinado|pode ser|works|great|otimo|vale|de acuerdo)\b/;

// "segunda" is deliberately absent from the ordinals. In Portuguese it is both
// "the second one" and "Monday", and a booking is not the place to guess.
const ORDINALS = [
  { rx: /\b(primeir[oa]|first|primer[oa]|1o|1a|1º|1ª)\b/, idx: 0 },
  { rx: /\b(terceir[oa]|third|tercer[oa]|3o|3a)\b/, idx: 2 },
  { rx: /\b(ultim[oa]|last)\b/, idx: -1 },
];
// An ordinal followed by the appointment itself is the appointment's name, not
// a choice between slots. The system's own vocabulary, in all three languages.
const ORDINAL_NAMES_APPOINTMENT = /\b(primeir[oa]|first|primer[oa]|ultim[oa]|last|terceir[oa]|third|tercer[oa])\s+(reuniao|reunion|meeting|conversa|encontro|visita|visit|viewing|cita|contacto|contact|call|chamada|sessao|session|appointment|marcacao)\b/;
// A question is not an acceptance.
const QUESTION_OPENERS = /^\s*(is|are|do|does|can|could|would|will|what|when|which|how|e|ha|tem|tens|teem|pode|podem|podia|podiam|sera|esta|estao|hay|tiene|tienen|puede|pueden|que|cuando|quando|se)\b/;

function matchConfirmation(text, storedSlots, tz, nowISO) {
  const out = (status, slot, by) => ({ status, slot: slot || null, matchedBy: by || null });
  const slots = Array.isArray(storedSlots) ? storedSlots : [];
  if (!slots.length) return out('no_offer');
  if (!text) return out('none');

  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // A question confirms nothing unless it also says yes.
  const isQuestion = /\?\s*$/.test(t) || QUESTION_OPENERS.test(t);
  if (isQuestion && !AFFIRMATIVE.test(t)) return out('none', null, 'question_not_acceptance');

  // Describe each offered slot in the client's zone, so every comparison below
  // is against what the lead was actually shown.
  const desc = slots.map((s, i) => {
    const d = DateTime.fromISO(s.startUtc).setZone(s.zone || tz);
    return { i, slot: s, weekday: d.weekday, date: d.toFormat('yyyy-LL-dd'),
             day: d.day, month: d.month, hour: d.hour, minute: d.minute };
  });

  const signals = [];
  let pool = desc;
  const narrow = (fn, name) => {
    const next = pool.filter(fn);
    if (next.length) { pool = next; signals.push(name); }
    return next.length;
  };

  // --- an explicit clock time: "9h", "09:00", "as 10", "10h30" ---------------
  const hours = new Set();
  let m;
  const explicitRx = /\b(\d{1,2})[:h](\d{2})\b|\b(\d{1,2})\s*h\b|\bas\s+(\d{1,2})\b|\bat\s+(\d{1,2})\b/g;
  while ((m = explicitRx.exec(t)) !== null) {
    const h = Number(m[1] || m[3] || m[4] || m[5]);
    if (h >= 0 && h <= 23) hours.add(h);
  }
  if (hours.size) {
    // Same rule as an unoffered weekday, and it matters more here: with a
    // single slot on offer, "as 14:00 pode ser?" would otherwise fall through
    // to the affirmative branch and book the 09:00 nobody asked for.
    if (!desc.some(x => hours.has(x.hour))) return out('none', null, 'time_not_offered');
    narrow(x => hours.has(x.hour), 'time');
  }

  // --- a weekday name -------------------------------------------------------
  const wanted = new Set();
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) wanted.add(Number(wd));
  }
  if (wanted.size) {
    // A weekday we never offered is a NEW request, not a confirmation. C1's
    // preferDate path owns that; booking must keep its hands off it.
    if (!desc.some(x => wanted.has(x.weekday))) return out('none', null, 'weekday_not_offered');
    narrow(x => wanted.has(x.weekday), 'weekday');
  }

  // --- "dia 10", or an explicit 10/09 --------------------------------------
  const dm = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})\b/);
  if (dm) {
    const day = Number(dm[1]), mon = Number(dm[2]);
    if (!desc.some(x => x.day === day && x.month === mon)) return out('none', null, 'date_not_offered');
    narrow(x => x.day === day && x.month === mon, 'date');
  } else {
    const dia = t.match(/\bdia\s+(\d{1,2})\b/);
    if (dia) {
      const day = Number(dia[1]);
      if (!desc.some(x => x.day === day)) return out('none', null, 'date_not_offered');
      narrow(x => x.day === day, 'day_of_month');
    }
  }

  // --- "a primeira", "the last one" ----------------------------------------
  if (pool.length > 1 && !ORDINAL_NAMES_APPOINTMENT.test(t)) {
    for (const o of ORDINALS) {
      if (o.rx.test(t)) {
        const target = o.idx === -1 ? desc[desc.length - 1] : desc[o.idx];
        if (target && pool.includes(target)) { pool = [target]; signals.push('ordinal'); }
        break;
      }
    }
  }

  if (signals.length && pool.length === 1) {
    return out('matched', pool[0].slot, signals.join('+'));
  }
  if (signals.length && pool.length > 1) {
    return out('ambiguous', null, signals.join('+'));
  }

  // --- a bare "sim" only works when there is nothing to be ambiguous about ---
  if (AFFIRMATIVE.test(t)) {
    if (desc.length === 1) return out('matched', desc[0].slot, 'affirmative_single_offer');
    return out('ambiguous', null, 'affirmative_multiple_offers');
  }
  return out('none');
}
// ---------------------------------------------------------------------------
// Choose the slots. The WORKFLOW picks them, never the model: Checkpoint C2
// matches the lead's confirmation against exactly what was stored here, so the
// offer has to be knowable. The model only phrases it.
// ---------------------------------------------------------------------------
const a   = $('AfterLead').first().json;
const cfg = a.config || {};
const res = $input.first().json;
const nowISO = new Date().toISOString();
const tz = cfg.timezone || 'Europe/Lisbon';

// Explicit guard on the calendar id itself, not just on the response. A missing
// or malformed id must be reported, never silently treated as "no availability"
// -- which is the same failure the free/busy errors array hides.
const calId = cfg.calendar_id;
let slotError = null;
if (!calId || typeof calId !== 'string' || calId.indexOf('@') === -1) {
  slotError = 'calendar_not_configured';
}

let fbBusy = [];
let slots = [], preferDate = null, preferRequested = null;
let preferStatus = 'none', busyCount = 0;
let offerSource = 'fresh';
if (!slotError) {
  const fb = readFreeBusy(res, calId);
  if (!fb.ok) {
    slotError = fb.error;
  } else {
    busyCount = fb.busy.length;
    fbBusy = fb.busy;
    const newPrefer = extractPreferredDate(a.body, tz, nowISO);
    preferDate = newPrefer;
    const out = computeSlots({
      nowISO, tz,
      workingHours: cfg.working_hours || { start: '09:00', end: '19:00', days: [1,2,3,4,5,6] },
      bookingWindowDays: cfg.booking_window_days || 14,
      minHoursNotice: cfg.min_hours_notice == null ? 24 : cfg.min_hours_notice,
      durationMinutes: cfg.viewing_duration_minutes || 60,
      busy: fb.busy,
      maxSlots: 3,
      preferDate,
      slotStepMinutes: 60,
    });
    // -------------------------------------------------------------------
    // An offer already on the table stays on the table.
    //
    // Without this, any unrelated message ("tem estacionamento?") recomputed a
    // fresh spread and OVERWROTE the stored proposals -- so a lead who had been
    // offered Thursday 09:00 and 10:00 could reply "the Thursday one" against a
    // stored set that no longer contained Thursday. Checkpoint C2 matches
    // confirmations against what is stored, so a moving offer is unmatchable.
    //
    // The stored offer is re-validated every turn: anything now in the past,
    // inside the notice period, or newly busy is dropped. A genuinely NEW date
    // request supersedes it.
    const prior = (a.priorQualification || {}).proposed_slots;

    // A requested day only SUPERSEDES a standing offer if it is actually
    // usable. Testing `newPrefer` alone threw away a live Thursday offer the
    // moment the lead asked "e no domingo?" -- we cannot do Sundays, so the
    // lead lost the times they were considering and the model apologised for
    // "the earlier confusion". preferDate influences ordering and inclusion
    // only; it must not change which offer is on the table either.
    const preferUsable = out.preferStatus === 'used';
    const supersede = preferUsable && (!prior || prior.prefer_date !== newPrefer);

    let reused = null;
    if (prior && !supersede) {
      const ageMs = Date.now() - new Date(prior.at).getTime();
      if (ageMs < 24 * 3600 * 1000) {                 // §5: proposals go stale at 24h
        const earliest = DateTime.fromISO(nowISO, { zone: 'utc' })
          .plus({ hours: cfg.min_hours_notice == null ? 24 : cfg.min_hours_notice });
        const stillGood = (prior.slots || []).filter(s => {
          const st = DateTime.fromISO(s.startUtc), en = DateTime.fromISO(s.endUtc);
          if (st < earliest) return false;
          return !fb.busy.some(b => st < DateTime.fromISO(b.end) && en > DateTime.fromISO(b.start));
        });
        if (stillGood.length) {
          reused = stillGood.map(s => ({
            startUtc: s.startUtc, endUtc: s.endUtc, startLocal: s.local, zone: s.zone,
            dateLocal: DateTime.fromISO(s.startUtc).setZone(s.zone).toFormat('yyyy-LL-dd'),
            timeLocal: DateTime.fromISO(s.startUtc).setZone(s.zone).toFormat('HH:mm'),
          }));
        }
      }
    }

    if (reused) {
      slots = reused;
      offerSource = 'reused';
      // The offer holds, but a day the lead just asked for and cannot have
      // still has to be acknowledged -- silently re-offering the same times
      // reads as not listening.
      if (newPrefer && !preferUsable) {
        preferDate = null;
        preferRequested = out.preferRequested;
        preferStatus = out.preferStatus;
      } else {
        preferDate = prior.prefer_date || null;
        preferRequested = prior.prefer_requested || prior.prefer_date || null;
        preferStatus = prior.prefer_status || 'none';
      }
    } else {
      slots = out.slots;
      preferStatus = out.preferStatus;
      preferDate = out.preferDate;
      preferRequested = out.preferRequested;
      offerSource = supersede ? 'fresh_new_date' : 'fresh';
    }
  }
}

// Human-readable lines for the prompt. The workflow writes these; the model
// restates them in the lead's language without altering the numbers.
const MONTHS = ['January','February','March','April','May','June','July',
                'August','September','October','November','December'];
const DAYS = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const lines = slots.map(s => {
  const d = DateTime.fromISO(s.startUtc).setZone(s.zone);
  return `${DAYS[d.weekday-1]} ${d.day} ${MONTHS[d.month-1]} ${d.year} at ${s.timeLocal} ${s.zone.split('/')[1].replace('_',' ')} time`;
});

return [{ json: { ...a,
  slots, slotLines: lines, slotError, preferDate, preferRequested,
  preferStatus, offerSource,
  busyIntervals: busyCount,
  busy: (!slotError && typeof fbBusy !== 'undefined') ? fbBusy : [],
  freeBusyStatus: res && res.statusCode,
} }];

// ============================================================================
// Slot engine — shared source. Embedded verbatim into the ProposeSlots Code
// node, and unit-tested standalone against non-Lisbon timezones.
//
// §4: the test environment has calendar, config and cron all agreeing on
// Europe/Lisbon. That agreement HIDES timezone bugs rather than revealing them,
// so nothing here may hardcode a zone and every case below is exercised against
// Europe/Madrid (+1 vs Lisbon) as well.
//
// Everything is computed and stored in UTC. The client timezone is used at
// exactly three edges: filtering to working hours, formatting for the lead, and
// setting the calendar event's zone.
// ============================================================================
// ---------------------------------------------------------------------------
// Google free/busy returns HTTP 200 for a calendar it cannot read, with an
// `errors` array and an EMPTY `busy` list. An unreachable or misconfigured
// calendar is therefore indistinguishable from a totally free one unless the
// errors array is read. Unguarded, that offers every slot in the window as
// available. Verified against the live API on 2026-09-03.
function readFreeBusy(httpResponse, calendarId) {
  const res = httpResponse || {};
  const code = res.statusCode;
  if (!(code >= 200 && code < 300)) {
    return { ok: false, busy: [], error: 'freebusy_http_' + code };
  }
  const cals = (res.body && res.body.calendars) || null;
  if (!cals) return { ok: false, busy: [], error: 'freebusy_malformed' };
  const entry = cals[calendarId];
  if (!entry) return { ok: false, busy: [], error: 'freebusy_calendar_absent' };
  if (Array.isArray(entry.errors) && entry.errors.length) {
    const reason = entry.errors.map(e => e.reason || 'unknown').join(',');
    return { ok: false, busy: [], error: 'freebusy_calendar_error:' + reason };
  }
  return { ok: true, busy: Array.isArray(entry.busy) ? entry.busy : [], error: null };
}

// ---------------------------------------------------------------------------
// A lightweight, workflow-side date HINT.
//
// The slots must be in Claude's prompt before it replies, and Checkpoint C2
// needs the workflow to know exactly which slots were offered -- so the model
// cannot be the one choosing them. That rules out taking the preferred day from
// the model's output on the same turn.
//
// This produces a CANDIDATE date only. Every guard in computeSlots still
// applies, and anything unrecognised or invalid falls back silently to
// spreading. The worst failure is an uneven spread, never a wrong or
// unavailable time.
const WEEKDAYS = {
  1: ['segunda', 'monday', 'lunes'],
  2: ['terca', 'tuesday', 'martes'],
  3: ['quarta', 'wednesday', 'miercoles'],
  4: ['quinta', 'thursday', 'jueves'],
  5: ['sexta', 'friday', 'viernes'],
  6: ['sabado', 'saturday'],
  7: ['domingo', 'sunday'],
};
function extractPreferredDate(text, tz, nowISO) {
  if (!text) return null;
  // Strip diacritics first. A JS \\b after "ã" never matches, because an accented
  // character is not a word character -- so "amanhã?" failed while "tomorrow"
  // worked. Normalising also removes the need to enumerate accented variants.
  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const now = DateTime.fromISO(nowISO, { zone: 'utc' }).setZone(tz);

  if (/\b(hoje|today|hoy)\b/.test(t)) return now.toFormat('yyyy-LL-dd');
  if (/\b(amanha|tomorrow|manana)\b/.test(t)) {
    return now.plus({ days: 1 }).toFormat('yyyy-LL-dd');
  }
  // "dia 12", "no dia 12 de setembro". Without this, "sabado dia 12" matched
  // only the weekday and resolved to the NEXT Saturday -- so a request for the
  // 12th was answered with slots for the 5th, and the model then invented times
  // for the day it had been asked about. Checked before the weekday branch for
  // exactly that reason.
  const dia = t.match(/\bdia\s+(\d{1,2})\b/);
  if (dia) {
    const day = Number(dia[1]);
    for (let i = 0; i < 400; i++) {
      const d = now.plus({ days: i });
      if (d.day === day) return d.toFormat('yyyy-LL-dd');
    }
    return null;
  }

  // Explicit dd/mm or dd-mm, year optional.
  const m = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})(?:[\/\-.](\d{2,4}))?\b/);
  if (m) {
    const day = Number(m[1]), mon = Number(m[2]);
    let year = m[3] ? Number(m[3]) : now.year;
    if (year < 100) year += 2000;
    const d = DateTime.fromObject({ year, month: mon, day }, { zone: tz });
    if (d.isValid) {
      // A bare dd/mm already past this year means next year.
      return (!m[3] && d < now.startOf('day') ? d.plus({ years: 1 }) : d).toFormat('yyyy-LL-dd');
    }
    return null;
  }
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) {
      const target = Number(wd);
      // "next <weekday>" means the coming one; today does not count, because a
      // same-day request will fail min_hours_notice anyway.
      let d = now.plus({ days: 1 }).startOf('day');
      for (let i = 0; i < 7; i++) {
        if (d.weekday === target) return d.toFormat('yyyy-LL-dd');
        d = d.plus({ days: 1 });
      }
    }
  }
  return null;
}

function computeSlots(opts) {
  const {
    nowISO,                    // UTC instant, ISO
    tz,                        // IANA zone from client config -- never a literal
    workingHours,              // {start:'09:00', end:'19:00', days:[1..6]}
    bookingWindowDays,
    minHoursNotice,
    durationMinutes,
    busy,                      // [{start,end}] ISO UTC, from free/busy
    maxSlots,
    preferDate,                // optional 'YYYY-MM-DD' in tz; soft preference
    slotStepMinutes,
  } = opts;

  const step = slotStepMinutes || 60;
  const max = maxSlots || 3;
  const now = DateTime.fromISO(nowISO, { zone: 'utc' });
  if (!now.isValid) throw new Error('bad nowISO');

  const zone = tz;
  const earliest = now.plus({ hours: minHoursNotice });     // never "in 20 minutes"
  const windowEnd = now.plus({ days: bookingWindowDays });

  const busyIv = (busy || []).map(b => ({
    s: DateTime.fromISO(b.start, { zone: 'utc' }),
    e: DateTime.fromISO(b.end, { zone: 'utc' }),
  })).filter(x => x.s.isValid && x.e.isValid);

  const overlaps = (s, e) => busyIv.some(b => s < b.e && e > b.s);

  const [sh, sm] = String(workingHours.start).split(':').map(Number);
  const [eh, em] = String(workingHours.end).split(':').map(Number);
  const allowedDays = new Set(workingHours.days || [1, 2, 3, 4, 5, 6]);

  // Walk calendar days in the CLIENT's zone, not UTC -- a day boundary in
  // Lisbon is not a day boundary in Madrid.
  const perDay = [];
  const perDayAll = [];
  let cursor = now.setZone(zone).startOf('day');
  const lastDay = windowEnd.setZone(zone).endOf('day');

  while (cursor <= lastDay) {
    if (allowedDays.has(cursor.weekday)) {          // Luxon: 1=Mon .. 7=Sun
      const dayStart = cursor.set({ hour: sh, minute: sm, second: 0, millisecond: 0 });
      const dayEnd = cursor.set({ hour: eh, minute: em, second: 0, millisecond: 0 });
      const free = [];
      let eligible = 0;
      // Re-derive from the day, so a DST transition inside the day is applied
      // by Luxon rather than by adding fixed offsets.
      for (let t = dayStart; t.plus({ minutes: durationMinutes }) <= dayEnd; t = t.plus({ minutes: step })) {
        const sUtc = t.toUTC();
        const eUtc = t.plus({ minutes: durationMinutes }).toUTC();
        if (sUtc < earliest) continue;              // past, or inside notice period
        if (eUtc > windowEnd) continue;             // beyond the booking window
        eligible++;                                 // would be offerable if free
        if (overlaps(sUtc, eUtc)) continue;         // busy
        free.push({
          startUtc: sUtc.toISO(),
          endUtc: eUtc.toISO(),
          startLocal: t.toISO(),
          dateLocal: t.toFormat('yyyy-LL-dd'),
          timeLocal: t.toFormat('HH:mm'),
          zone,
        });
      }
      // `eligible` counts slots that clear the past/notice/window tests but
      // ignores busy. It is the only way to tell "that day is booked up" from
      // "that day is too soon" -- and saying the wrong one is asserting a cause
      // the system does not actually know.
      if (eligible || free.length) {
        perDayAll.push({ date: cursor.toFormat('yyyy-LL-dd'), free, eligible });
      }
      if (free.length) perDay.push({ date: cursor.toFormat('yyyy-LL-dd'), free });
    }
    cursor = cursor.plus({ days: 1 });
  }

  // ---------------------------------------------------------------------
  // preferDate comes from the MODEL (it extracts "quinta-feira" from the
  // lead's message), so it is validated before it is allowed to influence
  // anything. It affects ORDERING and INCLUSION only -- never eligibility.
  // A slot that is not genuinely free can never be surfaced by preferring it.
  // Any failed check falls back silently to spreading.
  // ---------------------------------------------------------------------
  let preferStatus = 'none';
  let prefer = null;
  if (preferDate) {
    preferStatus = 'invalid';
    const d = DateTime.fromISO(String(preferDate), { zone });
    if (d.isValid) {
      const dayKey = d.toFormat('yyyy-LL-dd');
      const dayStartUtc = d.startOf('day').toUTC();
      const dayEndUtc = d.endOf('day').toUTC();
      const inWindow = dayEndUtc >= now && dayStartUtc <= windowEnd;
      const notPast = dayEndUtc > now;
      const afterNotice = dayEndUtc > earliest;
      const workingDay = allowedDays.has(d.weekday);
      // Each failure gets its own status. They all fall back to spreading, but
      // the reply should be able to say WHICH thing was true -- "we are closed
      // on Sundays" and "that is too soon" are different sentences to a lead,
      // and picking the wrong one is an invented fact.
      if (!workingDay) preferStatus = 'closed_day';
      else if (!notPast || !afterNotice) preferStatus = 'too_soon';
      else if (!inWindow) preferStatus = 'out_of_window';
      if (inWindow && notPast && afterNotice && workingDay) {
        prefer = dayKey;
        // Valid, but the day may yield nothing -- and there are two different
        // reasons for that. "Full" means the calendar is genuinely blocked;
        // "too soon" means every slot on that day sits inside min_hours_notice.
        // Reporting one as the other is asserting a cause we did not check.
        if (perDay.some(x => x.date === dayKey)) {
          preferStatus = 'used';
        } else {
          const rec = perDayAll.find(x => x.date === dayKey);
          preferStatus = (rec && rec.eligible > 0) ? 'full' : 'too_soon';
        }
      }
    }
  }

  const out = [];
  if (prefer && preferStatus === 'used') {
    // Listen to what was asked for: take up to 2 from the requested day, then
    // spread the remainder, so an alternative is still offered.
    const day = perDay.find(x => x.date === prefer);
    for (const s of day.free.slice(0, Math.min(2, max))) out.push(s);
  }
  for (const d of perDay) {
    if (out.length >= max) break;
    if (prefer && d.date === prefer) continue;          // already taken from
    out.push(d.free[0]);
  }
  // If only one day has availability at all, fill from it rather than
  // under-offering.
  if (out.length < max && perDay.length === 1) {
    for (const s of perDay[0].free) {
      if (out.length >= max) break;
      if (!out.some(o => o.startUtc === s.startUtc)) out.push(s);
    }
  }
  return { slots: out, preferDate: prefer,
           preferRequested: preferDate || null, preferStatus };
}

// ============================================================================
// Checkpoint C2 — does this message confirm one of the slots we offered?
//
// The WORKFLOW decides, for the same reason it chose the slots in C1: an event
// is about to be created, and "which one did they mean" must be answerable from
// stored data rather than from a model's paraphrase. The model still phrases
// the outcome -- it is just told the outcome rather than asked for it.
//
// Deciding this before the Claude call, rather than after, is what keeps the
// booking turn to ONE model call: by the time Claude writes, the event either
// exists or it does not, so it never confirms a booking that failed.
//
// The bias is deliberate and one-directional: when in doubt, do NOT book. An
// ambiguous message costs the lead one clarifying question. A wrong match puts
// a real appointment in a real agent's calendar at a time nobody agreed to.
//
// 2026-09-13, THE PHRASE WE TEACH THEM. "What should I bring to the first
// meeting?" booked the first slot on offer: "first" is an ordinal, the offer
// was open, and one ordinal was enough. "Uma primeira reuniao com o nosso
// colega" is the phrase every reply uses for the appointment, so leads say it
// back. A deterministic matcher that reads lead text has to be checked against
// the words our own replies put in their mouths. Two rules follow:
//   - a QUESTION is not an acceptance. "Is Tuesday still available?" with one
//     Tuesday on offer would have booked it. A message that ends in "?" or
//     opens with an interrogative confirms nothing unless it also carries an
//     affirmative ("pode ser terca as 9?" still books).
//   - an ORDINAL counts only when it points at a slot -- "the first one", "a
//     primeira opcao", "o primeiro horario" -- never when it names the
//     appointment: "first meeting", "primeira reuniao", "primera cita".
// ============================================================================
const AFFIRMATIVE = /\b(sim|yes|si|ok|okay|claro|perfeito|perfect|combinado|pode ser|works|great|otimo|vale|de acuerdo)\b/;

// "segunda" is deliberately absent from the ordinals. In Portuguese it is both
// "the second one" and "Monday", and a booking is not the place to guess.
const ORDINALS = [
  { rx: /\b(primeir[oa]|first|primer[oa]|1o|1a|1º|1ª)\b/, idx: 0 },
  { rx: /\b(terceir[oa]|third|tercer[oa]|3o|3a)\b/, idx: 2 },
  { rx: /\b(ultim[oa]|last)\b/, idx: -1 },
];
// An ordinal followed by the appointment itself is the appointment's name, not
// a choice between slots. The system's own vocabulary, in all three languages.
const ORDINAL_NAMES_APPOINTMENT = /\b(primeir[oa]|first|primer[oa]|ultim[oa]|last|terceir[oa]|third|tercer[oa])\s+(reuniao|reunion|meeting|conversa|encontro|visita|visit|viewing|cita|contacto|contact|call|chamada|sessao|session|appointment|marcacao)\b/;
// A question is not an acceptance.
const QUESTION_OPENERS = /^\s*(is|are|do|does|can|could|would|will|what|when|which|how|e|ha|tem|tens|teem|pode|podem|podia|podiam|sera|esta|estao|hay|tiene|tienen|puede|pueden|que|cuando|quando|se)\b/;

function matchConfirmation(text, storedSlots, tz, nowISO) {
  const out = (status, slot, by) => ({ status, slot: slot || null, matchedBy: by || null });
  const slots = Array.isArray(storedSlots) ? storedSlots : [];
  if (!slots.length) return out('no_offer');
  if (!text) return out('none');

  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // A question confirms nothing unless it also says yes.
  const isQuestion = /\?\s*$/.test(t) || QUESTION_OPENERS.test(t);
  if (isQuestion && !AFFIRMATIVE.test(t)) return out('none', null, 'question_not_acceptance');

  // Describe each offered slot in the client's zone, so every comparison below
  // is against what the lead was actually shown.
  const desc = slots.map((s, i) => {
    const d = DateTime.fromISO(s.startUtc).setZone(s.zone || tz);
    return { i, slot: s, weekday: d.weekday, date: d.toFormat('yyyy-LL-dd'),
             day: d.day, month: d.month, hour: d.hour, minute: d.minute };
  });

  const signals = [];
  let pool = desc;
  const narrow = (fn, name) => {
    const next = pool.filter(fn);
    if (next.length) { pool = next; signals.push(name); }
    return next.length;
  };

  // --- an explicit clock time: "9h", "09:00", "as 10", "10h30" ---------------
  const hours = new Set();
  let m;
  const explicitRx = /\b(\d{1,2})[:h](\d{2})\b|\b(\d{1,2})\s*h\b|\bas\s+(\d{1,2})\b|\bat\s+(\d{1,2})\b/g;
  while ((m = explicitRx.exec(t)) !== null) {
    const h = Number(m[1] || m[3] || m[4] || m[5]);
    if (h >= 0 && h <= 23) hours.add(h);
  }
  if (hours.size) {
    // Same rule as an unoffered weekday, and it matters more here: with a
    // single slot on offer, "as 14:00 pode ser?" would otherwise fall through
    // to the affirmative branch and book the 09:00 nobody asked for.
    if (!desc.some(x => hours.has(x.hour))) return out('none', null, 'time_not_offered');
    narrow(x => hours.has(x.hour), 'time');
  }

  // --- a weekday name -------------------------------------------------------
  const wanted = new Set();
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) wanted.add(Number(wd));
  }
  if (wanted.size) {
    // A weekday we never offered is a NEW request, not a confirmation. C1's
    // preferDate path owns that; booking must keep its hands off it.
    if (!desc.some(x => wanted.has(x.weekday))) return out('none', null, 'weekday_not_offered');
    narrow(x => wanted.has(x.weekday), 'weekday');
  }

  // --- "dia 10", or an explicit 10/09 --------------------------------------
  const dm = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})\b/);
  if (dm) {
    const day = Number(dm[1]), mon = Number(dm[2]);
    if (!desc.some(x => x.day === day && x.month === mon)) return out('none', null, 'date_not_offered');
    narrow(x => x.day === day && x.month === mon, 'date');
  } else {
    const dia = t.match(/\bdia\s+(\d{1,2})\b/);
    if (dia) {
      const day = Number(dia[1]);
      if (!desc.some(x => x.day === day)) return out('none', null, 'date_not_offered');
      narrow(x => x.day === day, 'day_of_month');
    }
  }

  // --- "a primeira", "the last one" ----------------------------------------
  if (pool.length > 1 && !ORDINAL_NAMES_APPOINTMENT.test(t)) {
    for (const o of ORDINALS) {
      if (o.rx.test(t)) {
        const target = o.idx === -1 ? desc[desc.length - 1] : desc[o.idx];
        if (target && pool.includes(target)) { pool = [target]; signals.push('ordinal'); }
        break;
      }
    }
  }

  if (signals.length && pool.length === 1) {
    return out('matched', pool[0].slot, signals.join('+'));
  }
  if (signals.length && pool.length > 1) {
    return out('ambiguous', null, signals.join('+'));
  }

  // --- a bare "sim" only works when there is nothing to be ambiguous about ---
  if (AFFIRMATIVE.test(t)) {
    if (desc.length === 1) return out('matched', desc[0].slot, 'affirmative_single_offer');
    return out('ambiguous', null, 'affirmative_multiple_offers');
  }
  return out('none');
}
// ---------------------------------------------------------------------------
// Is this message confirming one of the times we offered?
//
// Decided HERE, before the Claude call, so the booking turn stays at one model
// call: by the time Claude writes, the outcome is known, so it never confirms
// a booking that did not happen.
// ---------------------------------------------------------------------------
const p    = $input.first().json;
const cfg  = p.config || {};
const tz   = cfg.timezone || 'Europe/Lisbon';
const prior = p.priorQualification || {};
const booked = prior.booking || null;
const ps2  = prior.proposed_slots || null;

// §5: proposals go stale at 24h. A lead replying three days later is accepting
// something that may be long gone, so it is re-proposed rather than booked.
let stored = [], offerStale = false;
if (ps2 && Array.isArray(ps2.slots) && ps2.at) {
  offerStale = (Date.now() - new Date(ps2.at).getTime()) >= 24 * 3600 * 1000;
  if (!offerStale) stored = ps2.slots;
}

const m = matchConfirmation(p.body, stored, tz, new Date().toISOString());

// The busy list from THIS run's free/busy. A slot that was taken since it was
// offered must not be confirmable, and this is the first of two checks -- the
// second runs immediately before the event is created.
const busy = p.busy || [];
const isBusy = (s) => busy.some(b =>
  DateTime.fromISO(s.startUtc) < DateTime.fromISO(b.end) &&
  DateTime.fromISO(s.endUtc)   > DateTime.fromISO(b.start));

let bookingIntent = 'none', bookingSlot = null;
if (booked && booked.event_id) {
  // Idempotency (§9.7) and the reschedule rule (§9.8) share this branch: once a
  // viewing exists, nothing here creates a second one. A lead asking to move it
  // is escalated by the model, which is told the booking exists.
  bookingIntent = 'already_booked';
} else if (m.status === 'matched') {
  bookingIntent = isBusy(m.slot) ? 'taken' : 'confirm';
  bookingSlot = m.slot;
} else if (m.status === 'ambiguous') {
  bookingIntent = 'ambiguous';
} else if (offerStale && ps2) {
  bookingIntent = 'offer_stale';
}

// A Google event id must be base32hex: [a-v0-9]. A UUID with the dashes removed
// and the timestamp digits are already inside that alphabet, so the id is
// derived rather than hashed -- deterministic, collision-free, and a replayed
// confirmation therefore collides on Google's side instead of double-booking.
// ---------------------------------------------------------------------------
// The event id is derived from the SLOT, never from the lead.
//
// Two leads confirming the same time therefore generate the SAME id, and
// Google rejects the second create with 409. That conflict IS the lock:
// atomic, server-side, in the system that owns the calendar.
//
// The previous id included the lead id, so two leads produced two different
// ids and both creates succeeded -- a real double booking, twice observed.
// A re-check before creating narrows the window; it cannot close it, because
// there is no window small enough that two concurrent actors cannot both
// observe "free".
//
// Google ids are base32hex: [a-v0-9] only, 5-1024 chars.
// ---------------------------------------------------------------------------
const calKey = String(cfg.calendar_id || '').toLowerCase()
  .replace(/[^a-v0-9]/g, '').slice(0, 16);
const eventId = bookingSlot
  ? ('rv' + calKey + String(bookingSlot.startUtc).replace(/[^0-9]/g, ''))
  : null;

return [{ json: { ...p,
  bookingIntent, bookingSlot, bookingEventId: eventId,
  bookingMatchedBy: m.matchedBy, bookingMatchStatus: m.status,
  offerStale, existingBooking: booked,
} }];

// ============================================================================
// Slot engine — shared source. Embedded verbatim into the ProposeSlots Code
// node, and unit-tested standalone against non-Lisbon timezones.
//
// §4: the test environment has calendar, config and cron all agreeing on
// Europe/Lisbon. That agreement HIDES timezone bugs rather than revealing them,
// so nothing here may hardcode a zone and every case below is exercised against
// Europe/Madrid (+1 vs Lisbon) as well.
//
// Everything is computed and stored in UTC. The client timezone is used at
// exactly three edges: filtering to working hours, formatting for the lead, and
// setting the calendar event's zone.
// ============================================================================
// ---------------------------------------------------------------------------
// Google free/busy returns HTTP 200 for a calendar it cannot read, with an
// `errors` array and an EMPTY `busy` list. An unreachable or misconfigured
// calendar is therefore indistinguishable from a totally free one unless the
// errors array is read. Unguarded, that offers every slot in the window as
// available. Verified against the live API on 2026-09-03.
function readFreeBusy(httpResponse, calendarId) {
  const res = httpResponse || {};
  const code = res.statusCode;
  if (!(code >= 200 && code < 300)) {
    return { ok: false, busy: [], error: 'freebusy_http_' + code };
  }
  const cals = (res.body && res.body.calendars) || null;
  if (!cals) return { ok: false, busy: [], error: 'freebusy_malformed' };
  const entry = cals[calendarId];
  if (!entry) return { ok: false, busy: [], error: 'freebusy_calendar_absent' };
  if (Array.isArray(entry.errors) && entry.errors.length) {
    const reason = entry.errors.map(e => e.reason || 'unknown').join(',');
    return { ok: false, busy: [], error: 'freebusy_calendar_error:' + reason };
  }
  return { ok: true, busy: Array.isArray(entry.busy) ? entry.busy : [], error: null };
}

// ---------------------------------------------------------------------------
// A lightweight, workflow-side date HINT.
//
// The slots must be in Claude's prompt before it replies, and Checkpoint C2
// needs the workflow to know exactly which slots were offered -- so the model
// cannot be the one choosing them. That rules out taking the preferred day from
// the model's output on the same turn.
//
// This produces a CANDIDATE date only. Every guard in computeSlots still
// applies, and anything unrecognised or invalid falls back silently to
// spreading. The worst failure is an uneven spread, never a wrong or
// unavailable time.
const WEEKDAYS = {
  1: ['segunda', 'monday', 'lunes'],
  2: ['terca', 'tuesday', 'martes'],
  3: ['quarta', 'wednesday', 'miercoles'],
  4: ['quinta', 'thursday', 'jueves'],
  5: ['sexta', 'friday', 'viernes'],
  6: ['sabado', 'saturday'],
  7: ['domingo', 'sunday'],
};
function extractPreferredDate(text, tz, nowISO) {
  if (!text) return null;
  // Strip diacritics first. A JS \\b after "ã" never matches, because an accented
  // character is not a word character -- so "amanhã?" failed while "tomorrow"
  // worked. Normalising also removes the need to enumerate accented variants.
  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const now = DateTime.fromISO(nowISO, { zone: 'utc' }).setZone(tz);

  if (/\b(hoje|today|hoy)\b/.test(t)) return now.toFormat('yyyy-LL-dd');
  if (/\b(amanha|tomorrow|manana)\b/.test(t)) {
    return now.plus({ days: 1 }).toFormat('yyyy-LL-dd');
  }
  // Explicit dd/mm or dd-mm, year optional.
  const m = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})(?:[\/\-.](\d{2,4}))?\b/);
  if (m) {
    const day = Number(m[1]), mon = Number(m[2]);
    let year = m[3] ? Number(m[3]) : now.year;
    if (year < 100) year += 2000;
    const d = DateTime.fromObject({ year, month: mon, day }, { zone: tz });
    if (d.isValid) {
      // A bare dd/mm already past this year means next year.
      return (!m[3] && d < now.startOf('day') ? d.plus({ years: 1 }) : d).toFormat('yyyy-LL-dd');
    }
    return null;
  }
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) {
      const target = Number(wd);
      // "next <weekday>" means the coming one; today does not count, because a
      // same-day request will fail min_hours_notice anyway.
      let d = now.plus({ days: 1 }).startOf('day');
      for (let i = 0; i < 7; i++) {
        if (d.weekday === target) return d.toFormat('yyyy-LL-dd');
        d = d.plus({ days: 1 });
      }
    }
  }
  return null;
}

function computeSlots(opts) {
  const {
    nowISO,                    // UTC instant, ISO
    tz,                        // IANA zone from client config -- never a literal
    workingHours,              // {start:'09:00', end:'19:00', days:[1..6]}
    bookingWindowDays,
    minHoursNotice,
    durationMinutes,
    busy,                      // [{start,end}] ISO UTC, from free/busy
    maxSlots,
    preferDate,                // optional 'YYYY-MM-DD' in tz; soft preference
    slotStepMinutes,
  } = opts;

  const step = slotStepMinutes || 60;
  const max = maxSlots || 3;
  const now = DateTime.fromISO(nowISO, { zone: 'utc' });
  if (!now.isValid) throw new Error('bad nowISO');

  const zone = tz;
  const earliest = now.plus({ hours: minHoursNotice });     // never "in 20 minutes"
  const windowEnd = now.plus({ days: bookingWindowDays });

  const busyIv = (busy || []).map(b => ({
    s: DateTime.fromISO(b.start, { zone: 'utc' }),
    e: DateTime.fromISO(b.end, { zone: 'utc' }),
  })).filter(x => x.s.isValid && x.e.isValid);

  const overlaps = (s, e) => busyIv.some(b => s < b.e && e > b.s);

  const [sh, sm] = String(workingHours.start).split(':').map(Number);
  const [eh, em] = String(workingHours.end).split(':').map(Number);
  const allowedDays = new Set(workingHours.days || [1, 2, 3, 4, 5, 6]);

  // Walk calendar days in the CLIENT's zone, not UTC -- a day boundary in
  // Lisbon is not a day boundary in Madrid.
  const perDay = [];
  const perDayAll = [];
  let cursor = now.setZone(zone).startOf('day');
  const lastDay = windowEnd.setZone(zone).endOf('day');

  while (cursor <= lastDay) {
    if (allowedDays.has(cursor.weekday)) {          // Luxon: 1=Mon .. 7=Sun
      const dayStart = cursor.set({ hour: sh, minute: sm, second: 0, millisecond: 0 });
      const dayEnd = cursor.set({ hour: eh, minute: em, second: 0, millisecond: 0 });
      const free = [];
      let eligible = 0;
      // Re-derive from the day, so a DST transition inside the day is applied
      // by Luxon rather than by adding fixed offsets.
      for (let t = dayStart; t.plus({ minutes: durationMinutes }) <= dayEnd; t = t.plus({ minutes: step })) {
        const sUtc = t.toUTC();
        const eUtc = t.plus({ minutes: durationMinutes }).toUTC();
        if (sUtc < earliest) continue;              // past, or inside notice period
        if (eUtc > windowEnd) continue;             // beyond the booking window
        eligible++;                                 // would be offerable if free
        if (overlaps(sUtc, eUtc)) continue;         // busy
        free.push({
          startUtc: sUtc.toISO(),
          endUtc: eUtc.toISO(),
          startLocal: t.toISO(),
          dateLocal: t.toFormat('yyyy-LL-dd'),
          timeLocal: t.toFormat('HH:mm'),
          zone,
        });
      }
      // `eligible` counts slots that clear the past/notice/window tests but
      // ignores busy. It is the only way to tell "that day is booked up" from
      // "that day is too soon" -- and saying the wrong one is asserting a cause
      // the system does not actually know.
      if (eligible || free.length) {
        perDayAll.push({ date: cursor.toFormat('yyyy-LL-dd'), free, eligible });
      }
      if (free.length) perDay.push({ date: cursor.toFormat('yyyy-LL-dd'), free });
    }
    cursor = cursor.plus({ days: 1 });
  }

  // ---------------------------------------------------------------------
  // preferDate comes from the MODEL (it extracts "quinta-feira" from the
  // lead's message), so it is validated before it is allowed to influence
  // anything. It affects ORDERING and INCLUSION only -- never eligibility.
  // A slot that is not genuinely free can never be surfaced by preferring it.
  // Any failed check falls back silently to spreading.
  // ---------------------------------------------------------------------
  let preferStatus = 'none';
  let prefer = null;
  if (preferDate) {
    preferStatus = 'invalid';
    const d = DateTime.fromISO(String(preferDate), { zone });
    if (d.isValid) {
      const dayKey = d.toFormat('yyyy-LL-dd');
      const dayStartUtc = d.startOf('day').toUTC();
      const dayEndUtc = d.endOf('day').toUTC();
      const inWindow = dayEndUtc >= now && dayStartUtc <= windowEnd;
      const notPast = dayEndUtc > now;
      const afterNotice = dayEndUtc > earliest;
      const workingDay = allowedDays.has(d.weekday);
      // Each failure gets its own status. They all fall back to spreading, but
      // the reply should be able to say WHICH thing was true -- "we are closed
      // on Sundays" and "that is too soon" are different sentences to a lead,
      // and picking the wrong one is an invented fact.
      if (!workingDay) preferStatus = 'closed_day';
      else if (!notPast || !afterNotice) preferStatus = 'too_soon';
      else if (!inWindow) preferStatus = 'out_of_window';
      if (inWindow && notPast && afterNotice && workingDay) {
        prefer = dayKey;
        // Valid, but the day may yield nothing -- and there are two different
        // reasons for that. "Full" means the calendar is genuinely blocked;
        // "too soon" means every slot on that day sits inside min_hours_notice.
        // Reporting one as the other is asserting a cause we did not check.
        if (perDay.some(x => x.date === dayKey)) {
          preferStatus = 'used';
        } else {
          const rec = perDayAll.find(x => x.date === dayKey);
          preferStatus = (rec && rec.eligible > 0) ? 'full' : 'too_soon';
        }
      }
    }
  }

  const out = [];
  if (prefer && preferStatus === 'used') {
    // Listen to what was asked for: take up to 2 from the requested day, then
    // spread the remainder, so an alternative is still offered.
    const day = perDay.find(x => x.date === prefer);
    for (const s of day.free.slice(0, Math.min(2, max))) out.push(s);
  }
  for (const d of perDay) {
    if (out.length >= max) break;
    if (prefer && d.date === prefer) continue;          // already taken from
    out.push(d.free[0]);
  }
  // If only one day has availability at all, fill from it rather than
  // under-offering.
  if (out.length < max && perDay.length === 1) {
    for (const s of perDay[0].free) {
      if (out.length >= max) break;
      if (!out.some(o => o.startUtc === s.startUtc)) out.push(s);
    }
  }
  return { slots: out, preferDate: prefer,
           preferRequested: preferDate || null, preferStatus };
}

// ============================================================================
// Checkpoint C2 — does this message confirm one of the slots we offered?
//
// The WORKFLOW decides, for the same reason it chose the slots in C1: an event
// is about to be created, and "which one did they mean" must be answerable from
// stored data rather than from a model's paraphrase. The model still phrases
// the outcome -- it is just told the outcome rather than asked for it.
//
// Deciding this before the Claude call, rather than after, is what keeps the
// booking turn to ONE model call: by the time Claude writes, the event either
// exists or it does not, so it never confirms a booking that failed.
//
// The bias is deliberate and one-directional: when in doubt, do NOT book. An
// ambiguous message costs the lead one clarifying question. A wrong match puts
// a real appointment in a real agent's calendar at a time nobody agreed to.
// ============================================================================
const AFFIRMATIVE = /\b(sim|yes|si|ok|okay|claro|perfeito|perfect|combinado|pode ser|works|great|otimo|vale|de acuerdo)\b/;

// "segunda" is deliberately absent from the ordinals. In Portuguese it is both
// "the second one" and "Monday", and a booking is not the place to guess.
const ORDINALS = [
  { rx: /\b(primeir[oa]|first|primer[oa]|1o|1a|1º|1ª)\b/, idx: 0 },
  { rx: /\b(terceir[oa]|third|tercer[oa]|3o|3a)\b/, idx: 2 },
  { rx: /\b(ultim[oa]|last)\b/, idx: -1 },
];

function matchConfirmation(text, storedSlots, tz, nowISO) {
  const out = (status, slot, by) => ({ status, slot: slot || null, matchedBy: by || null });
  const slots = Array.isArray(storedSlots) ? storedSlots : [];
  if (!slots.length) return out('no_offer');
  if (!text) return out('none');

  const t = String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // Describe each offered slot in the client's zone, so every comparison below
  // is against what the lead was actually shown.
  const desc = slots.map((s, i) => {
    const d = DateTime.fromISO(s.startUtc).setZone(s.zone || tz);
    return { i, slot: s, weekday: d.weekday, date: d.toFormat('yyyy-LL-dd'),
             day: d.day, month: d.month, hour: d.hour, minute: d.minute };
  });

  const signals = [];
  let pool = desc;
  const narrow = (fn, name) => {
    const next = pool.filter(fn);
    if (next.length) { pool = next; signals.push(name); }
    return next.length;
  };

  // --- an explicit clock time: "9h", "09:00", "as 10", "10h30" ---------------
  const hours = new Set();
  let m;
  const explicitRx = /\b(\d{1,2})[:h](\d{2})\b|\b(\d{1,2})\s*h\b|\bas\s+(\d{1,2})\b|\bat\s+(\d{1,2})\b/g;
  while ((m = explicitRx.exec(t)) !== null) {
    const h = Number(m[1] || m[3] || m[4] || m[5]);
    if (h >= 0 && h <= 23) hours.add(h);
  }
  if (hours.size) {
    // Same rule as an unoffered weekday, and it matters more here: with a
    // single slot on offer, "as 14:00 pode ser?" would otherwise fall through
    // to the affirmative branch and book the 09:00 nobody asked for.
    if (!desc.some(x => hours.has(x.hour))) return out('none', null, 'time_not_offered');
    narrow(x => hours.has(x.hour), 'time');
  }

  // --- a weekday name -------------------------------------------------------
  const wanted = new Set();
  for (const [wd, names] of Object.entries(WEEKDAYS)) {
    if (names.some(n => t.includes(n))) wanted.add(Number(wd));
  }
  if (wanted.size) {
    // A weekday we never offered is a NEW request, not a confirmation. C1's
    // preferDate path owns that; booking must keep its hands off it.
    if (!desc.some(x => wanted.has(x.weekday))) return out('none', null, 'weekday_not_offered');
    narrow(x => wanted.has(x.weekday), 'weekday');
  }

  // --- "dia 10", or an explicit 10/09 --------------------------------------
  const dm = t.match(/\b(\d{1,2})[\/\-.](\d{1,2})\b/);
  if (dm) {
    const day = Number(dm[1]), mon = Number(dm[2]);
    if (!desc.some(x => x.day === day && x.month === mon)) return out('none', null, 'date_not_offered');
    narrow(x => x.day === day && x.month === mon, 'date');
  } else {
    const dia = t.match(/\bdia\s+(\d{1,2})\b/);
    if (dia) {
      const day = Number(dia[1]);
      if (!desc.some(x => x.day === day)) return out('none', null, 'date_not_offered');
      narrow(x => x.day === day, 'day_of_month');
    }
  }

  // --- "a primeira", "the last one" ----------------------------------------
  if (pool.length > 1) {
    for (const o of ORDINALS) {
      if (o.rx.test(t)) {
        const target = o.idx === -1 ? desc[desc.length - 1] : desc[o.idx];
        if (target && pool.includes(target)) { pool = [target]; signals.push('ordinal'); }
        break;
      }
    }
  }

  if (signals.length && pool.length === 1) {
    return out('matched', pool[0].slot, signals.join('+'));
  }
  if (signals.length && pool.length > 1) {
    return out('ambiguous', null, signals.join('+'));
  }

  // --- a bare "sim" only works when there is nothing to be ambiguous about ---
  if (AFFIRMATIVE.test(t)) {
    if (desc.length === 1) return out('matched', desc[0].slot, 'affirmative_single_offer');
    return out('ambiguous', null, 'affirmative_multiple_offers');
  }
  return out('none');
}


// The second of the two checks. The first ran before the Claude call so the
// reply would be right; this one runs with nothing between it and the create.
const d   = $('DecideEscalation').first().json;
const cfg = $('AfterLead').first().json.config || {};
const fb  = readFreeBusy($input.first().json, cfg.calendar_id);
const slot = d.bookingSlot;

// A failed re-check is NOT permission to book. readFreeBusy exists because a
// calendar we cannot read answers 200 with an empty busy list, which is
// indistinguishable from "free" -- and here that would mean booking over
// somebody.
let stillFree = false, recheckError = fb.error;
if (fb.ok) {
  stillFree = !fb.busy.some(b =>
    DateTime.fromISO(slot.startUtc) < DateTime.fromISO(b.end) &&
    DateTime.fromISO(slot.endUtc)   > DateTime.fromISO(b.start));
  if (!stillFree) recheckError = 'slot_taken_since_offer';
}
return [{ json: { ...d, stillFree, recheckError } }];

// ============================================================================
// The never-invent-a-time guard. Shared source.
//
// Embedded verbatim into ParseClaude and ParseGuardRetry, replacing the
// timesNotSupplied() each node carried inline. Unit-tested standalone in
// tests/time_guard.test.js, which loads THIS file.
//
// THE RULE (unchanged since 2026-09-12): a time in the reply must be one the
// workflow supplied. If none was supplied, no time may appear at all. A
// rejection routes into the guard retry, and escalates if the retry fails too.
//
// THE ONE EXEMPTION (2026-09-21): a time the LEAD named in their own message
// may appear in a clause that DECLINES it. Live check 2 of the language
// deploy: the lead asked "11:00?", 09:00 and 10:00 were offered, and both of
// the model's replies said, correctly, "11:00 isn't available, but I do have
// … 09:00 … or 10:00". The guard rejected both, because it could not tell
// NAMING a time from DECLINING one, and the lead was escalated for asking an
// ordinary question.
//
// WHAT THE EXEMPTION MUST NOT OPEN, in order of danger:
//   * accepting the lead's unoffered time: "11:00 it is", "11:00 works";
//   * declining it in one clause and affirming it in the next: "11:00 isn't
//     possible on Wednesday, but Thursday at 11:00 works". So the decision is
//     taken PER OCCURRENCE, in the clause around it, not per sentence;
//   * declining a time the lead never asked for, which is still the model
//     talking about a time nobody supplied;
//   * an invented alternative in a declining sentence: "11:00 isn't
//     available, but 14:00 is".
// Clauses split on contrast words and dashes, NOT on plain commas:
// "11:00, unfortunately, is taken" is one clause, and must stay one.
//
// NEGATION THAT GOVERNS THE TIME (2026-09-21, the first deploy gate). The
// model declined "11:00?" with "09:00 or 10:00 are available, but not 11:00",
// the guard rejected that and the retry, and the lead was escalated. This was
// the third decline shape the wording list missed ("quedamos entonces", then
// the plurals, now "but not X"). So instead of another phrase, a second test
// is added, taken PER OCCURRENCE: does a negation stand directly in front of
// THIS time, with nothing between them except a preposition or a day?
//   en  not (at) 11:00 · except (for) 11:00 ·
//       don't have an 11:00 · can't do 11:00 · no 11:00 slot
//   pt  não às 11:00 · menos às 11:00 · exceto / salvo às 11:00 ·
//       não consigo marcar às 11:00
//   es  no a las 11:00 · excepto / salvo / menos a las 11:00 ·
//       no puedo ofrecer las 11:00
// The rule is unchanged: the time must be one the LEAD named. And the
// negation must govern it:
//   * "why not 11:00", "if not 11:00", "porque não às 11:00", "¿por qué no a
//     las 11:00?" are proposals, never declines;
//   * "pelo menos às 11:00", "al menos a las 11:00" mean "at least", and
//     "mais ou menos", "más o menos" mean "around";
//   * "apart from", "other than", "besides", "tirando" are left out: "apart
//     from 11:00 we also have 09:00" ADDS the time rather than declining it;
//   * an EXCEPT that carves the time out of something UNAVAILABLE, or out of
//     a negation, or that sits beside "also", affirms it: "everything except
//     11:00 is taken", "nothing is free except 11:00". That is a rejection even when the
//     clause also reads as a decline. The clause-level rule alone accepted it
//     before 2026-09-21.
// ============================================================================

const TG_TIME_RX = /\b([01]?\d|2[0-3])[:h]([0-5]\d)\b/g;

function tgNorm(h, m) { return String(Number(h)) + ':' + m; }

function tgTimesIn(s) {
  return tgTimesAt(s).map(x => x.t);
}

// Every time in s, with where it starts: [{ t: '11:00', i: 17 }].
function tgTimesAt(s) {
  const out = [];
  const rx = new RegExp(TG_TIME_RX.source, 'g');
  let m;
  while ((m = rx.exec(String(s == null ? '' : s))) !== null) out.push({ t: tgNorm(m[1], m[2]), i: m.index });
  return out;
}

// What may stand between a negation and the time it governs: a day ("on
// Thursday", "na quinta dia 24", "el jueves 24 de septiembre") and a
// preposition ("at", "às", "a las"). Nothing else. Deaccented text.
const TG_DAY = '(?:(?:mon|tues|wednes|thurs|fri|satur|sun)day|(?:segunda|terca|quarta|quinta|sexta)(?:-feira)?|sabado|domingo|lunes|martes|miercoles|jueves|viernes)';
const TG_BRIDGE = '(?:(?:(?:on|this|next|na|no|nesta|neste|el|este)\\s+)?' + TG_DAY +
  '(?:\\s+(?:dia\\s+)?\\d{1,2}(?:\\s+(?:de\\s+)?[a-z]+)?)?\\s+)?' +
  '(?:(?:at|for|the|as|a|pelas|para as|a las|las|a la|para las)\\s+)?$';
// The negation words themselves, one per language, with the forms that do NOT
// negate what follows. Shared: the time guard's rule below and tgNegatedBefore()
// (which src/booking_claim.js calls) read these three and no other list.
// en. Not "why not", "if not", "or not", "whether not".
const TG_NEG_EN = "(?<!\\b(?:why|if|or|whether)\\s)\\bnot";
// pt. Not "porque não", "por que não", "se não", "ou não".
const TG_NEG_PT = "(?<!\\b(?:porque|por que|se|ou)\\s)\\bnao";
// es. Not "por qué no", "porque no", "si no", "o no".
const TG_NEG_ES = "(?<!\\b(?:por que|porque|si|o)\\s)\\bno";
// en contractions ("isn't", "won't"). NOT part of the time guard's own rule (its
// decline list carries those forms itself); shared for src/appointment_kind.js's
// viewing guard (22 Sep 2026), so "this isn't a viewing" is read as a denial.
const TG_NEG_EN_NT = "\\b(?:is|are|was|were|does|do|did|would|will|wo|could|ca)n'?t";
// A negation that governs the time after it.
const TG_NOT_BEFORE_RX = new RegExp('(?:' + [
  TG_NEG_EN,
  "\\b(?:(?:don'?t|do not|doesn'?t|does not)\\s+have|have no|haven'?t got)(?:\\s+(?:an?|the|any))?",
  "\\b(?:can'?t|cannot|can not)\\s+(?:do|offer|make|book)",
  TG_NEG_PT,
  "\\bnao\\s+(?:consigo|conseguimos|posso|podemos)\\s+(?:fazer|oferecer|marcar|agendar)",
  "\\bnao\\s+(?:tenho|temos|ha)(?:\\s+(?:vaga|disponibilidade))?",
  // es. A bare "no" governs only through a preposition: "pero no a las 11:00".
  TG_NEG_ES + "(?=\\s+(?:(?:a las|las|para las|a la)\\s+$|(?:el\\s+)?" + TG_DAY + "))",
  "\\bno\\s+(?:puedo|podemos)\\s+(?:hacer|ofrecer|agendar|reservar)",
  "\\bno\\s+(?:tengo|tenemos|hay)(?:\\s+(?:hueco|disponibilidad))?",
].join('|') + ')\\s+' + TG_BRIDGE);
// Does a negation govern whatever starts right after `before`? Deaccented,
// lower-cased text. The negation must END the text, optionally followed by one
// adverb: "ainda nao temos uma reuniao marcada" is negated at "temos"; "nao, temos
// a reuniao marcada" is not (the comma ends the negation's reach), and neither is
// "nao se preocupe, temos a reuniao marcada". Added 22 Sep 2026 for the claim
// guard (src/booking_claim.js): "Ainda não temos uma reunião marcada, João. Posso
// propor..." was read as a claim, both drafts rejected, the lead handed over
// (the booking gate, run 8).
const TG_NEGATED_BEFORE_RX = new RegExp('(?:' + [TG_NEG_EN, TG_NEG_PT, TG_NEG_ES].join('|') +
  ')\\s+(?:(?:ainda|ja|aun|todavia|yet|still|really|actually)\\s+)?$');
function tgNegatedBefore(before) {
  return TG_NEGATED_BEFORE_RX.test(String(before == null ? '' : before));
}

// "except" and its kin. They decline the time only when the rest of the clause
// is not about something UNAVAILABLE: "any time except 11:00" declines it,
// "everything except 11:00 is taken" offers it.
const TG_EXCEPT_BEFORE_RX = new RegExp('(?:' + [
  '\\bexcept(?:\\s+for)?',
  '\\b(?:exceto|excepto|salvo)', '(?<!\\b(?:pelo|ao|a|de|al|lo|o|ou)\\s)\\bmenos',
].join('|') + ')\\s+' + TG_BRIDGE);
const TG_UNAVAILABLE_RX = /\b(?:(?:taken|booked|full|unavailable|gone|not (?:available|free|open)|isn'?t (?:available|free|open)|aren'?t (?:available|free|open)|no longer)\b|ocupad|reservad|preenchid|lotad|complet|indisponiv|(?:nao|no) (?:esta|estao|estan|ha|hay) (?:disponiv|disponib|livre|libre))/;
// Before an except: a negation or "only" turns the except into an offer.
const TG_EXCEPT_INVERTS_RX = /\b(?:not|no|nothing|none|cannot|only|nao|nada|nenhum\w*|sem|apenas|so|sin|ningun\w*|solo|solamente)\b|n't\b/;
// Anywhere in the clause: an except beside "also" adds the time.
const TG_ADDITIVE_RX = /\b(?:also|too|as well|tambem|alem|tambien|ademas)\b/;
// After the time: "there's no 11:00 slot", "no 11:00 opening".
const TG_NO_BEFORE_RX = /\bno\s+$/;
const TG_SLOT_AFTER_RX = /^\s*(?:slot|opening|appointment|availability)\b/;

// governs(clause, i) -> 'declined' | 'carved' | null, for the time at clause[i].
function tgGoverned(clause, i) {
  const before = clause.slice(0, i);
  const after = clause.slice(i).replace(/^\S+/, '');
  const ex = before.match(TG_EXCEPT_BEFORE_RX);
  if (ex) {
    const lead = before.slice(0, ex.index);
    return (TG_UNAVAILABLE_RX.test(clause) || TG_EXCEPT_INVERTS_RX.test(lead) || TG_ADDITIVE_RX.test(clause)) ? 'carved' : 'declined';
  }
  if (TG_NOT_BEFORE_RX.test(before)) return 'declined';
  if (TG_NO_BEFORE_RX.test(before) && TG_SLOT_AFTER_RX.test(after)) return 'declined';
  return null;
}

// A clause that declines. Deaccented, lower-cased text. Each language's forms,
// singular and plural. The list is measured against real replies in
// tests/time_guard.test.js; a shape it misses is a false escalation (annoying),
// never a false acceptance, because the exemption only ever ALLOWS a declined
// time the lead asked for.
const TG_DECLINE_RX = new RegExp([
  // en. A negation counts only when it governs an availability word: "no
  // problem, 17:00 then" must never read as a decline.
  "\\b(?:isn'?t|is not|aren'?t|are not|not|no longer|won'?t be|can'?t (?:do|offer|make)|cannot (?:do|offer|make))\\b[^.;]{0,30}?\\b(?:available|free|possible|an option|open|doable)\\b",
  "\\bnot available\\b", "\\bunavailable\\b",
  "\\b(?:already (?:taken|booked)|fully booked|booked up|is taken|are taken)\\b",
  "\\bno (?:availability|slot|slots|opening|openings)\\b",
  "\\b(?:don'?t|do not) have (?:availability|anything|a slot|slots|that time|an opening)\\b",
  "\\b(?:can'?t|cannot) offer\\b",
  // 22 Sep 2026: the slot another lead has just taken. TAKEN and GONE only, never
  // "booked": a decline lets the lead's own time through, and "your meeting was
  // just booked for 11:00" must never be read as one.
  "\\b(?:was|were|has been|have been|got) (?:just )?taken\\b(?! care)", "\\bjust (?:been |got )?(?:taken|gone)\\b(?! care)",
  "\\b(?:has|have) (?:just )?gone\\b",
  "\\b(?:taken|booked|reserved) by (?:someone else|somebody else|another (?:client|person|customer|lead))\\b",
  // pt. Same rule: "nao ha problema" is not a decline.
  "\\bnao (?:esta|estao|temos|tenho|ha|existe|existem|e|sera|fica|ficam)\\b[^.;]{0,25}?\\b(?:disponiv|disponibilidade|livre|possiv|vaga|aberto|opcao)",
  "\\bindisponive(?:l|is)\\b",
  "\\bja (?:esta|estao) (?:ocupad|preenchid|reservad)", "\\b(?:esta|estao) (?:ocupad|preenchid)",
  "\\bsem disponibilidade\\b", "\\bnao (?:consigo|conseguimos|posso|podemos) (?:oferecer|marcar|agendar|disponibilizar)",
  // 22 Sep 2026: "ficou ocupado", "acabou de ser ocupado". Never "marcado": see en.
  // "Reservado" only with WHO took it: "acabou de ser reservado por outra pessoa"
  // (the booking gate, run 5). Kept narrow: someone ELSE, never the lead's own booking.
  "\\b(?:reservad|marcad|ocupad)[oa]s? por (?:outra pessoa|outro cliente|outra cliente|outras pessoas|alguem)\\b",
  "\\b(?:ficou|ficaram|foi|foram) (?:entretanto |agora |ja )?(?:ocupad|preenchid)", "\\bacab(?:ou|aram) de (?:ser |ficar )?(?:ocupad|preenchid)",
  // es. "no hay problema" is not a decline.
  "\\bno (?:esta|estan|tenemos|tengo|hay|es|sera|queda|quedan)\\b[^.;]{0,25}?\\b(?:disponib|libre|posible|hueco|opcion)",
  "\\bya (?:esta|estan) (?:ocupad|reservad|complet)", "\\b(?:esta|estan) (?:ocupad|complet)",
  "\\bsin disponibilidad\\b", "\\bno (?:puedo|podemos) (?:ofrecer|agendar|reservar)",
  // 22 Sep 2026, the booking gate's run 9: "Ese horario de las 16:00 se acaba de
  // ocupar"; run 6: "acaba de ocuparse". Never "reservado" alone: see en.
  "\\b(?:reservad|ocupad|cogid)[oa]s? por (?:otra persona|otro cliente|otra clienta|otras personas|alguien)\\b",
  "\\bse (?:acaba|acaban) de ocupar\\b", "\\bacaba(?:n)? de ocupar(?:se)?\\b", "\\bacaba(?:n)? de (?:ser |quedar )?ocupad", "\\bse (?:ocupo|ocuparon)\\b", "\\b(?:quedo|quedaron) (?:ya )?ocupad",
].join('|'));

// Contrast words and dashes end a clause. Deaccented text.
const TG_CLAUSE_SPLIT_RX = /\s*;\s*|\s+[-–—]\s+|\s*—\s*|,?\s+\b(?:but|however|though|although|whereas|instead|mas|porem|contudo|no entanto|pero|sin embargo|en cambio)\b/;

// Typographic apostrophes are folded to ' before any pattern runs (21 Sep 2026,
// the gate that passed 61f50cc: "11:00 isn’t available", U+2019, was rejected
// because every pattern here is written with a straight quote).
function tgDeaccent(s) {
  return String(s == null ? '' : s).replace(/[\u2018\u2019\u201B\u02BC\u2032\uFF07\u00B4\u0060]/g, "'")
    .normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// Which time each clause-level decline is ABOUT: the occurrence nearest to it.
// Before 2026-09-21 (the first deploy gate) a decline anywhere in the clause
// exempted every lead-named time in it, so "10:00 isn't available, so 11:00 it
// is" let 11:00 through. And the bare sentiment words ("unfortunately",
// "infelizmente", "lamentablemente"...) no longer decline on their own:
// "Sadly I had to move things, 11:00 is yours" was accepted.
// -> Set of the start indexes of declined occurrences.
function tgDeclinedOccurrences(clause, times) {
  const out = new Set();
  if (!times.length) return out;
  const rx = new RegExp(TG_DECLINE_RX.source, 'g');
  let m;
  while ((m = rx.exec(clause)) !== null) {
    const a = m.index, b = m.index + m[0].length;
    let best = null, bestD = Infinity;
    for (const x of times) {
      const e = x.i + x.t.length;
      const d = e <= a ? a - e : (x.i >= b ? x.i - b : 0);
      if (d < bestD) { bestD = d; best = x; }
    }
    if (best) out.add(best.i);
    if (m[0].length === 0) rx.lastIndex++;
  }
  return out;
}

// timesNotSupplied(reply, slots, leadText) -> the times the reply named that
// nothing supplied, e.g. ['14:00']. Empty means the reply passes.
//   slots     [{timeLocal: 'HH:MM'}, ...]: offered, booked or stored times
//   leadText  the lead's current message (optional: without it there is no
//             exemption, which is the pre-2026-09-21 behaviour)
function timesNotSupplied(reply, slots, leadText) {
  const supplied = new Set();
  for (const s of (slots || [])) {
    const m = String((s && s.timeLocal) || '').match(/^(\d{1,2}):(\d{2})$/);
    if (m) supplied.add(tgNorm(m[1], m[2]));
  }
  const leadTimes = new Set(tgTimesIn(leadText));
  const bad = new Set();
  const sentences = String(reply == null ? '' : reply).split(/(?<=[.!?\n])\s+|\n+/);
  for (const sentence of sentences) {
    for (const clause of tgDeaccent(sentence).split(TG_CLAUSE_SPLIT_RX)) {
      if (!clause) continue;
      const times = tgTimesAt(clause);
      const declinedAt = tgDeclinedOccurrences(clause, times);
      for (const { t, i } of times) {
        if (supplied.has(t)) continue;
        if (!leadTimes.has(t)) { bad.add(t); continue; }
        const governed = tgGoverned(clause, i);
        if (governed === 'declined') continue;
        if (governed === 'carved') { bad.add(t); continue; }
        if (declinedAt.has(i)) continue;
        bad.add(t);
      }
    }
  }
  return [...bad];
}

// >>> EMBED src/lost_slot.js >>>
// ============================================================================
// A lead loses a slot to another lead: the sentence is the SYSTEM's, never the
// model's. Shared source.
//
// Embedded between markers into AfterBooking (after src/time_guard.js, whose
// tgTimesIn() it uses) and LostSlotReoffer. Unit-tested standalone in
// tests/lost_slot.test.js, which loads THIS file rather than a copy.
//
// WHY THIS EXISTS
// On the 24 Sep gate a lead picked 16:00 seconds after another lead had booked
// it. The model was told "the time was taken, apologise plainly" and wrote:
// "Peço desculpa, João, mas esse horário das 16:00 não está correto da minha
// parte". That is false (nobody erred; someone else booked it), it apologises
// for an error we did not make, and the time guard could not read it as a
// decline, so invariant 1 fired. A phrase list would have caught this wording
// and missed the next one (docs/concierge-structural-guards-plan.md: nine
// misses, all of them a guard deciding what prose means).
//
// THE RULE (operator, 24 Sep 2026), and the first piece of the structural
// rebuild built its way (plan §1: the workflow writes every sentence that
// carries a time):
//   - the sentence is a fixed template per language (pt, en, es), rendered by
//     the workflow in the language already resolved for the reply;
//   - it says plainly that the time was just taken by someone else, and never
//     apologises for an error we did not make;
//   - it offers the remaining REAL slots, computed by the slot engine from a
//     calendar read taken at that moment, never from the earlier offer;
//   - if none are left, or this lead lost a slot the time before as well, it
//     hands over to a person (with the card), so there is no loop of re-offers;
//   - the model's prose is the second line only: it may carry {{LOST_SLOT}}
//     where the sentence goes; prose that names any time of its own is
//     dropped, and the template goes alone. The template always wins.
// Both paths use it: the sequential one (the slot was already busy when the
// lead picked it) and the race (two leads confirmed at once).
// ============================================================================

const LS_PLACEHOLDER = '{{LOST_SLOT}}';
const LS_LOOSE_TIME_RX = /\b(?:[01]?\d|2[0-3])\s?(?:h\b(?!\d)|[ap]\.?\s?m\.?(?![a-z]))/i;
// Anything that looks like an attempt at the placeholder but is not exactly it:
// {{LOST SLOT}}, {LOST_SLOT}, {{ LOST_SLOT }}, {{lost_slot}}, [[LOST_SLOT]].
const LS_MANGLED_RX = /[{[]{1,2}\s*lost[\s_-]?slot\s*[}\]]{1,2}/gi;

const LS_TEXT = {
  en: {
    offer: 'That time has just been taken by someone else. We still have {slots} ({city} time). Which one suits you?',
    none_left: 'That time has just been taken by someone else, and there are no other times free at the moment. A colleague will be in touch shortly to find one with you.',
    second_in_a_row: 'That time has also just been taken by someone else. A colleague will be in touch shortly to find a time with you.',
    or: ' or ', at: ' at ', city: { Lisbon: 'Lisbon' },
  },
  pt: {
    offer: 'Esse horário acabou de ser reservado por outra pessoa. Ainda temos {slots} (hora de {city}). Qual prefere?',
    none_left: 'Esse horário acabou de ser reservado por outra pessoa e, de momento, não há outros horários livres. Um colega entra em contacto consigo em breve para encontrar um.',
    second_in_a_row: 'Esse horário também acabou de ser reservado por outra pessoa. Um colega entra em contacto consigo em breve para encontrar um horário.',
    or: ' ou ', at: ', às ', city: { Lisbon: 'Lisboa' },
  },
  es: {
    offer: 'Ese horario acaba de reservarlo otra persona. Aún tenemos {slots} (hora de {city}). ¿Cuál le viene mejor?',
    none_left: 'Ese horario acaba de reservarlo otra persona y ahora mismo no hay otros horarios libres. Un compañero se pondrá en contacto con usted en breve para encontrar uno.',
    second_in_a_row: 'Ese horario también acaba de reservarlo otra persona. Un compañero se pondrá en contacto con usted en breve para encontrar un horario.',
    or: ' o ', at: ' a las ', city: { Lisbon: 'Lisboa' },
  },
};
const LS_DAYS = {
  en: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'],
  pt: ['segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado', 'domingo'],
  es: ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'],
};
const LS_MONTHS = {
  en: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
  pt: ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'],
  es: ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'],
};

function lsLang(lang) { return LS_TEXT[lang] ? lang : 'en'; }
function lsZone(z) { return (typeof z === 'string' && z.indexOf('/') !== -1) ? z : 'Europe/Lisbon'; }

// One slot, from its stored UTC instant, in the client's zone through the
// timezone database (never an offset: Lisbon changes on 25 Oct).
//   en "Thursday 1 October at 09:00"   pt "quinta-feira, 1 de outubro, às 09:00"
//   es "jueves 1 de octubre a las 09:00"
function lsSlot(startUtc, lang, zone) {
  const L = lsLang(lang);
  const dt = DateTime.fromISO(String(startUtc), { zone: 'utc' }).setZone(lsZone(zone));
  if (!dt.isValid) return null;
  const day = LS_DAYS[L][dt.weekday - 1], mon = LS_MONTHS[L][dt.month - 1], hm = dt.toFormat('HH:mm');
  if (L === 'pt') return day + ', ' + dt.day + ' de ' + mon + LS_TEXT.pt.at + hm;
  if (L === 'es') return day + ' ' + dt.day + ' de ' + mon + LS_TEXT.es.at + hm;
  return day + ' ' + dt.day + ' ' + mon + LS_TEXT.en.at + hm;
}

function lsJoin(items, L) {
  if (items.length <= 1) return items.join('');
  return items.slice(0, -1).join(', ') + LS_TEXT[L].or + items[items.length - 1];
}

// decideLostSlot({ remaining, streakBefore }) -> { outcome, detail, offer }
//   remaining     the slots the slot engine found free in a calendar read taken
//                 NOW ([] when that read failed: never fall back to an old offer)
//   streakBefore  how many slots this lead had lost in a row before this one
function decideLostSlot(o) {
  const remaining = Array.isArray(o && o.remaining) ? o.remaining : [];
  const streak = Number(o && o.streakBefore) || 0;
  if (streak >= 1) return { outcome: 'handover', detail: 'second_in_a_row', offer: [] };
  if (!remaining.length) return { outcome: 'handover', detail: 'none_left', offer: [] };
  return { outcome: 'reoffer', detail: 'reoffered', offer: remaining.slice(0, 3) };
}

// renderLostSlot(decision, lang, zone) -> the sentence the lead receives.
function renderLostSlot(decision, lang, zone) {
  const L = lsLang(lang);
  const T = LS_TEXT[L];
  if (decision.outcome !== 'reoffer') return T[decision.detail] || T.none_left;
  const slots = decision.offer.map(s => lsSlot(s.startUtc, L, zone)).filter(Boolean);
  if (!slots.length) return T.none_left;
  const cityEn = lsZone(zone).split('/').pop().replace(/_/g, ' ');
  return T.offer.replace('{slots}', lsJoin(slots, L)).replace('{city}', T.city[cityEn] || cityEn);
}

// assembleLostSlotReply(prose, rendered, timesIn) -> { text, proseUsed, warnings }
// The model's prose around the placeholder is the SECOND line: the rendered
// sentence always goes, and the prose goes with it only when it names no time
// of its own. `timesIn` is src/time_guard.js's tgTimesIn (extraction, which
// converges; never a reading of what the prose means).
function assembleLostSlotReply(prose, rendered, timesIn) {
  const warnings = [];
  let p = String(prose == null ? '' : prose);
  const extract = typeof timesIn === 'function' ? timesIn : () => [];
  const bare = p.split(LS_PLACEHOLDER).join(' ');
  // tgTimesIn reads "16:00" and "16h00"; "4pm", "4 p.m." and a bare "16h" are
  // times too. Still extraction: a time's FORMAT, never what the prose means.
  if (extract(bare).length || LS_LOOSE_TIME_RX.test(bare)) {
    // Its own lost-slot sentence, or a time of any kind: the template wins alone.
    return { text: rendered, proseUsed: false, warnings: ['lost_slot_prose_named_a_time'] };
  }
  const n = p.split(LS_PLACEHOLDER).length - 1;
  if (n > 1) warnings.push('lost_slot_placeholder_repeated');
  // Mangled attempts are removed, and the sentence is then placed as if missing.
  const mangled = (p.replace(/\{\{LOST_SLOT\}\}/g, '').match(LS_MANGLED_RX) || []).length;
  if (mangled) { warnings.push('lost_slot_placeholder_mangled'); p = p.replace(/\{\{LOST_SLOT\}\}/g, '\u0000').replace(LS_MANGLED_RX, '').replace(/\u0000/g, LS_PLACEHOLDER); }
  let text;
  if (n >= 1) {
    const i = p.indexOf(LS_PLACEHOLDER);
    text = p.slice(0, i) + rendered + p.slice(i + LS_PLACEHOLDER.length).split(LS_PLACEHOLDER).join('');
  } else {
    if (!mangled && p.trim()) warnings.push('lost_slot_placeholder_missing');
    // The sentence the lead is waiting for goes first; any prose follows it.
