  //     others. "Ola, procuro casa em Cascais" is short but unambiguous.
  //   - contested: enough evidence AND a clear margin. This is the pt/es case,
  //     where both score and the winner has to actually win.
  // Everything else falls back to the configured default rather than guessing.
  const unopposed = scores[top] >= 2 && scores[second] === 0;
  const contested = scores[top] >= 4 && (scores[top] - scores[second]) >= 4;
  const confident = unopposed || contested;
  return out(confident ? top : null, scores, confident);
}

// resolveLeadLanguage(text, priorInbound) -> {lang, source}
//
// The language to STATE for this reply. 2026-09-21: the current message alone
// decided it, and a short reply the detector cannot read ("ok, Thursday 15h")
// stated nothing, so the model drifted to the prompt's Portuguese. A lead does
// not change language by writing briefly, so an undecided message inherits the
// language of the lead's most recent message that WAS decided.
//   source: 'message'  the current message decided it
//           'history'  inherited from an earlier inbound message
//           null       nothing decided it (a first message the detector
//                      cannot read), and nothing is stated
// `priorInbound` is the lead's earlier messages as text, NEWEST FIRST. Only
// the lead's own words count: the assistant writes in whatever it was told,
// so its messages are not evidence of the lead's language.
function resolveLeadLanguage(text, priorInbound) {
  const now = detectLanguage(text);
  if (now.lang) return { lang: now.lang, source: 'message' };
  for (const t of (Array.isArray(priorInbound) ? priorInbound : [])) {
    const d = detectLanguage(t);
    if (d.lang) return { lang: d.lang, source: 'history' };
  }
  return { lang: null, source: null };
}

// pickMessage(messages, lang, fallbackLang) -> string|null
//
// `messages` is the config map, e.g. {pt: '...', en: '...', es: '...'}. Resolution
// order is: detected language -> the client's configured default -> English ->
// whatever single string was configured. Every step is a fixed string; nothing
// here is generated.
function pickMessage(messages, lang, fallbackLang) {
  if (typeof messages === 'string') return messages;          // legacy single string
  if (!messages || typeof messages !== 'object') return null;
  const order = [lang, fallbackLang, 'en', 'pt'];
  for (const k of order) {
    if (k && typeof messages[k] === 'string' && messages[k].trim()) return messages[k];
  }
  const first = Object.values(messages).find(v => typeof v === 'string' && v.trim());
  return first || null;
}

// Convenience: resolve a named system message for a lead's text in one call.
// `cfg` is client_automations.config.
//
// `priorInbound` (optional, 2026-09-21): the lead's earlier messages, NEWEST
// FIRST. An English lead who asks for a person in words the lists cannot read
// ("Talk to a human") inherits English from history (resolveLeadLanguage)
// rather than getting the client's default. `detected` stays the current
// message's own verdict, and `source` says where `lang` came from:
// 'message' | 'history' | null (the configured default).
function systemMessage(cfg, name, leadText, priorInbound) {
  const c = cfg || {};
  const det = detectLanguage(leadText);
  const res = resolveLeadLanguage(leadText, priorInbound);
  const fallback = c.default_language
    || (Array.isArray(c.languages) && c.languages.length ? c.languages[0] : 'en');
  const bag = (c.system_messages || {})[name];
  const picked = pickMessage(bag, res.lang, fallback);
  return {
    text: picked || c.handoff_note || null,
    lang: res.lang || fallback,
    detected: det.lang,
    source: res.source,
    confident: det.confident,
    scores: det.scores,
  };
}


// Convergence point for every booking path. Which branch ran is READ from an
// explicit marker, never inferred from the shape of the input -- an upstream
// HTTP node's statusCode travels down this chain and made a skipped booking
// look like a created one (engineering-lessons.md §1).
const d = $input.first().json;
const branch = d.bookingBranch;
// The id actually SENT to Google carries a generation suffix chosen by
// ReadSlotEvents; the stored base id is only a fallback for paths that never
// reached the create (see src/event_id.js).
let sentId = d.bookingEventId;
try { sentId = $('ReadSlotEvents').first().json.bookingEventId || sentId; } catch (e) { /* create path not reached */ }

let bookingResult = 'not_attempted', eventId = null, bookingError = null;

if (d.bookingIntent === 'already_booked') {
  bookingResult = 'already_booked';
  eventId = (d.existingBooking || {}).event_id || null;
} else if (branch === 'create_attempted' || branch === 'conflict_resolved') {
  const code = d.httpStatus;
  const body = d.httpBody || {};
  if (code >= 200 && code < 300) {
    bookingResult = 'created';
    eventId = body.id || sentId;
  } else if (code === 409) {
    // Resolved against the calendar, not assumed. A slot-keyed id means a 409
    // is usually ANOTHER lead winning the race -- the case that used to double
    // book -- but it can also be our own orphaned create, or an id burned by a
    // deleted event.
    if (d.conflict === 'ours') {
      bookingResult = 'duplicate_replay';
      eventId = sentId;
    } else if (d.conflict === 'burned_id') {
      bookingResult = 'conflict_burned_id';
      bookingError = 'the identifier for this slot belongs to a deleted event; '
                   + 'the time may be free but cannot be booked automatically';
    } else {
      bookingResult = 'slot_taken';
      bookingError = 'another lead confirmed this slot first (409)';
    }
  } else {
    bookingResult = 'failed';
    bookingError = 'create_http_' + code + ':' +
      ((body.error && body.error.message) ? String(body.error.message).slice(0, 120) : 'unknown');
  }
} else if (branch === 'conflict_resolved') {
  // handled above via code === 409
} else if (branch === 'blocked') {
  bookingResult = d.recheckError === 'slot_taken_since_offer' ? 'slot_taken' : 'recheck_failed';
  bookingError = d.recheckError || null;
}

const booked = (bookingResult === 'created' || bookingResult === 'duplicate_replay');

// The model was told, before it wrote, that the slot was free and being booked.
// If the create then failed, its reply says "Confirmado!" about an appointment
// that does not exist -- the worst output this product can produce, because the
// lead turns up and nobody is there. So the reply is DISCARDED and the lead
// gets a handoff instead. This is an escalation discovered after the model
// call, which is why AfterBooking, not DecideEscalation, is the last word on
// escalation.
const promisedButFailed = d.bookReady && !booked;

// The C3 five-second race lands here: the model has already written a
// confirmation, so its reply is unusable, and "a colleague will follow up"
// does not say what happened. Same rules as the handoff note -- fixed strings,
// deterministic language, no model.
const cfgAB = ($('AfterLead').first().json.config) || {};
const leadText = $('AfterLead').first().json.body;
let abPrior = []; try { abPrior = $('BuildClaudeRequest').first().json.leadPriorInbound || []; } catch (e) { abPrior = []; }
const RACE = (bookingResult === 'slot_taken')
  ? systemMessage(cfgAB, 'slot_taken', leadText, abPrior)
  : systemMessage(cfgAB, 'handoff', leadText, abPrior);
const RACE_NOTE = RACE.text || d.handoffNote;
const RACE_LANG = RACE.lang;
const reasons = (d.escalationReasons || []).slice();
// A lost race (the re-check, or Google's 409 on a slot another lead took) is the
// calendar working, not failing: its own head, which src/system_reasons.js does
// not list, so the run is not an error and the escalation is a person's to act
// on. Everything else that failed a promised booking stays booking_failed.
if (promisedButFailed) reasons.push((bookingResult === 'slot_taken' ? 'booking_lost_race:' + (bookingError || 'slot_taken')
                                    : 'booking_failed:' + (bookingResult + (bookingError ? ':' + bookingError : ''))));

// ---------------------------------------------------------------------------
// A LOST SLOT: the sentence is the system's, never the model's (src/lost_slot.js,
// operator 24 Sep 2026). Sequential (the slot was already busy when the lead
// picked it) or race (another lead confirmed it at the same moment). The
// remaining slots come from LostSlotReoffer's calendar read taken NOW; with no
// read, nothing is offered and the lead is handed over. A second loss in a row
// hands over too: no loop of re-offers.
// ---------------------------------------------------------------------------
const lsPath = (d.bookingIntent === 'taken' && d.bookingSlot && !d.escalating) ? 'sequential'
             : (promisedButFailed && bookingResult === 'slot_taken') ? 'race' : null;
let lostSlot = null;
if (lsPath) {
  const fresh = d.lostSlotFresh || null;
  const priorQ = ($('AfterLead').first().json.priorQualification) || {};
  const streakBefore = Number(priorQ.lost_slot_streak) || 0;
  const decision = decideLostSlot({ remaining: (fresh && fresh.readOk) ? (fresh.remaining || []) : [], streakBefore });
  let lsLangV = d.leadLang || null;
  if (!lsLangV) { try { lsLangV = $('BuildClaudeRequest').first().json.leadLang || null; } catch (e) { lsLangV = null; } }
  lsLangV = lsLangV || cfgAB.default_language || 'en';
  const rendered = renderLostSlot(decision, lsLangV, cfgAB.timezone || 'Europe/Lisbon');
  // Race: the model wrote a confirmation of a booking that failed. Never used.
  const asm = (decision.outcome === 'reoffer' && lsPath === 'sequential')
    ? assembleLostSlotReply(d.replyText, rendered, tgTimesIn)
    : { text: rendered, proseUsed: false, warnings: [] };
  lostSlot = { path: lsPath, outcome: decision.outcome, detail: decision.detail, streak_before: streakBefore,
               fresh_read: fresh ? { ok: !!fresh.readOk, error: fresh.error || null, status: fresh.status || null,
                                     read_at: fresh.readAt || null, busy: fresh.busyCount } : null,
               offer: decision.offer, lang: lsLangV, text: asm.text, prose_used: asm.proseUsed, warnings: asm.warnings,
               lost_slot: d.bookingSlot || null };
  // The generic race reason is replaced: a re-offer is no escalation at all, a
  // hand-over says why.
  for (let i = reasons.length - 1; i >= 0; i--) if (String(reasons[i]).indexOf('booking_lost_race') === 0) reasons.splice(i, 1);
