const lsReoffer = !!(lostSlot && lostSlot.outcome === 'reoffer');
const lsHandover = !!(lostSlot && lostSlot.outcome === 'handover');
const escalatingOut = lostSlot ? (lsHandover || !!d.escalating) : (d.escalating || promisedButFailed);
const replyTextOut = lsReoffer ? lostSlot.text : d.replyText;

