// AI DISCLOSURE -- EU AI Act Article 50 (src/ai_disclosure.js).
//
// THE BANNER NEVER TOUCHES replyText OR handoffBody. It goes into sendBody /
// sendHandoffBody, and only the Send* and Store* nodes read those. AfterBooking
// runs BEFORE AssertInvariants, so prefixing in place would push our own
// constant through timesNamedIn, moneyAmountsIn and nameMismatch and have them
// read it as if the model had written it. What goes on the wire is sendBody;
// everything else is what the model or the config actually said.
//
// Both bodies are prepared because this node cannot know which send will fire
// -- IsEscalating decides that downstream and both read this node. Only one is
// ever sent, and the PrepRun node on the path that fired records which.
const aLd = $('AfterLead').first().json;
const discCfg = aLd.config || {};
let discRows = [], discFailsafe = false;
try {
  const rs = $('ReadDisclosureState').first().json;
  discRows = Array.isArray(rs.body) ? rs.body : [];
  if (!(rs.statusCode >= 200 && rs.statusCode < 300)) discFailsafe = true;
} catch (e) { discFailsafe = true; }
let discHist = [];
try { const h = $('LoadHistory').first().json; discHist = Array.isArray(h.body) ? h.body : []; } catch (e) { discHist = []; }

const discState = disclosureStateFrom(discRows, discHist, discCfg, new Date().toISOString());
discState.failsafe = discFailsafe;
const discDecision = shouldDisclose(discState);

// The banner INHERITS the language the path already resolved -- it never runs
// its own detection. Independent detection is how you get a Portuguese banner
// above an English reply, which is the split-language class §0.4 already fought.
let discReplyLang = lostSlot ? lostSlot.lang : d.leadLang;
if (!discReplyLang) { try { discReplyLang = $('BuildClaudeRequest').first().json.leadLang; } catch (e) { discReplyLang = null; } }
discReplyLang = discReplyLang || discCfg.default_language || 'en';
const discHandoffLang = (lsHandover ? lostSlot.lang : promisedButFailed ? RACE_LANG : d.handoffLang) || discCfg.default_language || 'en';

const discNames = { agent: discCfg.agent_name, agency: discCfg.agency_name, clientName: aLd.clientName };
const discPrefix = (lang) => discDecision.required ? disclosureText(discCfg, lang, discNames) : '';
// An absent body stays absent: handoffBody is null on the non-escalating path,
// and a banner with nothing after it is not a message.
const discApply = (banner, body) => String(body || '').trim()
  ? withDisclosure(banner, body)
  : { text: body, applied: false, overLimit: false, droppedChars: 0 };

const discHandoffText = lsHandover ? lostSlot.text : promisedButFailed ? RACE_NOTE : d.handoffBody;
const outReply = discApply(discPrefix(discReplyLang), replyTextOut);
const outHandoff = discApply(discPrefix(discHandoffLang), discHandoffText);

return [{ json: { ...d, bookingResult, bookingError,
                  bookedEventId: eventId, booked, promisedButFailed,
                  bookingSlot: d.bookingSlot || null,
                  escalating: escalatingOut, lostSlot, replyText: replyTextOut,
                  escalationReasons: reasons,
                  escalationReason: reasons.join(' | ') || null,
                  // What actually goes to Twilio on each of the two paths.
                  sendBody: outReply.text,
                  sendHandoffBody: outHandoff.text,
                  disclosure: {
                    decision: discDecision, state: discState,
                    replyLang: discReplyLang, handoffLang: discHandoffLang,
                    replyApplied: outReply.applied, handoffApplied: outHandoff.applied,
                    replyOverLimit: outReply.overLimit, handoffOverLimit: outHandoff.overLimit,
                    replyDropped: outReply.droppedChars, handoffDropped: outHandoff.droppedChars,
                    // The value messages.disclosure gets, built by the tested
                    // disclosureRecord() rather than re-spelled in an n8n
                    // expression where nothing would check the shape.
                    replyRow: outReply.applied ? disclosureRecord(discDecision.reason, discReplyLang) : null,
                    handoffRow: outHandoff.applied ? disclosureRecord(discDecision.reason, discHandoffLang) : null,
                  },
                  // Never the model's reply on this path: it claims a booking.
                  // A slot taken inside the confirm window gets its OWN message
                  // rather than the generic handoff: the lead chose a time and
                  // deserves to be told that specific thing happened to it.
                  handoffBody: lsHandover ? lostSlot.text : promisedButFailed ? RACE_NOTE : d.handoffBody,
                  handoffLang: lsHandover ? lostSlot.lang : promisedButFailed ? RACE_LANG : d.handoffLang } }];

// Nothing was attempted: not a confirmation, or escalation took priority.
return [{ json: { ...$('DecideEscalation').first().json,
                  bookingBranch: 'not_attempted', httpStatus: null, httpBody: null } }];

// The re-check ran and did not clear it: taken since it was offered, or the
// calendar could not be read. Either way, no event.
let rr = $('ReadRecheck').first().json;
// The listing step can also block the create; it carries the same fields.
try { const rs = $('ReadSlotEvents').first().json; if (rs && rs.recheckError) rr = rs; } catch (e) { /* listing not reached */ }
return [{ json: { ...$('DecideEscalation').first().json,
                  bookingBranch: 'blocked', recheckError: rr.recheckError,
                  httpStatus: null, httpBody: null } }];

// Lesson 12: this node follows an HTTP call, so $input IS the response
// envelope here -- which is exactly why it is read HERE and labelled, rather
// than guessed at downstream.
const res = $input.first().json;
return [{ json: { ...$('DecideEscalation').first().json,
                  bookingBranch: 'create_attempted',
                  httpStatus: res ? res.statusCode : null,
                  httpBody: res ? res.body : null } }];

// Same trap as the keepalive: a rejected send returns an item, not an error.
// This one must NOT throw -- the lead has already been handed off and the
// escalation still needs recording -- so the outcome is carried forward and
// written to the run payload, where it can be queried rather than inferred.
const res = $input.first().json;
const code = res && res.statusCode;
const ok = code >= 200 && code < 300;
return [{ json: { ...$('AfterNotify').first().json,
  emailAlertAttempted: true,
  emailAlertOk: ok,
  emailAlertError: ok ? null
    : ((res && res.error && res.error.message) || (res && res.body && res.body.message)
       || ('http_' + (code || 'none'))) } }];

// Who holds this slot?
//
//   ours       -> our own create landed but the database write did not. The
//                 lead does have a booking; treat as a replay, not a loss.
//   cancelled  -> the id belongs to a DELETED event. Google keeps deleted ids
//                 reserved, so the slot is free but this identifier is burned.
//                 That needs a human, and it must not be reported as "taken".
//   theirs     -> another lead got there first. This is the race, correctly
//                 lost, and the lead gets the slot_taken apology.
const d   = $('DecideEscalation').first().json;
const a   = $('AfterLead').first().json;
const res = $input.first().json || {};
const body = res.body || {};
const code = res.statusCode;

let conflict = 'unknown';
if (code >= 200 && code < 300) {
  const owner = ((body.extendedProperties || {}).private || {}).ryvoLeadId || null;
  if (body.status === 'cancelled') conflict = 'burned_id';
  else if (owner && owner === String(a.leadId)) conflict = 'ours';
  else conflict = 'theirs';
} else if (code === 404) {
  // Rejected as a duplicate, yet not readable: an id reserved by a purge.
  conflict = 'burned_id';
