  const full = pre + DISCLOSURE_SEP + b;
  if (full.length <= cap) return { text: full, applied: true, overLimit: false, droppedChars: 0 };

  const room = cap - pre.length - DISCLOSURE_SEP.length - 1;   // 1 for the ellipsis
