  'curto médio longo prazo cerca aproximadamente meio'
).split(' '));

function ocTimelineForeign(v) {
  const words = String(v || '').toLowerCase().split(/[^a-zà-ÿ]+/).filter(Boolean);
  return words.filter(w => !OC_PT_TIMELINE_WORDS.has(w));
