  // "6-12 months", "6 to 12 months", "6 a 12 meses"
  m = s.match(new RegExp('^(\\d+)\\s*(?:-|–|to|a)\\s*(\\d+)\\s+' + OC_UNIT_RX + '$'));
  if (m) { const u = ocUnit(m[2], m[3]); if (u) return m[1] + ' a ' + m[2] + ' ' + u; }
