const safe = (fn) => { try { const v = fn(); return v == null ? null : v; } catch (e) { return null; } };
const h   = safe(() => $('AfterHandoff').first().json) || {};
const al  = safe(() => $('AfterLead').first().json) || {};
const cfg = al.config || {};
const lu  = safe(() => $('AfterLeadUpdate').first().json) || {};
const bcr = safe(() => $('BuildClaudeRequest').first().json) || {};
const ab  = safe(() => $('AfterBooking').first().json) || {};
const rds = safe(() => $('ReadDisclosureState').first().json);
const lead = (lu.leadAfter && typeof lu.leadAfter === 'object') ? lu.leadAfter : (al.priorLead || {});
const q = lead.qualification || {};
const discRows = (rds && rds.statusCode >= 200 && rds.statusCode < 300 && Array.isArray(rds.body)) ? rds.body : null;
const discNow = !!(ab.disclosure && ab.disclosure.handoffApplied && h.handoffOk === true);
const past = Array.isArray(q.past_bookings) ? q.past_bookings : [];
const lastPast = past.length ? past[past.length - 1] : null;
// Which note the lead was actually sent: AfterBooking decides it (a lost race
// replaces the handoff), DecideEscalation's retired-booking note otherwise.
const noteKind = (ab.lostSlot && ab.lostSlot.outcome === 'handover') ? 'slot_taken'
               : ab.promisedButFailed ? (ab.bookingResult === 'slot_taken' ? 'slot_taken' : 'handoff')
               : (h.bookingRetiredNote ? 'booking_retired' : 'handoff');
// What the lead was SENT (25 Sep 2026): every outbound message in the history
// loaded this turn, and the note sent now. Only offered slots named there go on the card.
const histRows = (() => { const hh = safe(() => $('LoadHistory').first().json); return (hh && Array.isArray(hh.body)) ? hh.body : []; })();
const sentTexts = histRows.filter(r => r && r.direction === 'outbound').map(r => r.body)
  .concat([h.sendHandoffBody || h.handoffBody || '']);
const alert = operatorAlert({
  from: h.from, lead,
  lang: bcr.leadLang || null, langSource: bcr.leadLangSource || null,
  reasons: h.escalationReasons || [], escalationKind: h.escalationKind || null,
  propertyRefs: bcr.propertyRefs || [],
  disclosure: { at: (discRows && discRows[0]) ? discRows[0].created_at : null, now: discNow,
                unknown: discRows === null && !discNow },
  booking: { active: q.booking || null,
             retired: lastPast ? { startUtc: lastPast.startUtc, reason: lastPast.retired_reason } : null,
             proposed: ocProposedTold((q.proposed_slots && q.proposed_slots.slots) || [], sentTexts, slotsNamedIn) },
  note: { kind: noteKind, delivered: h.handoffOk === true ? true : (h.handoffOk === false ? false : null) },
  zone: cfg.timezone || 'Europe/Lisbon', at: new Date().toISOString(),
