// ---------------------------------------------------------------------------
const OC_PLACE_PT = { lisbon: 'Lisboa', oporto: 'Porto', seville: 'Sevilha', madeira: 'Madeira',
                      azores: 'Açores', 'the algarve': 'Algarve', algarve: 'Algarve' };
