function ocForeignWords(v) {
  const s = String(v || '').toLowerCase();
  const words = s.split(/[^a-zà-ÿ0-9]+/).filter(Boolean);
  const hits = words.filter(w => OC_FOREIGN.has(w));
  if (hits.length) return hits;
